function harness(respond: (query: TdObject) => TdObject | Promise<TdObject>, onDelete = vi.fn(),
  storage: string | Pick<Parameters<typeof createTelegram>[0], "directory" | "withMediaCacheTransfer" | "dolbyVisionTool" | "hdr10PlusTool" | "notifyHistoryMessageChanged"> = "fixture", onChatChanged = vi.fn(),
  channelPosts?: ChannelPostReceipts, privateHistory?: ReturnType<typeof createPrivateHistory>, notifyMessage?: Parameters<typeof createTelegram>[4],
  notifyActivity?: Parameters<typeof createTelegram>[6], notifyPresence?: Parameters<typeof createTelegram>[7], miniAppStorage?: ReturnType<typeof createMiniAppDeviceStorage>, miniAppSecureStorage?: ReturnType<typeof createMiniAppSecureStorage>,
  notifyMiniAppClosed?: (session: string) => void) {
  let update!: (event: TdObject) => void;
  const request = vi.fn(async (query: TdObject) => respond(query));
  const open: typeof connectTdJson = (_, onUpdate) => {
    update = onUpdate;
    return { request, close: async () => {} };
  };
  const session = createTelegram({ library: "fixture", ...(typeof storage === "string" ? { directory: storage } : storage),
    key: "fixture", apiId: 1, apiHash: "fixture", channelPosts,
    privateHistory, miniAppStorage, miniAppSecureStorage, notifyMiniAppClosed }, open, onChatChanged, onDelete, notifyMessage, undefined, notifyActivity, notifyPresence);
  function auth(type: string, fields: Record<string, unknown> = {}) {
    update({ "@type": "updateAuthorizationState", authorization_state: { "@type": type, ...fields } });
  }
  return { session, request, auth, update };
}

test("notifies history edits by identity and reloads one message in the same topic", async () => {
  const notifyHistoryMessageChanged = vi.fn();
  const { session, request, update } = harness((query) => {
    switch (query["@type"]) {
      case "getAuthorizationState": return { "@type": "authorizationStateReady" };
      case "getChat": return { "@type": "chat", id: query.chat_id, title: "Fixture forum" };
      case "getMessage": return { "@type": "message", chat_id: -42, id: 50, is_outgoing: true,
        date: 1700000000, edit_date: 1700000010, topic_id: { "@type": "messageTopicForum", forum_topic_id: 17 },
        content: { "@type": "messageText", text: { "@type": "formattedText", text: "Edited fixture text", entities: [] } } };
      default: throw new Error("Unexpected history edit fixture request");
    }
  }, undefined, { directory: "fixture", notifyHistoryMessageChanged });
  try {
    await vi.waitFor(() => expect(session.status().state).toBe("ready"));
    update({ "@type": "updateMessageContent", chat_id: -42, message_id: 50, new_content: { text: "Ignored update content" } });
    update({ "@type": "updateMessageEdited", chat_id: -42, message_id: -50 });
    expect(notifyHistoryMessageChanged).toHaveBeenCalledExactlyOnceWith({ id: "-42", messageId: "50" });
    await expect(session.historyMessage("-42", "50", 17)).resolves.toMatchObject({
      id: "50", forumTopicId: 17, editedAt: 1700000010, text: "Edited fixture text",
    });
    await expect(session.historyMessage("-42", "50", 18)).resolves.toBeNull();
    await expect(session.historyMessage("-42", "51", 17)).resolves.toBeNull();
    expect(request.mock.calls.filter(([query]) => query["@type"] === "getMessage").map(([query]) => query.message_id))
      .toEqual([50, 50, 51]);
    expect(request.mock.calls.some(([query]) =>
      ["getChatHistory", "getForumTopicHistory", "viewMessages", "openMessageContent"].includes(query["@type"] ?? ""))).toBe(false);
  } finally { await session.close(); }
});

test("lists only current contacts whose valid birthdays Telegram reported", async () => {
  const { session, request, update } = harness((query) => {
    if (query["@type"] === "getAuthorizationState") return { "@type": "authorizationStateReady" };
    if (query["@type"] === "getUser") return { "@type": "user", id: query.user_id, first_name: "Fixture contact", is_contact: query.user_id === 8 };
    throw new Error("Unexpected birthday fixture request");
  });
  const birthday = (user_id: number, day = 29) => ({ "@type": "closeBirthdayUser", user_id,
    birthdate: { "@type": "birthdate", day, month: 2, year: 2000 } });
  try {
    await vi.waitFor(() => expect(session.status().state).toBe("ready"));
    await expect(session.contactBirthdays()).resolves.toEqual([]);
    update({ "@type": "updateContactCloseBirthdays", close_birthday_users: [birthday(8), birthday(8), birthday(9), birthday(10, 30)] });
    await expect(session.contactBirthdays()).resolves.toEqual([{ id: "8", name: "Fixture contact", birthdate: { day: 29, month: 2, year: 0 } }]);
    expect(request.mock.calls.filter(([query]) => query["@type"] === "getUser")).toEqual([8, 9].map((user_id) => [{ "@type": "getUser", user_id }]));
    update({ "@type": "updateContactCloseBirthdays", close_birthday_users: [] });
    await expect(session.contactBirthdays()).resolves.toEqual([]);
  } finally { await session.close(); }
});

test("loads widget HTML on request from the exact current message only", async () => {
  const html = "<p>Fixture widget</p>";
  const raw = { "@type": "message", chat_id: 42, id: 7, can_be_saved: false,
    content: { "@type": "messageWidget", html, chat_data: "private fixture",
      caption: { "@type": "formattedText", text: "Widget caption", entities: [] }, show_caption_above_media: true } };
  let reply: TdObject = raw;
  const { session, request } = harness((query) => {
    if (query["@type"] === "getAuthorizationState") return { "@type": "authorizationStateReady" };
    if (query["@type"] === "getChat") return { "@type": "chat", id: 42 };
    if (query["@type"] === "getChatHistory") return { "@type": "messages", messages: [raw] };
    if (query["@type"] === "getMessage") return reply;
    throw new Error("Unexpected widget fixture query");
  });
  try {
    await vi.waitFor(() => expect(session.status().state).toBe("ready"));
    const { messages } = await session.history("42");
    expect(messages[0]).toMatchObject({ widget: true, text: "Widget caption", captionAboveMedia: true });
    expect(JSON.stringify(messages)).not.toMatch(/Fixture widget|private fixture/);
    expect(request).not.toHaveBeenCalledWith(expect.objectContaining({ "@type": "getMessage" }));
    await expect(session.messageWidgetPreview("42", "7")).resolves.toEqual({ html });
    await expect(session.messageWidgetPreview("43", "7")).resolves.toBeNull();
    await expect(session.messageWidgetPreview("42", "8")).resolves.toBeNull();
    reply = { ...raw, content: { ...raw.content, "@type": "messageText" } };
    await expect(session.messageWidgetPreview("42", "7")).resolves.toBeNull();
    reply = { ...raw, content: { ...raw.content, html: "я".repeat(16385) } };
    await expect(session.messageWidgetPreview("42", "7")).resolves.toBeNull();
  } finally { await session.close(); }
});

test("keeps Mini App location decisions separate by bot and account and resets only the chosen permission", () => {
  const db = new Database(":memory:");
  try {
    db.exec(miniAppLocationAccessMigration);
    const access = createMiniAppLocationAccess(db);
    expect(access("7", 54)).toBe("ask");
    expect(access("7", 54, "allowed")).toBe("allowed");
    expect(access("8", 54, "denied")).toBe("denied");
    expect(access("7", 55)).toBe("ask");
    expect(access("7", 54, "ask")).toBe("ask");
    expect(access("7", 54)).toBe("ask");
    expect(access("8", 54)).toBe("denied");
  } finally { db.close(); }
});

test("isolates Mini App device storage by account and bot and replaces values within its quota", () => {
  const db = new Database(":memory:");
  try {
    db.exec(miniAppDeviceStorageMigration);
    const storage = createMiniAppDeviceStorage(db);
    const save = (account: string, bot: number, key: string, value: string | null) => storage(account, bot, { kind: "save", key, value });
    const get = (account: string, bot: number, key: string) => storage(account, bot, { kind: "get", key });
    expect(save("7", 54, "a", "x".repeat(maxMiniAppDeviceStorageBytes - 2)).status).toBe("ok");
    expect(save("7", 54, "b", "🧪")).toEqual({ status: "failed", error: "QUOTA_EXCEEDED" });
    expect(save("7", 54, "a", "replacement").status).toBe("ok");
    expect(save("7", 54, "b", "🧪").status).toBe("ok");
    expect(get("8", 54, "a")).toEqual({ status: "ok", value: null });
    expect(get("7", 55, "a")).toEqual({ status: "ok", value: null });
    expect(save("8", 54, "a", "other account").status).toBe("ok");
    expect(save("7", 55, "a", "other bot").status).toBe("ok");
    expect(save("7", 54, "b", null).status).toBe("ok");
    expect(get("7", 54, "b")).toEqual({ status: "ok", value: null });
    expect(storage("7", 54, { kind: "clear" }).status).toBe("ok");
    expect(get("7", 54, "a")).toEqual({ status: "ok", value: null });
    expect(get("8", 54, "a")).toEqual({ status: "ok", value: "other account" });
    expect(get("7", 55, "a")).toEqual({ status: "ok", value: "other bot" });
  } finally { db.close(); }
});

