    await expect(session.quickReplyPhoto(2, 20, 63)).rejects.toThrow("Quick reply photo unavailable.");
    await expect(session.quickReplyPhoto(2, 20, 62)).rejects.toThrow("Photo download is incomplete.");
    expect(request.mock.calls.flatMap(([query]) => query["@type"] === "downloadFile" ? [query.file_id] : [])).toEqual([61]);
    const mediaShortcuts = await session.quickReplyMessages(3);
