    await expect(session.quickReplyDocumentName(3, 31, 65)).rejects.toThrow("Quick reply document unavailable.");
    await expect(session.quickReplyDocumentName(3, 30, 65)).rejects.toThrow("Quick reply document unavailable.");
    await expect(session.quickReplyPlaybackReference(3, 30, 66)).rejects.toThrow("Quick reply media unavailable.");
    await expect(session.quickReplyPlaybackReference(3, 30, 65)).resolves.toEqual({ id: 65, size: 1024, mime: "audio/ogg" });
    const revision = shortcutMessages[1]!.editRevision!;
