    await expect(session.deleteQuickReplyMessage(2, 20, "0".repeat(64), 2)).resolves.toBe("changed");
    await expect(session.deleteQuickReplyMessage(2, 20, deleteRevision, 2)).resolves.toBe("deleted");
    expect(request.mock.calls.flatMap(([query]) => query["@type"] === "deleteQuickReplyShortcutMessages" ? [query] : []))
