    await expect(session.editQuickReplyText(2, 10, "0".repeat(64), "Stale fixture")).resolves.toBe("changed");
    await expect(session.editQuickReplyText(2, 10, revision, "Second updated", [{ offset: 0, length: 6, style: "bold" }]))
