test("revalidates an inline Mini App button and closes its exact TDLib session", async () => {
  const app = "https://app.example.com/open";
  const label = "Fixture app";
  const revision = createHash("sha256").update(JSON.stringify([label, app])).digest("hex");
  let sender = 42;
  let requiresOrigin = false;
  let launchId = "9007199254740993";
  let corruptClose = false;
  const closed = vi.fn();
  const { session, request, update } = harness((query) => {
    switch (query["@type"]) {
      case "getAuthorizationState": return { "@type": "authorizationStateReady" };
      case "getChat": return { "@type": "chat", id: query.chat_id, type: { "@type": "chatTypePrivate", user_id: 42 } };
      case "getMessage": return { "@type": "message", chat_id: query.chat_id, id: query.message_id,
        sender_id: { "@type": "messageSenderUser", user_id: sender },
        reply_markup: { "@type": "replyMarkupInlineKeyboard", rows: [[{
          "@type": "inlineKeyboardButton", text: label, type: { "@type": "inlineKeyboardButtonTypeWebApp", url: app },
        }]] } };
      case "getUser": return { "@type": "user", id: 42, type: { "@type": "userTypeBot" } };
      case "openWebApp": return { "@type": "webAppInfo", launch_id: launchId,
        url: { "@type": "webAppUrl", url: app + "#fixture", require_same_origin: requiresOrigin } };
      case "closeWebApp":
        if (corruptClose) throw new TdTimeoutError();
        return { "@type": "ok" };
      default: throw new Error("Unexpected test query");
    }
  }, undefined, undefined, undefined, undefined, undefined, undefined, undefined, undefined, undefined, undefined, closed);
  try {
    await vi.waitFor(() => expect(session.status().state).toBe("ready"));
    await expect(session.launchInlineMiniApp("42", "51", 0, 0, "0".repeat(64))).resolves.toBeNull();
    sender = 43;
    await expect(session.launchInlineMiniApp("42", "51", 0, 0, revision)).resolves.toBeNull();
    expect(request.mock.calls.some(([query]) => query["@type"] === "openWebApp")).toBe(false);
    sender = 42;
    const opened = await session.launchInlineMiniApp("42", "51", 0, 0, revision);
    expect(opened).toMatchObject({ url: app + "#fixture", session: expect.any(String) });
    expect(request).toHaveBeenLastCalledWith(expect.objectContaining({ "@type": "openWebApp", chat_id: 42, bot_user_id: 42, url: app }));
    await expect(session.closeMiniApp(opened!.session)).resolves.toBe(true);
    await expect(session.closeMiniApp(opened!.session)).resolves.toBe(false);
    requiresOrigin = true;
    await expect(session.launchInlineMiniApp("42", "51", 0, 0, revision)).resolves.toBeNull();
    expect(request.mock.calls.map(([query]) => query).filter((query) => query["@type"] === "closeWebApp"))
      .toEqual(Array.from({ length: 2 }, () => ({ "@type": "closeWebApp", web_app_launch_id: "9007199254740993" })));
    requiresOrigin = false;
    launchId = "9007199254740995";
    const outstanding = await session.launchInlineMiniApp("42", "51", 0, 0, revision);
    expect(outstanding?.session).toBeTruthy();
    const sentLaunchId = "9007199254740997";
    const outstandingLaunchId = launchId;
    launchId = sentLaunchId;
    const sent = await session.launchInlineMiniApp("42", "51", 0, 0, revision);
    update({ "@type": "updateWebAppMessageSent", web_app_launch_id: 9007199254740997 });
    expect(closed).not.toHaveBeenCalled();
    update({ "@type": "updateWebAppMessageSent", web_app_launch_id: sentLaunchId });
    update({ "@type": "updateWebAppMessageSent", web_app_launch_id: sentLaunchId });
    expect(closed).toHaveBeenCalledExactlyOnceWith(sent!.session);
    expect(request).toHaveBeenLastCalledWith({ "@type": "closeWebApp", web_app_launch_id: sentLaunchId });
    await expect(session.closeMiniApp(sent!.session)).resolves.toBe(false);
    corruptClose = true;
    await expect(session.close()).resolves.toBeUndefined();
    expect(request).toHaveBeenLastCalledWith({ "@type": "closeWebApp", web_app_launch_id: outstandingLaunchId }, 1500);
    await expect(session.closeMiniApp(outstanding!.session)).resolves.toBe(false);
  } finally { await session.close(); }
});

