test("pauses, resumes and removes the Business bot only for the reviewed private chat", async () => {
  let paused = false;
  let removed = false;
  const { session, request } = harness((query) => {
    switch (query["@type"]) {
      case "getAuthorizationState": return { "@type": "authorizationStateReady" };
      case "getMe": return { "@type": "user", id: 77 };
      case "getChat": return { "@type": "chat", id: query.chat_id,
        type: { "@type": "chatTypePrivate", user_id: query.chat_id },
        business_bot_manage_bar: removed ? null : {
          "@type": "businessBotManageBar", bot_user_id: 54, is_bot_paused: paused, can_bot_reply: !paused,
        } };
      case "getUser": return { "@type": "user", id: 54, first_name: "Fixture bot",
        type: { "@type": "userTypeBot", can_connect_to_business: true } };
      case "toggleBusinessConnectedBotChatIsPaused": paused = query.is_paused === true; return { "@type": "ok" };
      case "removeBusinessConnectedBotFromChat": removed = true; return { "@type": "ok" };
      default: throw new Error("Unexpected test query");
    }
  });
  try {
    await vi.waitFor(() => expect(session.status().state).toBe("ready"));
    const current = await session.chatBusinessBot("42");
    expect(current).toMatchObject({ botId: "54", paused: false, canReply: true, identity: { name: "Fixture bot" } });
    await expect(session.changeChatBusinessBot("43", "remove", current!.revision)).resolves.toBe("changed");
    await expect(session.changeChatBusinessBot("42", "pause", current!.revision)).resolves.toBe("saved");
    await expect(session.changeChatBusinessBot("42", "remove", current!.revision)).resolves.toBe("changed");
    const suspended = await session.chatBusinessBot("42");
    expect(suspended).toMatchObject({ paused: true, canReply: false });
    await expect(session.changeChatBusinessBot("42", "resume", suspended!.revision)).resolves.toBe("saved");
    const resumed = await session.chatBusinessBot("42");
    await expect(session.changeChatBusinessBot("42", "remove", resumed!.revision)).resolves.toBe("saved");
    await expect(session.chatBusinessBot("42")).resolves.toBeNull();
    expect(request.mock.calls.map(([query]) => query).filter((query) =>
      query["@type"] === "toggleBusinessConnectedBotChatIsPaused" || query["@type"] === "removeBusinessConnectedBotFromChat")).toEqual([
      { "@type": "toggleBusinessConnectedBotChatIsPaused", chat_id: 42, is_paused: true },
      { "@type": "toggleBusinessConnectedBotChatIsPaused", chat_id: 42, is_paused: false },
      { "@type": "removeBusinessConnectedBotFromChat", chat_id: 42 },
    ]);
  } finally { await session.close(); }
});

test("connects a Business-capable bot with exactly the selected recipients and permissions", async () => {
  let bot: unknown;
  let compatible = true;
  const { session, request } = harness((query) => {
    switch (query["@type"]) {
      case "getAuthorizationState": return { "@type": "authorizationStateReady" };
      case "getBusinessConnectedBot":
        if (!bot) throw new TdError(404);
        return { "@type": "businessConnectedBotInfo", bot };
      case "getCurrentState": return { "@type": "updates", updates: [] };
      case "searchPublicChat": return { "@type": "chat", type: { "@type": "chatTypePrivate", user_id: 54 } };
      case "getUser": return { "@type": "user", id: 54, first_name: "Fixture",
        type: { "@type": "userTypeBot", can_connect_to_business: compatible },
        usernames: { "@type": "usernames", active_usernames: ["fixture_bot"] } };
      case "setBusinessConnectedBot": bot = query.bot; return { "@type": "ok" };
      case "deleteBusinessConnectedBot": bot = undefined; return { "@type": "ok" };
      default: throw new Error("Unexpected test query");
    }
  });
  try {
    await vi.waitFor(() => expect(session.status().state).toBe("ready"));
    expect(await session.findBusinessBot("fixture_bot")).toEqual({ id: "54", name: "Fixture", username: "fixture_bot" });
    const initial = await session.businessBot();
    expect(initial.connection).toBeNull();
    const connection = { botId: "54", excludedChats: ["51"], rights: ["can_reply" as const], recipients: {
      chats: ["42"], existing: true, newChats: false, contacts: false, nonContacts: false, exclude: false,
    } };
    compatible = false;
    await expect(session.saveBusinessBot(connection, initial.revision)).resolves.toBe("invalid");
    compatible = true;
    await expect(session.saveBusinessBot(connection, initial.revision)).resolves.toBe("saved");
    const saved = await session.businessBot();
    expect(saved.connection).toEqual(connection);
    const set = request.mock.calls.map(([query]) => query).find((query) => query["@type"] === "setBusinessConnectedBot");
    expect(set).toMatchObject({ bot: { bot_user_id: 54, recipients: { chat_ids: [42], excluded_chat_ids: [51] },
      rights: { can_reply: true, can_read_messages: false, can_transfer_stars: false, can_delete_all_messages: false } } });
    await expect(session.saveBusinessBot(null, initial.revision)).resolves.toBe("changed");
    await expect(session.saveBusinessBot(null, saved.revision)).resolves.toBe("saved");
    expect(request).toHaveBeenLastCalledWith({ "@type": "deleteBusinessConnectedBot", bot_user_id: 54 });
  } finally { await session.close(); }
});

test("confirms a pending Business bot only when its identity, authorization and access still match", async () => {
  let botId = 54;
  let requestBotId = 55;
  let requestDate = 1700000000;
  let pending = true;
  let canReply = false;
  const { session, request } = harness((query) => {
    switch (query["@type"]) {
      case "getAuthorizationState": return { "@type": "authorizationStateReady" };
      case "getBusinessConnectedBot": return { "@type": "businessConnectedBotInfo", bot: {
        "@type": "businessConnectedBot", bot_user_id: botId, recipients: {
          "@type": "businessRecipients", chat_ids: [42], excluded_chat_ids: [],
        }, rights: { "@type": "businessBotRights", can_reply: canReply },
      } };
      case "getUser": return { "@type": "user", id: botId, first_name: "Fixture",
        type: { "@type": "userTypeBot", can_connect_to_business: true } };
      case "getCurrentState": return { "@type": "updates", updates: pending ? [
        { "@type": "updateUnconfirmedSession", unconfirmed_session_count: 1, session: {
          "@type": "unconfirmedSession", type: { "@type": "sessionTypeConnectedBot", bot_user_id: requestBotId },
          date: requestDate, device_model: "Fixture device", location: "Fixture location",
        } },
      ] : [] };
      case "confirmBusinessConnectedBot":
        pending = false;
        return { "@type": "ok" };
      default: throw new Error("Unexpected fixture request");
    }
  });
  try {
    await vi.waitFor(() => expect(session.status().state).toBe("ready"));
    expect((await session.businessBot()).pending).toBeUndefined();
    requestBotId = botId;
    const first = (await session.businessBot()).pending!;
    expect(first).toMatchObject({ date: requestDate, device: "Fixture device", location: "Fixture location" });
    canReply = true;
    await expect(session.confirmBusinessBot(first.revision)).resolves.toBe("changed");
    const second = (await session.businessBot()).pending!;
    requestDate++;
    await expect(session.confirmBusinessBot(second.revision)).resolves.toBe("changed");
    const third = (await session.businessBot()).pending!;
    botId = 56;
    await expect(session.confirmBusinessBot(third.revision)).resolves.toBe("changed");
    botId = 54;
    expect(request.mock.calls.filter(([query]) => query["@type"] === "confirmBusinessConnectedBot")).toHaveLength(0);
    await expect(Promise.all([session.confirmBusinessBot(third.revision), session.confirmBusinessBot(third.revision)]))
      .resolves.toEqual(["saved", "unavailable"]);
    await expect(session.confirmBusinessBot(third.revision)).resolves.toBe("changed");
    expect(request.mock.calls.filter(([query]) => query["@type"] === "confirmBusinessConnectedBot")).toEqual([
      [{ "@type": "confirmBusinessConnectedBot", bot_user_id: 54 }],
    ]);
  } finally { await session.close(); }
});

