test("round-trips the Business away schedules and disables the auto-reply", async () => {
  const { session, request } = harness((query) => {
    switch (query["@type"]) {
      case "getAuthorizationState": return { "@type": "authorizationStateReady" };
      case "getMe": return { "@type": "user", id: 7, is_premium: true };
      case "getUserFullInfo": return { "@type": "userFullInfo", business_info: { "@type": "businessInfo", away_message_settings: saved } };
      case "loadQuickReplyShortcuts": return { "@type": "ok" };
      case "getCurrentState": return { "@type": "updates", updates: [
        { "@type": "updateQuickReplyShortcut", shortcut: { "@type": "quickReplyShortcut", id: 2, name: "away", message_count: 1 } },
        { "@type": "updateQuickReplyShortcuts", shortcut_ids: [2] },
      ] };
      case "setBusinessAwayMessageSettings":
        saved = query.away_message_settings;
        return { "@type": "ok" };
      default: throw new Error("Unexpected test query");
    }
  });
  let saved: unknown = null;
  try {
    await vi.waitFor(() => expect(session.status().state).toBe("ready"));
    const initial = await session.businessAway();
    expect(initial?.away).toBeNull();
    const recipients = { chats: ["42"], existing: false, newChats: true, contacts: false, nonContacts: false, exclude: false };
    const custom = { kind: "custom", start: 1800000000, end: 1800003600 } as const;
    const away = { shortcutId: 2, offlineOnly: true, recipients, schedule: custom };
    await expect(session.saveBusinessAway(away, "0".repeat(64))).resolves.toBe("changed");
    expect(request.mock.calls.some(([query]) => query["@type"] === "setBusinessAwayMessageSettings")).toBe(false);
    for (const [schedule, expected] of [
      [custom, { "@type": "businessAwayMessageScheduleCustom", start_date: custom.start, end_date: custom.end }],
      [{ kind: "always" }, { "@type": "businessAwayMessageScheduleAlways" }],
      [{ kind: "outside" }, { "@type": "businessAwayMessageScheduleOutsideOfOpeningHours" }],
    ] as const) {
      const current = await session.businessAway();
      const next = { ...away, schedule };
      await expect(session.saveBusinessAway(next, current!.revision)).resolves.toBe("saved");
      expect(saved).toEqual({ "@type": "businessAwayMessageSettings", shortcut_id: 2, offline_only: true,
        schedule: expected, recipients: { "@type": "businessRecipients", chat_ids: [42], excluded_chat_ids: [],
          select_existing_chats: false, select_new_chats: true, select_contacts: false, select_non_contacts: false, exclude_selected: false },
      });
      expect((await session.businessAway())?.away).toEqual(next);
    }
    const current = await session.businessAway();
    await expect(session.saveBusinessAway(null, current!.revision)).resolves.toBe("saved");
    expect((await session.businessAway())?.away).toBeNull();
  } finally { await session.close(); }
});

