test("manages owned Business chat links with formatted drafts and rechecks the reviewed link", async () => {
  const url = "https://t.me/m/Fixture-1";
  const text = { "@type": "formattedText", text: "Hello", entities: [
    { "@type": "textEntity", offset: 0, length: 5, type: { "@type": "textEntityTypeBold" } },
  ] };
  let premium = true;
  let link = { "@type": "businessChatLink", link: url, title: "Original", text, view_count: 7 };
  const { session, request } = harness((query) => {
    switch (query["@type"]) {
      case "getAuthorizationState": return { "@type": "authorizationStateReady" };
      case "getMe": return { "@type": "user", id: 7, is_premium: premium };
      case "getBusinessChatLinks": return { "@type": "businessChatLinks", links: [
        link, { ...link, link: "https://example.com/m/invalid" },
      ] };
      case "editBusinessChatLink":
        link = { ...link, title: "Renamed" };
        return link;
      case "createBusinessChatLink": return { ...link, link: "https://t.me/m/Fixture-2", title: "New" };
      case "deleteBusinessChatLink": return { "@type": "ok" };
      default: throw new Error("Unexpected fixture request");
    }
  });
  try {
    await vi.waitFor(() => expect(session.status().state).toBe("ready"));
    const result = await session.businessChatLinks();
    expect(result).toMatchObject({ canEdit: true, links: [{ url, title: "Original", views: 7,
      message: { text: "Hello", styles: [{ offset: 0, length: 5, style: "bold" }] }, messageEditable: true }] });
    const { revision } = result.links[0]!;
    link = { ...link, view_count: 8 };
    await expect(session.changeBusinessChatLink({ action: "edit", title: "Renamed", url, revision })).resolves.toBe("saved");
    expect(request).toHaveBeenCalledWith({ "@type": "editBusinessChatLink", link: url,
      link_info: { "@type": "inputBusinessChatLink", title: "Renamed", text } });
    await expect(session.changeBusinessChatLink({ action: "delete", url, revision })).resolves.toBe("changed");
    const refreshed = await session.businessChatLinks();
    await expect(session.changeBusinessChatLink({ action: "create", title: "New", message: {
      text: "Open", links: [{ offset: 0, length: 4, url: "https://example.com/" }],
    } })).resolves.toBe("saved");
    expect(request).toHaveBeenCalledWith({ "@type": "createBusinessChatLink", link_info: {
      "@type": "inputBusinessChatLink", title: "New", text: { "@type": "formattedText", text: "Open", entities: [
        { "@type": "textEntity", offset: 0, length: 4, type: { "@type": "textEntityTypeTextUrl", url: "https://example.com/" } },
      ] },
    } });
    await expect(session.changeBusinessChatLink({ action: "create", title: "Invalid",
      message: { text: "Short", styles: [{ offset: 3, length: 8, style: "bold" }] },
    })).resolves.toBe("invalid");
    premium = false;
    await expect(session.changeBusinessChatLink({ action: "create", title: "Unavailable", message: { text: "" } })).resolves.toBe("unavailable");
    await expect(session.changeBusinessChatLink({ action: "delete", url, revision: refreshed.links[0]!.revision })).resolves.toBe("deleted");
    expect(request.mock.calls.filter(([query]) => query["@type"] === "deleteBusinessChatLink")).toEqual([
      [{ "@type": "deleteBusinessChatLink", link: url }],
    ]);
  } finally { await session.close(); }
});

test("saves a Business start page with the original sticker and respects changed settings", async () => {
  const { session, request } = harness((query) => {
    switch (query["@type"]) {
      case "getAuthorizationState": return { "@type": "authorizationStateReady" };
      case "getMe": return { "@type": "user", id: 7, is_premium: true };
      case "getUserFullInfo": return { "@type": "userFullInfo", business_info: { "@type": "businessInfo",
        start_page: { "@type": "businessStartPage", title: "Welcome", message: "Fixture",
          sticker: { "@type": "sticker", sticker: { "@type": "file", id: 75 } } },
      } };
      case "getOption": return { "@type": "optionValueInteger",
        value: query.name === "business_start_page_title_length_max" ? 32 : 96 };
      case "setBusinessStartPage": return { "@type": "ok" };
      case "getInstalledStickerSets": return { "@type": "stickerSets", sets: [
        { "@type": "stickerSetInfo", id: "81", title: "Fixture", is_installed: true,
          sticker_type: { "@type": "stickerTypeRegular" } },
      ] };
      case "getStickerSet": return { "@type": "stickerSet", id: "81", is_installed: true,
        sticker_type: { "@type": "stickerTypeRegular" }, stickers: [
          { "@type": "sticker", set_id: "81", sticker: { "@type": "file", id: 77 },
            full_type: { "@type": "stickerFullTypeRegular" } },
        ] };
      default: throw new Error("Unexpected test query");
    }
  });
  try {
    await vi.waitFor(() => expect(session.status().state).toBe("ready"));
    const view = await session.businessStartPage();
    expect(view).toMatchObject({ title: "Welcome", message: "Fixture", titleLimit: 32, messageLimit: 96,
      hasSticker: true, editable: true });
    await expect(session.saveBusinessStartPage("Hello", "Updated", "0".repeat(64))).resolves.toBe("changed");
    await expect(session.saveBusinessStartPage("x".repeat(33), "Updated", view!.revision)).resolves.toBe("invalid");
    await expect(session.saveBusinessStartPage("Hello", "Updated", view!.revision)).resolves.toBe("saved");
    await expect(session.saveBusinessStartPage("Hello", "Updated", view!.revision, { packId: "81", fileId: 78 })).resolves.toBe("invalid");
    await expect(session.saveBusinessStartPage("Hello", "Updated", view!.revision, { packId: "81", fileId: 77 })).resolves.toBe("saved");
    await expect(session.saveBusinessStartPage("Hello", "Updated", view!.revision, null)).resolves.toBe("saved");
    expect(request.mock.calls.flatMap(([query]) => query["@type"] === "setBusinessStartPage" ? [query] : []))
      .toEqual([{ "@type": "setBusinessStartPage", start_page: { "@type": "inputBusinessStartPage",
        title: "Hello", message: "Updated", sticker: { "@type": "inputFileId", id: 75 },
      } }, { "@type": "setBusinessStartPage", start_page: { "@type": "inputBusinessStartPage",
        title: "Hello", message: "Updated", sticker: { "@type": "inputFileId", id: 77 },
      } }, { "@type": "setBusinessStartPage", start_page: { "@type": "inputBusinessStartPage",
        title: "Hello", message: "Updated", sticker: null,
      } }]);
  } finally { await session.close(); }
});

