test("loads a TGS sticker only from the requested quick reply and message", async () => {
  const directory = await mkdtemp(join(tmpdir(), "bb-quick-reply-tgs-"));
  const sticker = { v: "5.7.4", w: 512, h: 512, fr: 60, ip: 0, op: 180, layers: [{ ty: 4, ind: 1, shapes: [] }] };
  const bytes = gzipSync(JSON.stringify(sticker));
  const path = join(directory, "sticker.tgs");
  await writeFile(path, bytes);
  const { session, request } = harness((query) => {
    switch (query["@type"]) {
      case "getAuthorizationState": return { "@type": "authorizationStateReady" };
      case "getMe": return { "@type": "user", id: 7 };
      case "loadQuickReplyShortcutMessages": return { "@type": "ok" };
      case "getCurrentState": return { "@type": "updates", updates: [
        { "@type": "updateQuickReplyShortcutMessages", shortcut_id: 4, messages: [
          { "@type": "quickReplyMessage", id: 8, content: { "@type": "messageSticker", sticker: { "@type": "sticker",
            format: { "@type": "stickerFormatTgs" }, sticker: { "@type": "file", id: 12, size: bytes.length },
          } } },
        ] },
      ] };
      case "downloadFile": return { "@type": "file", id: query.file_id,
        local: { "@type": "localFile", path, is_downloading_completed: true } };
      default: throw new Error("Unexpected fixture query");
    }
  }, undefined, directory);
  try {
    await vi.waitFor(() => expect(session.status().state).toBe("ready"));
    await expect(session.quickReplyMessages(4)).resolves.toMatchObject([{ id: 8, tgsStickerFileId: 12 }]);
    await expect(session.quickReplyTgsSticker(4, 8, 13)).rejects.toThrow("Quick reply sticker unavailable.");
    await expect(session.quickReplyTgsSticker(4, 9, 12)).rejects.toThrow("Quick reply sticker unavailable.");
    expect(request.mock.calls.flatMap(([query]) => query["@type"] === "downloadFile" ? [query.file_id] : [])).toEqual([]);
    expect(JSON.parse(await session.quickReplyTgsSticker(4, 8, 12))).toEqual(sticker);
    expect(request.mock.calls.flatMap(([query]) => query["@type"] === "downloadFile" ? [query.file_id] : [])).toEqual([12]);
  } finally {
    await session.close();
    await rm(directory, { recursive: true, force: true });
  }
});

test.each([
  { state: "messageSendingStatePending", expected: "submitted" },
  { state: "messageSendingStateFailed", expected: "invalid" },
])("handles staged quick reply photos in TDLib state $state", async ({ state, expected }) => {
  const directory = await mkdtemp(join(tmpdir(), "bb-quick-photo-"));
  const jpeg = Buffer.from([0xff, 0xd8, 0xff, 0xc0, 0, 8, 8, 0, 1, 0, 1, 1, 0xff, 0xd9]);
  const file = { "@type": "file", id: 33, remote: { "@type": "remoteFile", is_uploading_completed: false } };
  let path = "";
  const { session, update } = harness((query) => {
    switch (query["@type"]) {
      case "getAuthorizationState": return { "@type": "authorizationStateReady" };
      case "getMe": return { "@type": "user", id: 7 };
      case "getOption": return { "@type": "optionValueString", value: "1.8.70" };
      case "checkQuickReplyShortcutName":
      case "loadQuickReplyShortcuts": return { "@type": "ok" };
      case "getCurrentState": return { "@type": "updates", updates: [
        { "@type": "updateQuickReplyShortcuts", shortcut_ids: [] },
      ] };
      case "addQuickReplyShortcutMessage": {
        const content = query.input_message_content as TdObject;
        expect(content).toMatchObject({ "@type": "inputMessagePhoto",
          photo: { "@type": "inputPhoto", width: 1, height: 1 },
          has_spoiler: true, show_caption_above_media: true,
          caption: { text: "Fixture caption", entities: [{ offset: 0, length: 7, type: { "@type": "textEntityTypeBold" } }] },
        });
        path = String(((content.photo as TdObject).photo as TdObject).path);
        return { "@type": "quickReplyMessage", id: 42, sending_state: { "@type": state },
          content: { "@type": "messagePhoto", photo: { "@type": "photo", sizes: [
            { "@type": "photoSize", width: 1, height: 1, photo: file },
          ] } },
        };
      }
      case "getFile": return file;
      default: throw new Error("Unexpected test query");
    }
  }, undefined, directory);
  try {
    await vi.waitFor(() => expect(session.status().state).toBe("ready"));
    await expect(session.addQuickReplyPhoto("welcome", "Fixture caption", jpeg.toString("base64"), undefined,
      [{ offset: 0, length: 7, style: "bold" }], [], { spoiler: true, captionAbove: true })).resolves.toBe(expected);
    expect(path).not.toBe("");
    if (state === "messageSendingStatePending") {
      expect(await readFile(path)).toEqual(jpeg);
      update({ "@type": "updateFile", file: { ...file, remote: { ...file.remote, is_uploading_completed: true } } });
    }
    await vi.waitFor(() => expect(existsSync(path)).toBe(false));
  } finally {
    await session.close();
    await rm(directory, { recursive: true, force: true });
  }
});

test("adds photos in one quick reply album and keeps staging until all uploads finish", async () => {
  const directory = await mkdtemp(join(tmpdir(), "bb-quick-album-"));
  const image = (width: number) => Buffer.from([0xff, 0xd8, 0xff, 0xc0, 0, 8, 8, 0, 1, 0, width, 1, 0xff, 0xd9]).toString("base64");
  const files = [33, 34].map((id) => ({ "@type": "file", id, remote: { "@type": "remoteFile", is_uploading_completed: false } }));
  const paths: string[] = [];
  const { session, request, update } = harness((query) => {
    switch (query["@type"]) {
      case "getAuthorizationState": return { "@type": "authorizationStateReady" };
      case "getMe": return { "@type": "user", id: 7 };
      case "getOption": return { "@type": "optionValueString", value: "1.8.99" };
      case "checkQuickReplyShortcutName":
      case "loadQuickReplyShortcuts": return { "@type": "ok" };
      case "getCurrentState": return { "@type": "updates", updates: [{ "@type": "updateQuickReplyShortcuts", shortcut_ids: [] }] };
      case "addQuickReplyShortcutMessageAlbum": {
        const contents = query.input_message_contents as TdObject[];
        expect(query.shortcut_name).toBe("album");
        expect(contents).toMatchObject([
          { "@type": "inputMessagePhoto", photo: { "@type": "inputPhoto", width: 2 }, caption: { text: "Album fixture" },
            has_spoiler: true, show_caption_above_media: true },
          { "@type": "inputMessagePhoto", photo: { "@type": "inputPhoto", width: 1 }, caption: { text: "" }, has_spoiler: true },
        ]);
        expect(contents[1]).not.toHaveProperty("show_caption_above_media");
        paths.push(...contents.map((row) => String(((row.photo as TdObject).photo as TdObject).path)));
        return { "@type": "quickReplyMessages", messages: files.map((file, index) => ({
          "@type": "quickReplyMessage", id: index + 1, media_album_id: "8", sending_state: { "@type": "messageSendingStatePending" },
          content: { "@type": "messagePhoto", photo: { "@type": "photo", sizes: [
            { "@type": "photoSize", width: 1, height: 1, photo: file },
          ] } },
        })) };
      }
      case "getFile": return files.find((file) => file.id === query.file_id)!;
      default: throw new Error("Unexpected fixture query");
    }
  }, undefined, directory);
  try {
    await vi.waitFor(() => expect(session.status().state).toBe("ready"));
    await expect(session.addQuickReplyPhotoAlbum("album", "", [image(1)])).resolves.toEqual({ state: "failed" });
    await expect(session.addQuickReplyPhotoAlbum("album", "Album fixture", [image(2), image(1)], undefined, [], [],
      { spoiler: true, captionAbove: true })).resolves.toEqual({ state: "submitted" });
    expect(request.mock.calls.filter(([query]) => query["@type"] === "addQuickReplyShortcutMessageAlbum")).toHaveLength(1);
    expect(paths.every(existsSync)).toBe(true);
    const finish = (index: number) => update({ "@type": "updateFile", file: {
      ...files[index], remote: { ...files[index]!.remote, is_uploading_completed: true },
    } });
    finish(0);
    expect(paths.every(existsSync)).toBe(true);
    finish(1);
    await vi.waitFor(() => expect(paths.some(existsSync)).toBe(false));
  } finally {
    await session.close();
    await rm(directory, { recursive: true, force: true });
  }
});

test("clears only the reviewed date range and removes matching private copies after Telegram confirms", async () => {
  const db = new Database(":memory:");
  db.exec(privateHistoryMigration);
  db.exec(privateMediaMigration);
  const archive = createPrivateHistory(db, Buffer.alloc(32, 7).toString("base64"));
  const from = 1_700_000_050;
  const to = from + 100;
  const copy = (id: string, timestamp: number) => ({ id, timestamp, author: "Fixture", time: "", text: "Synthetic snapshot" });
  archive.save("7", "42", [copy("11", from - 1), copy("12", from), copy("13", to), copy("14", to + 1)]);
  archive.save("7", "43", [copy("21", from)]);
  for (const id of ["11", "12", "13", "14"]) archive.mark("7", "42", id, "deleted");
  archive.mark("7", "43", "21", "deleted");
  let kind = "chatTypePrivate";
  let accepted = false;
  const onDelete = vi.fn();
  const { session, request } = harness((query) => {
    switch (query["@type"]) {
      case "getAuthorizationState": return { "@type": "authorizationStateReady" };
      case "getMe": return { "@type": "user", id: 7 };
      case "getChat": return { "@type": "chat", id: query.chat_id, type: { "@type": kind },
        can_be_deleted_only_for_self: true, can_be_deleted_for_all_users: true };
      case "deleteChatMessagesByDate":
        if (!accepted) throw new TdError(403);
        return { "@type": "ok" };
      default: throw new Error("Unexpected fixture query");
    }
  }, onDelete, undefined, undefined, undefined, archive);
  const range = { start: from, end: to };
  const purged = () => archive.page("7", "42", 0, 0).map(({ id }) => id);
  const calls = () => request.mock.calls.map(([query]) => query).filter((query) => query["@type"] === "deleteChatMessagesByDate");
  try {
    await vi.waitFor(() => expect(session.status().state).toBe("ready"));
    kind = "chatTypeBasicGroup";
    await expect(session.clearChatDateScopes("-42")).resolves.toEqual(["self"]);
    await expect(session.clearChatByDate("-42", range, "everyone")).resolves.toBe("refused");
    kind = "chatTypeSupergroup";
    await expect(session.clearChatDateScopes("-42")).resolves.toEqual([]);
    await expect(session.clearChatByDate("-42", range, "self")).resolves.toBe("refused");
    expect(calls()).toEqual([]);
    kind = "chatTypePrivate";
    await expect(session.clearChatDateScopes("42")).resolves.toEqual(["self", "everyone"]);
    await expect(session.clearChatByDate("42", range, "self")).resolves.toBe("refused");
    expect(purged()).toEqual(["14", "13", "12", "11"]);
    accepted = true;
    await expect(session.clearChatByDate("42", range, "everyone")).resolves.toBe("deleted");
    expect(calls()).toEqual([false, true].map((revoke) => ({
      "@type": "deleteChatMessagesByDate", chat_id: 42, min_date: from, max_date: to, revoke,
    })));
    expect(onDelete).toHaveBeenCalledExactlyOnceWith({ id: "42", messageIds: ["12", "13"] });
    expect(purged()).toEqual(["14", "11"]);
    expect(archive.page("7", "43", 0, 0)).toHaveLength(1);
  } finally { await session.close(); db.close(); }
});

test("keeps observed incoming private messages through deletion, expiry and reconnect", async () => {
  const db = new Database(":memory:");
  db.exec(privateHistoryMigration);
  db.exec(privateMediaMigration);
  const key = Buffer.alloc(32, 7).toString("base64");
  const incoming: TdObject = {
    "@type": "message", id: 12, chat_id: 42, is_outgoing: false, date: 42,
    content: { "@type": "messageText", text: { "@type": "formattedText", text: "Private fixture" } },
  };
  const picture: TdObject = { ...incoming, id: 13, self_destruct_type: { "@type": "messageSelfDestructTypeImmediately" },
    content: { "@type": "messagePhoto", caption: { "@type": "formattedText", text: "Disappearing caption fixture" } } };
  let history: TdObject[] = [picture, incoming];
  const respond = (query: TdObject): TdObject => {
    switch (query["@type"]) {
      case "getAuthorizationState": return { "@type": "authorizationStateReady" };
      case "getMe": return { "@type": "user", id: 7 };
      case "getChat": return { "@type": "chat", id: query.chat_id, title: "Fixture", type: { "@type": "chatTypePrivate" } };
      case "getChatHistory": return { "@type": "messages", messages: history };
      default: throw new Error("Unexpected test query");
    }
  };
  const onDelete = vi.fn();
  const open = () => harness(respond, onDelete, undefined, undefined, undefined, createPrivateHistory(db, key));
  const { session, update } = open();
  try {
    await vi.waitFor(() => expect(session.status().state).toBe("ready"));
    await session.history("42");
    update({ "@type": "updateDeleteMessages", chat_id: 42, message_ids: [12, 999], is_permanent: true });
    update({ "@type": "updateMessageContent", chat_id: 42, message_id: 13, new_content: { "@type": "messageExpiredPhoto" } });
    await vi.waitFor(() => expect(onDelete).toHaveBeenCalledTimes(2));
    expect(onDelete).toHaveBeenNthCalledWith(1, {
      id: "42", messageIds: ["999"], retained: [expect.objectContaining({ id: "12", text: "Private fixture", retained: "deleted" })],
    });
    expect(onDelete).toHaveBeenNthCalledWith(2, {
      id: "42", messageIds: [], retained: [expect.objectContaining({ id: "13", text: "Disappearing media", retained: "expired" })],
    });
    history = [];
    await session.close();
    const reopened = open().session;
    try {
      await vi.waitFor(() => expect(reopened.status().state).toBe("ready"));
      await expect(reopened.history("42")).resolves.toMatchObject({ messages: [
        { id: "12", text: "Private fixture", retained: "deleted" }, { id: "13", text: "Disappearing media", retained: "expired" },
      ] });
      expect((await reopened.history("43")).messages).toEqual([]);
    } finally { await reopened.close(); }
    const persisted = db.prepare<[], { snapshot: Buffer }>("SELECT snapshot FROM telegram_private_history").all();
    expect(persisted.every(({ snapshot }) => !snapshot.includes(Buffer.from("fixture")))).toBe(true);
  } finally {
    await session.close();
    db.close();
  }
});

test.each(["photo", "video"] as const)("saves one-view %s on explicit view and reopens it after expiry and reconnect", async (kind) => {
  const directory = await mkdtemp(join(tmpdir(), "bb-telegram-once-"));
  const path = join(directory, "media");
  const bytes = Buffer.concat([Buffer.from([0xff, 0xd8, 0xff]), Buffer.from("synthetic one-view media fixture")]);
  await writeFile(path, bytes);
  const db = new Database(":memory:");
  db.exec(privateHistoryMigration);
  db.exec(privateMediaMigration);
  const key = Buffer.alloc(32, 8).toString("base64");
  const file = { "@type": "file", id: 51, size: bytes.length };
  const photo = { "@type": "messagePhoto", photo: { "@type": "photo", sizes: [
    { "@type": "photoSize", width: 20, height: 20, photo: file },
  ] } };
  const video = { "@type": "messageVideo", video: { "@type": "video", video: file, mime_type: "video/mp4" } };
  const raw: TdObject = {
    "@type": "message", id: 15, chat_id: 42, is_outgoing: false, can_be_saved: false,
    self_destruct_type: { "@type": "messageSelfDestructTypeImmediately" },
    content: { ...(kind === "photo" ? photo : video), is_secret: true },
  };
  let expired = false;
  let refuse = true;
  const respond = (query: TdObject): TdObject => {
    switch (query["@type"]) {
      case "getAuthorizationState": return { "@type": "authorizationStateReady" };
      case "getMe": return { "@type": "user", id: 7 };
      case "getChat": return { "@type": "chat", id: query.chat_id, type: { "@type": query.chat_id === 42 ? "chatTypePrivate" : "chatTypeSecret" } };
      case "getChatHistory": return { "@type": "messages", messages: expired ? [] : [raw] };
      case "getMessage": if (!expired) return raw; throw new Error("Media expired");
      case "downloadFile": return { ...file, local: { "@type": "localFile", is_downloading_completed: true, path } };
      case "openMessageContent":
        if (refuse) throw new Error("View refused");
        expired = true;
        return { "@type": "ok" };
      default: throw new Error("Unexpected test query");
    }
  };
  const open = () => harness(respond, undefined, directory, undefined, undefined, createPrivateHistory(db, key));
  const { session, request } = open();
  const signal = new AbortController().signal;
  try {
    await vi.waitFor(() => expect(session.status().state).toBe("ready"));
    const preview = await session.history("42");
    expect(preview).toMatchObject({ messages: [{ id: "15", oneView: kind }] });
    expect(preview).toStrictEqual(JSON.parse(JSON.stringify(preview)));
    expect(request.mock.calls.map(([query]) => query["@type"])).not.toContain("downloadFile");
    await expect(session.openOneView("43", "15", signal)).rejects.toThrow("unavailable");
    await expect(session.openOneView("42", "15", signal)).rejects.toThrow("View refused");
    expect(db.prepare("SELECT media FROM telegram_private_history").get()).toEqual({ media: null });
    refuse = false;
    const mime = kind === "photo" ? "image/jpeg" : "video/mp4";
    await expect(session.openOneView("42", "15", signal)).resolves.toEqual({ bytes, mime });
    expect(request.mock.calls.map(([query]) => query["@type"])).not.toContain("sendChatScreenshotTakenNotification");
    const persisted = db.prepare<[], { media: Buffer }>("SELECT media FROM telegram_private_history").get();
    expect(persisted?.media.includes(bytes)).toBe(false);
    await session.close();
    await rm(path);
    const reopened = open();
    try {
      await vi.waitFor(() => expect(reopened.session.status().state).toBe("ready"));
      await expect(reopened.session.history("42")).resolves.toMatchObject({ messages: [{ oneView: kind, retained: "expired" }] });
      await expect(reopened.session.openOneView("42", "15", signal)).resolves.toEqual({ bytes, mime });
      expect(reopened.request.mock.calls.map(([query]) => query["@type"])).not.toContain("openMessageContent");
    } finally { await reopened.session.close(); }
  } finally {
    await session.close();
    db.close();
    await rm(directory, { recursive: true, force: true });
  }
});

function cacheDownloadQueue(active = 0, paused = 0): TdObject {
  return { "@type": "foundFileDownloads", files: [],
    total_counts: { "@type": "downloadedFileCounts", active_count: active, paused_count: paused, completed_count: 0 } };
}

test("counts cached media without database bytes and clears through TDLib without reconnecting", async () => {
  let bytes = 900 * 1024 * 1024;
  const { session, request } = harness((query) => {
    switch (query["@type"]) {
      case "getAuthorizationState": return { "@type": "authorizationStateReady" };
      case "searchFileDownloads": return cacheDownloadQueue();
      case "getStorageStatistics": return { "@type": "storageStatistics", size: bytes, count: 3, by_chat: bytes === 900 * 1024 * 1024 ? [
        { "@type": "storageStatisticsByChat", chat_id: 0, by_file_type: [
          { "@type": "storageStatisticsByFileType", file_type: { "@type": "fileTypeVideo" }, size: 560 * 1024 * 1024 },
          { "@type": "storageStatisticsByFileType", file_type: { "@type": "fileTypeProfilePhoto" }, size: 40 * 1024 * 1024 },
        ] },
      ] : [] };
      case "optimizeStorage":
        bytes = (query.file_types as TdObject[]).some((type) => type["@type"] === "fileTypeWallpaper") ? Number(query.size) : 340 * 1024 * 1024;
        return { "@type": "storageStatistics", size: bytes, count: 0 };
      default: throw new Error("Unexpected TDLib request");
    }
  });
  await vi.waitFor(() => expect(session.status()).toEqual({ state: "ready" }));
  expect(await session.cacheUsage()).toEqual({ bytes: 900 * 1024 * 1024, breakdown: [
    { category: "videos", bytes: 560 * 1024 * 1024 },
    { category: "other", bytes: 300 * 1024 * 1024 },
    { category: "previews", bytes: 40 * 1024 * 1024 },
  ] });
  await expect(session.optimizeCache(0, { category: "videos" })).resolves.toEqual({ bytes: 340 * 1024 * 1024 });
  await expect(session.optimizeCache(512 * 1024 * 1024)).resolves.toEqual({ bytes: 512 * 1024 * 1024 });
  await expect(session.optimizeCache(0)).resolves.toEqual({ bytes: 0 });
  expect(await session.cacheUsage()).toEqual({ bytes: 0 });
  const optimizations = request.mock.calls.filter(([query]) => query["@type"] === "optimizeStorage").map(([query]) => query);
  expect(optimizations).toEqual([
    expect.objectContaining({ size: 0, immunity_delay: 0, file_types: [
      { "@type": "fileTypeVideo" }, { "@type": "fileTypeVideoNote" }, { "@type": "fileTypeAnimation" },
    ] }),
    expect.objectContaining({ size: 512 * 1024 * 1024, immunity_delay: 60 }),
    expect.objectContaining({ size: 0, immunity_delay: 0,
      file_types: expect.arrayContaining([{ "@type": "fileTypePhoto" }, { "@type": "fileTypeProfilePhoto" }, { "@type": "fileTypeThumbnail" }]) }),
  ]);
  expect(request.mock.calls.some(([query]) => ["logOut", "close", "destroy"].includes(query["@type"]))).toBe(false);
  expect(session.status()).toEqual({ state: "ready" });
});

test("searches within one granted forum scope and filters mixed, protected and out-of-range results", async () => {
  let protectAfterLookup = false;
  let protectedChat = false;
  const topic = (forum_topic_id: number) => ({ "@type": "messageTopicForum", forum_topic_id });
  const row = (id: number, date: number, sender: number, override: Partial<TdObject> = {}) => ({
    "@type": "message", chat_id: -42, id, date, topic_id: topic(17),
    sender_id: { "@type": "messageSenderUser", user_id: sender },
    content: { "@type": "messageText", text: { "@type": "formattedText", text: "Fixture match", entities: [] } },
    ...override,
  });
  const { session, request } = harness((query) => {
    switch (query["@type"]) {
      case "getAuthorizationState": return { "@type": "authorizationStateReady" };
      case "getChat": return { "@type": "chat", id: -42, title: "Fixture forum", has_protected_content: protectedChat };
      case "getChatMessageByDate": return row(100, 399, 19);
      case "getUser":
        if (protectAfterLookup) protectedChat = true;
        return { "@type": "user", id: query.user_id, first_name: `Sender ${query.user_id}` };
      case "searchChatMessages":
        if (query.from_message_id === 100) return { "@type": "foundChatMessages", next_from_message_id: 90,
          messages: [row(99, 398, 999, { chat_id: -43 }), row(98, 398, 999, { can_be_saved: false })] };
        return { "@type": "foundChatMessages", next_from_message_id: 75, messages: [
          row(90, 389, 19), row(89, 388, 20), row(89, 388, 20), row(88, 388, 999, { topic_id: topic(18) }),
          row(87, 387, 999, { self_destruct_type: { "@type": "messageSelfDestructTypeImmediately" } }),
          row(86, 301, 999, { ephemeral_content: { "@type": "ephemeralMessageContent" } }), row(85, -1, 999),
        ] };
      default: throw new Error("Unexpected fixture message search");
    }
  });
  const host = createFakePluginHost({ pluginId: "makosh-telegram" });
  let granted = ["-42"];
  const permission = new AbortController();
  registerAgentHistory(host.bb, async () => granted, () => session, () => permission.signal);
  try {
    const range = { from: 200, until: 400 };
    await vi.waitFor(() => expect(session.status().state).toBe("ready"));
    await expect(session.searchAgentMessages("-42", "Fixture match", range, undefined, 17)).resolves.toEqual({ messages: [], before: "90" });
    await expect(session.searchAgentMessages("-42", "Fixture match", range, "90", 17)).resolves.toEqual({
      messages: [
        { id: "90", date: 389, author: "Sender 19", excerpt: "Fixture match", forumTopicId: 17 },
        { id: "89", date: 388, author: "Sender 20", excerpt: "Fixture match", forumTopicId: 17 },
      ], before: null,
    });
    expect(request.mock.calls.filter(([query]) => query["@type"] === "searchChatMessages").map(([query]) => query)).toEqual([100, 90].map((from_message_id) => ({
      "@type": "searchChatMessages", chat_id: -42, topic_id: topic(17), from_message_id, offset: 0, limit: 25, query: "Fixture match",
    })));
    expect(request.mock.calls.filter(([query]) => query["@type"] === "getUser").map(([query]) => query.user_id)).toEqual([19, 20]);
    const input = { chatId: "-42", forumTopicId: 17, query: "Fixture match", dateFrom: "1970-01-01", dateTo: "1970-01-01" };
    const first = JSON.parse(String(await host.harness.behavior.callAgentTool(agentSearchMessagesTool, input)));
    expect(first).toEqual({ messages: [], next: expect.any(String) });
    const second = JSON.parse(String(await host.harness.behavior.callAgentTool(agentSearchMessagesTool, { ...input, cursor: first.next })));
    expect(second.messages.map(({ id }: { id: string }) => id)).toEqual(["90", "89"]);
    granted = [];
    await expect(host.harness.behavior.callAgentTool(agentSearchMessagesTool, input)).resolves.toContain("disabled");
    protectAfterLookup = true;
    await expect(session.searchAgentMessages("-42", "Fixture match", range, "90", 17)).rejects.toThrow("cannot be exported");
  } finally {
    await session.close();
    await host.harness.lifecycle.dispose();
  }
});

test("uses Telegram's last-access TTL only when cache retention is configured", async () => {
  const { session, request } = harness((query) => {
    switch (query["@type"]) {
      case "getAuthorizationState": return { "@type": "authorizationStateReady" };
      case "searchFileDownloads": return cacheDownloadQueue();
      case "getStorageStatistics":
      case "optimizeStorage": return { "@type": "storageStatistics", size: 100, count: 1 };
      default: throw new Error("Unexpected cache query");
    }
  });
  await vi.waitFor(() => expect(session.status().state).toBe("ready"));
  const limit = 512 * 1024 * 1024;
  await expect(session.optimizeCache(limit, { retentionDays: 366 })).rejects.toThrow("Invalid Telegram cache policy");
  await expect(session.optimizeCache(limit, { retentionDays: 7 })).resolves.toEqual({ bytes: 100 });
  await expect(session.optimizeCache(limit)).resolves.toEqual({ bytes: 100 });
  expect(request.mock.calls.filter(([query]) => query["@type"] === "optimizeStorage")).toEqual([
    [expect.objectContaining({ size: limit, ttl: 7 * 86_400, immunity_delay: 60 }), 60_000],
    [expect.objectContaining({ size: limit, ttl: 2147483647, immunity_delay: 60 }), 60_000],
  ]);
});

test("reports and clears cache for a single chat without targeting the aggregate row", async () => {
  let stats = [
    { "@type": "storageStatisticsByChat", chat_id: 0, size: 10 },
    { "@type": "storageStatisticsByChat", chat_id: -42, size: 60 },
    { "@type": "storageStatisticsByChat", chat_id: -43, size: 30 },
    { "@type": "storageStatisticsByChat", chat_id: -44, size: 1 },
  ];
  const result = () => ({ "@type": "storageStatistics", size: stats.reduce((total, row) => total + row.size, 0), by_chat: stats });
  const { session, request } = harness((query) => {
    switch (query["@type"]) {
      case "getAuthorizationState": return { "@type": "authorizationStateReady" };
      case "searchFileDownloads": return cacheDownloadQueue();
      case "getChat": return { "@type": "chat", id: query.chat_id === -44 ? -45 : query.chat_id, title: `Fixture ${query.chat_id}` };
      case "getStorageStatistics": return result();
      case "optimizeStorage":
        stats = stats.filter((row) => !(query.chat_ids as number[]).includes(row.chat_id));
        return result();
      default: throw new Error("Unexpected cache query");
    }
  });
  await vi.waitFor(() => expect(session.status().state).toBe("ready"));
  expect(await session.cacheUsage()).toEqual({ bytes: 101 });
  expect(request.mock.calls.some(([query]) => query["@type"] === "getChat")).toBe(false);
  expect(await session.cacheUsage(true)).toEqual({ bytes: 101, chats: [
    { id: "-42", title: "Fixture -42", bytes: 60 }, { id: "-43", title: "Fixture -43", bytes: 30 },
  ] });
  await expect(session.optimizeCache(0, { chatId: "0" })).rejects.toThrow("Invalid Telegram chat");
  await expect(session.optimizeCache(0, { chatId: "-44" })).rejects.toThrow("unavailable");
  expect(await session.optimizeCache(0, { chatId: "-42", includeChats: true })).toEqual({ bytes: 41, chats: [
    { id: "-43", title: "Fixture -43", bytes: 30 },
  ] });
  expect(request.mock.calls.filter(([query]) => query["@type"] === "optimizeStorage")).toEqual([
    [expect.objectContaining({ chat_ids: [-42], chat_limit: 10, size: 0 }), 60_000],
  ]);
});

test("discovers story and Live Photo cache types and defers cleanup while a native download is running", async () => {
  let paused = 0;
  let optimized = false;
  const fields = [
    ["fileTypePhotoStory", 20], ["fileTypeVideoStory", 40], ["fileTypeLivePhotoVideo", 10],
    ["fileTypeWallpaper", 50], ["fileTypeNotificationSound", 5],
  ] as const;
  const { session, request } = harness((query) => {
    switch (query["@type"]) {
      case "getAuthorizationState": return { "@type": "authorizationStateReady" };
      case "searchFileDownloads": return cacheDownloadQueue(1, paused);
      case "getStorageStatistics": return optimized ? { "@type": "storageStatistics", size: 5 } : { "@type": "storageStatistics", size: 125, by_chat: [
        { "@type": "storageStatisticsByChat", chat_id: 0, by_file_type: fields.map(([type, size]) => ({
          "@type": "storageStatisticsByFileType", file_type: { "@type": type }, size,
        })) },
      ] };
      case "optimizeStorage": optimized = true; return { "@type": "storageStatistics", size: 5 };
      default: throw new Error("Unexpected cache query");
    }
  });
  try {
    await vi.waitFor(() => expect(session.status().state).toBe("ready"));
    expect(await session.cacheUsage()).toEqual({ bytes: 125, breakdown: [
      { category: "videos", bytes: 50 }, { category: "wallpapers", bytes: 50 },
      { category: "photos", bytes: 20 }, { category: "other", bytes: 5 },
    ] });
    await expect(session.optimizeCache(0)).resolves.toBeUndefined();
    expect(request).not.toHaveBeenCalledWith(expect.objectContaining({ "@type": "optimizeStorage" }), expect.anything());
    paused = 1;
    await expect(session.optimizeCache(0)).resolves.toEqual({ bytes: 5 });
    await expect(session.optimizeCache(0, { category: "wallpapers" })).resolves.toEqual({ bytes: 5 });
    const optimizations = request.mock.calls.filter(([query]) => query["@type"] === "optimizeStorage").map(([query]) => query);
    expect(optimizations[0]?.file_types).toEqual(expect.arrayContaining(fields.slice(0, 4).map(([type]) => ({ "@type": type }))));
    expect(optimizations[0]?.file_types).not.toContainEqual({ "@type": "fileTypeNotificationSound" });
    expect(optimizations[1]?.file_types).toEqual([{ "@type": "fileTypeWallpaper" }]);
  } finally { await session.close(); }
});

