test("keeps unread message and chat totals independently for each Telegram list", async () => {
  const changed = vi.fn();
  const { session, update } = harness((query) => {
    if (query["@type"] === "getAuthorizationState") return { "@type": "authorizationStateReady" };
    throw new Error("Unexpected test query");
  }, vi.fn(), "fixture", changed);
  const main = { "@type": "chatListMain" };
  const folder = { "@type": "chatListFolder", chat_folder_id: 17 };
  update({ "@type": "updateUnreadChatCount", chat_list: main, unread_count: 14, unread_unmuted_count: 3 });
  await vi.waitFor(() => expect(session.status()).toEqual({ state: "ready" }));
  changed.mockClear();
  update({ "@type": "updateUnreadMessageCount", chat_list: main, unread_count: 150, unread_unmuted_count: 9 });
  update({ "@type": "updateUnreadChatCount", chat_list: folder, unread_count: 6, unread_unmuted_count: 2 });
  update({ "@type": "updateUnreadChatCount", chat_list: folder, unread_count: 6, unread_unmuted_count: 2 });
  update({ "@type": "updateUnreadChatCount", chat_list: main, unread_count: 2, unread_unmuted_count: 3 });
  expect(changed).toHaveBeenCalledTimes(2);
  expect(session.unreadCounts()).toEqual([
    { list: "main", chats: { total: 14, unmuted: 3 }, messages: { total: 150, unmuted: 9 } },
    { list: 17, chats: { total: 6, unmuted: 2 } },
  ]);
  update({ "@type": "updateUnreadChatCount", chat_list: folder, unread_count: 0, unread_unmuted_count: 0 });
  expect(session.unreadCounts()[1]).toMatchObject({ chats: { total: 0, unmuted: 0 } });
});

test.each([false, true])("manages Telegram proxies without returning credentials (modern=%s)", async (modern) => {
  let enabled = false;
  let saved = { server: "fixture.invalid", port: 1080, type: {
    "@type": "proxyTypeSocks5", username: "fixture-user", password: "fixture-password",
  } };
  const row = () => modern
    ? { "@type": "addedProxy", id: 4, is_enabled: enabled, proxy: { "@type": "proxy", ...saved } }
    : { "@type": "proxy", id: 4, is_enabled: enabled, ...saved };
  const { session, request } = harness((query) => {
    switch (query["@type"]) {
      case "getAuthorizationState": return { "@type": "authorizationStateReady" };
      case "getProxies": return { "@type": modern ? "addedProxies" : "proxies", proxies: [row()] };
      case "editProxy": {
        const address = (modern ? query.proxy : query) as typeof saved;
        saved = { server: address.server, port: address.port, type: address.type };
        return row();
      }
      case "enableProxy": enabled = true; return { "@type": "ok" };
      case "disableProxy": enabled = false; return { "@type": "ok" };
      case "pingProxy": return { "@type": "seconds", seconds: 0.035 };
      default: throw new Error("Unexpected test query");
    }
  });
  await vi.waitFor(() => expect(session.status().state).toBe("ready"));
  expect(await session.proxies()).toEqual([{ id: 4, enabled: false, kind: "socks5", server: "fixture.invalid", port: 1080 }]);
  await expect(session.saveProxy({ kind: "socks5", server: "fixture.invalid", port: 1081 }, 4)).resolves.toEqual({
    id: 4, enabled: false, kind: "socks5", server: "fixture.invalid", port: 1081,
  });
  expect(saved.type.password).toBe("fixture-password");
  await expect(session.changeProxy("enable", 4)).resolves.toBe(true);
  expect((await session.proxies())[0]?.enabled).toBe(true);
  await expect(session.pingProxy(4)).resolves.toBe(35);
  expect(request).toHaveBeenCalledWith(modern
    ? { "@type": "pingProxy", proxy: { "@type": "proxy", ...saved } }
    : { "@type": "pingProxy", proxy_id: 4 }, 15_000);
  await expect(session.changeProxy("disable")).resolves.toBe(true);
  expect((await session.proxies())[0]?.enabled).toBe(false);
});

