test("translates rich messages through TDLib while retaining supported sections and captions", async () => {
  const plain = (text: string) => ({ "@type": "richTextPlain", text });
  const rich = (title: string, caption: string) => ({ "@type": "richMessage", is_full: true, blocks: [
    { "@type": "pageBlockTitle", title: plain(title) },
    { "@type": "pageBlockPhoto", caption: { "@type": "pageBlockCaption", text: plain(caption) } },
  ] });
  let protectedChat = true;
  const { session, request } = harness((query) => {
    switch (query["@type"]) {
      case "getAuthorizationState": return { "@type": "authorizationStateReady" };
      case "getChat": return { "@type": "chat", id: -42, has_protected_content: protectedChat };
      case "getMessage": return { "@type": "message", id: 9, chat_id: -42,
        content: { "@type": "messageRichMessage", message: rich("Fixture title", "Fixture caption") } };
      case "translateMessageRichMessage": return rich("Título", "Leyenda");
      default: throw new Error("Unexpected fixture query");
    }
  });
  try {
    await vi.waitFor(() => expect(session.status().state).toBe("ready"));
    await expect(session.translateMessage("-42", "9", "es")).resolves.toBeNull();
    expect(request.mock.calls.some(([query]) => query["@type"] === "translateMessageRichMessage")).toBe(false);
    protectedChat = false;
    await expect(session.translateMessage("-42", "9", "es")).resolves.toMatchObject({
      text: "Título\nLeyenda", rich: { blocks: [
        { kind: "title", content: { text: "Título" } }, { kind: "attachment", content: { text: "Leyenda" } },
      ] },
    });
    expect(request).toHaveBeenCalledWith({ "@type": "translateMessageRichMessage", chat_id: -42, message_id: 9, to_language_code: "es", tone: "" });
  } finally { await session.close(); }
});

