test("keeps Telegram-restricted message contents out of history, search and attachment requests", async () => {
  const photoContent = { "@type": "messagePhoto", photo: { "@type": "photo", sizes: [
    { "@type": "photoSize", width: 320, height: 240, photo: { "@type": "file", id: 7 } },
  ] }, caption: { "@type": "formattedText", text: "Private fixture caption" } };
  const reason = "Telegram marked this fixture unavailable.";
  const restricted = { "@type": "message", id: 12, chat_id: 42, date: 1700000000, content: photoContent,
    restriction_info: { "@type": "restrictionInfo", restriction_reason: reason, has_sensitive_content: true } };
  const warningOnly = { ...restricted, id: 11, restriction_info: { ...restricted.restriction_info, restriction_reason: "" } };
  let enabled = false;
  const { session, request, update } = harness((query) => {
    switch (query["@type"]) {
      case "getAuthorizationState": return { "@type": "authorizationStateReady" };
      case "getOption": return { "@type": "optionValueBoolean", value: query.name === "can_ignore_sensitive_content_restrictions" || enabled };
      case "getChat": return { "@type": "chat", id: 42, title: "Fixture chat",
        type: { "@type": "chatTypePrivate", user_id: 42 } };
      case "getChatHistory": return { "@type": "messages", messages: [restricted, warningOnly] };
      case "searchMessages": return { "@type": "foundMessages", next_offset: "", messages: [restricted] };
      case "getMessage": return query.message_id === 11 ? warningOnly : restricted;
      default: throw new Error("Unexpected restriction fixture query");
    }
  });
  try {
    await vi.waitFor(() => expect(session.status().state).toBe("ready"));
    const rows = (await session.history("42")).messages;
    const hidden = rows.find(({ id }) => id === "12");
    expect(hidden).toMatchObject({ text: reason, restricted: true });
    expect(hidden).not.toHaveProperty("hasPhoto");
    expect(hidden).not.toHaveProperty("photoCaption");
    expect(rows.find(({ id }) => id === "11")).toMatchObject({ text: expect.stringContaining("18+ media hidden"), restricted: true });
    await expect(session.photo("42", "11")).rejects.toThrow("No eligible photo.");
    const result = await session.globalSearch("", "media");
    expect(result.hits[0]?.message.text).toBe(reason);
    expect(result.hits[0]?.thumbnail).toBeUndefined();
    expect(JSON.stringify(result)).not.toContain("Private fixture caption");
    await expect(session.photo("42", "12")).rejects.toThrow("No eligible photo.");
    await expect(session.documentName("42", "12")).rejects.toThrow("Document is unavailable.");
    enabled = true;
    update({ "@type": "updateOption", name: "ignore_sensitive_content_restrictions",
      value: { "@type": "optionValueBoolean", value: true } });
    expect((await session.history("42")).messages.find(({ id }) => id === "11")).toMatchObject({ hasPhoto: true });
    expect((await session.history("42")).messages.find(({ id }) => id === "12")).toMatchObject({ restricted: true, text: reason });

    update({ "@type": "updateAgeVerificationParameters", parameters: {
      "@type": "ageVerificationParameters", min_age: 18, verification_bot_username: "FixtureVerifyBot",
    } });
    expect((await session.history("42")).messages.find(({ id }) => id === "11")).toMatchObject({
      restricted: true, text: "Telegram requires age verification to show this media.",
    });
    await expect(session.photo("42", "11")).rejects.toThrow("No eligible photo.");
    await expect(session.sensitiveContentSettings()).resolves.toEqual({
      show: true, editable: false, ageVerificationRequired: true, verificationBot: "FixtureVerifyBot",
    });
    await expect(session.saveSensitiveContentSettings(false, true)).resolves.toBe("unavailable");
    update({ "@type": "updateAgeVerificationParameters", parameters: {
      "@type": "ageVerificationParameters", verification_bot_username: "example.com/other",
    } });
    await expect(session.sensitiveContentSettings()).resolves.toEqual({ show: true, editable: false, ageVerificationRequired: true });
    update({ "@type": "updateAgeVerificationParameters", parameters: null });
    await expect(session.sensitiveContentSettings()).resolves.toEqual({ show: true, editable: true });
    expect(request.mock.calls.some(([query]) => query["@type"] === "downloadFile" || query["@type"] === "setOption")).toBe(false);
  } finally { await session.close(); }
});

test("launches only the current Telegram age verification bot and drops stale launches", async () => {
  const bot = "FixtureVerifyBot";
  let onLaunch = () => {};
  let requireOrigin = false;
  const { session, request, update } = harness((query) => {
    switch (query["@type"]) {
      case "getAuthorizationState": return { "@type": "authorizationStateReady" };
      case "getInternalLinkType": return { "@type": "internalLinkTypeMainWebApp", bot_username: bot, start_parameter: "" };
      case "searchPublicChat": return { "@type": "chat", type: { "@type": "chatTypePrivate", user_id: 54 } };
      case "getUser": return { "@type": "user", id: 54, type: { "@type": "userTypeBot", has_main_web_app: true } };
      case "getMainWebApp": {
        onLaunch();
        return { "@type": "mainWebApp", url: { "@type": "webAppUrl", url: "https://example.com/fixture-check",
          require_same_origin: requireOrigin } };
      }
      default: throw new Error("Unexpected age verification fixture query.");
    }
  });
  const ageRequired = (username: string) => update({ "@type": "updateAgeVerificationParameters", parameters: {
    "@type": "ageVerificationParameters", min_age: 18, verification_bot_username: username,
  } });
  try {
    await vi.waitFor(() => expect(session.status().state).toBe("ready"));
    await expect(session.launchAgeVerification(bot)).resolves.toBeNull();
    ageRequired(bot);
    await expect(session.launchAgeVerification("OtherVerifyBot")).resolves.toBeNull();
    await expect(session.launchAgeVerification(bot, AbortSignal.abort())).resolves.toBeNull();
    expect(request.mock.calls.map(([query]) => query["@type"])).toEqual(["getAuthorizationState"]);
    await expect(session.launchAgeVerification(bot)).resolves.toMatchObject({
      url: "https://example.com/fixture-check", session: expect.any(String),
    });
    expect(request).toHaveBeenCalledWith(expect.objectContaining({
      "@type": "getMainWebApp", chat_id: 0, bot_user_id: 54, start_parameter: "",
    }));
    requireOrigin = true;
    await expect(session.launchAgeVerification(bot)).resolves.toBeNull();
    requireOrigin = false;
    onLaunch = () => ageRequired("ChangedVerifyBot");
    await expect(session.launchAgeVerification(bot)).resolves.toBeNull();
    expect(request.mock.calls.some(([query]) => query["@type"] === "setOption" || query["@type"] === "sendMessage")).toBe(false);
  } finally { await session.close(); }
});

test("applies the 18+ account preference to agent discovery, reading and transcript eligibility", async () => {
  const restriction_info = { "@type": "restrictionInfo", has_sensitive_content: true, restriction_reason: "" };
  const text = { "@type": "message", id: 31, chat_id: -42, date: 410, is_outgoing: true, restriction_info,
    content: { "@type": "messageText", text: { "@type": "formattedText", text: "Sensitive fixture match" } } };
  const voice = { ...text, id: 30, date: 400, content: {
    "@type": "messageVoiceNote", voice_note: { "@type": "voiceNote", duration: 1, voice: { "@type": "file", id: 99, size: 4 } },
  } };
  let enabled = false;
  let anchorMatches = true;
  const range = { from: 200, until: 500 };
  const { session, request, update } = harness((query) => {
    switch (query["@type"]) {
      case "getAuthorizationState": return { "@type": "authorizationStateReady" };
      case "getOption": return { "@type": "optionValueBoolean", value: query.name === "can_ignore_sensitive_content_restrictions" || enabled };
      case "getChat": return { "@type": "chat", id: -42, title: "Unrelated fixture group" };
      case "getChatMessageByDate": return anchorMatches ? text : { ...text, id: 40, content: {
        "@type": "messageText", text: { "@type": "formattedText", text: "Unrelated anchor" },
      } };
      case "searchChatMessages": return { "@type": "foundChatMessages", next_from_message_id: 0, messages: [text] };
      case "getChatHistory": return { "@type": "messages", messages: [text, voice] };
      case "getMessage": return query.message_id === 30 ? voice : text;
      case "translateMessageText": return { "@type": "formattedText", text: "Fixture translation" };
      default: throw new Error("Unexpected sensitive fixture query");
    }
  });
  const find = () => session.findRelatedChats("Sensitive fixture match", range, ["-42"]);
  const search = () => session.searchAgentMessages("-42", "Sensitive fixture match", range);
  try {
    await vi.waitFor(() => expect(session.status().state).toBe("ready"));
    expect((await find()).chats).toEqual([]);
    expect((await search()).messages).toEqual([]);
    expect((await session.historyInDateRange("-42", range)).messages).toEqual([
      { id: "31", date: 410, withheld: true }, { id: "30", date: 400, withheld: true },
    ]);
    await expect(session.transcribeVoice("-42", "30")).rejects.toThrow("unavailable");
    await expect(session.translateMessage("-42", "31", "en")).resolves.toBeNull();
    expect(request.mock.calls.some(([query]) =>
      query["@type"] === "downloadFile" || query["@type"] === "translateMessageText")).toBe(false);

    enabled = true;
    update({ "@type": "updateOption", name: "ignore_sensitive_content_restrictions",
      value: { "@type": "optionValueBoolean", value: true } });
    expect((await find()).chats).toMatchObject([{ id: "-42", matchedMessages: true }]);
    anchorMatches = false;
    expect((await find()).chats).toMatchObject([{ id: "-42", matchedMessages: true }]);
    expect((await search()).messages).toMatchObject([{ id: "31", excerpt: "Sensitive fixture match" }]);
    await expect(session.translateMessage("-42", "31", "en")).resolves.toEqual({ text: "Fixture translation" });

    update({ "@type": "updateAgeVerificationParameters", parameters: { "@type": "ageVerificationParameters", min_age: 18 } });
    expect((await find()).chats).toEqual([]);
    expect((await search()).messages).toEqual([]);
    await expect(session.translateMessage("-42", "31", "en")).resolves.toBeNull();
  } finally { await session.close(); }
});

test("converts locations and venues without offering external maps for protected messages", async () => {
  const point = { "@type": "location", latitude: 10, longitude: -20 };
  const location = { "@type": "messageLocation", location: point };
  const contents = [
    { content: location },
    { content: { ...location, live_period: 900, expires_in: 0 } },
    { content: { ...location, live_period: 2147483647, expires_in: 2147483647 }, can_be_saved: false },
    { content: { "@type": "messageVenue", venue: { "@type": "venue", location: point, title: "Fixture", address: "Test address" } } },
    { content: { ...location, location: { ...point, latitude: 95 } } },
  ];
  let protectedChat = false;
  const { session } = harness((query) => {
    if (query["@type"] === "getAuthorizationState") return { "@type": "authorizationStateReady" };
    if (query["@type"] === "getChat") return { "@type": "chat", id: -42, has_protected_content: protectedChat };
    if (query["@type"] === "getChatHistory") return {
      "@type": "messages",
      messages: contents.map((entry, index) => ({ "@type": "message", id: index + 1, ...entry })).reverse(),
    };
    throw new Error("Unexpected test query");
  });
  await vi.waitFor(() => expect(session.status().state).toBe("ready"));
  const messages = (await session.history("-42")).messages;
  expect(messages.map(({ location }) => location)).toEqual([
    { latitude: 10, longitude: -20, canOpenMap: true },
    { latitude: 10, longitude: -20, canOpenMap: true, liveUntil: "ended" },
    { latitude: 10, longitude: -20, canOpenMap: false, liveUntil: "indefinite" },
    { latitude: 10, longitude: -20, canOpenMap: true, place: { title: "Fixture", address: "Test address" } },
    undefined,
  ]);
  protectedChat = true;
  expect((await session.history("-42")).messages[0]?.location?.canOpenMap).toBe(false);
});

test("places only the confirmed auction bid and rejects a changed round", async () => {
  const now = Math.floor(Date.now() / 1000);
  let round = 1;
  let nextBid = 550;
  const { session, request } = harness((query) => {
    switch (query["@type"]) {
      case "getAuthorizationState": return { "@type": "authorizationStateReady" };
      case "getChat": return { "@type": "chat", id: query.chat_id, type: { "@type": "chatTypePrivate", user_id: query.chat_id } };
      case "getUser": return { "@type": "user", id: query.user_id, type: { "@type": "userTypeRegular" } };
      case "getGiftAuctionState": return { "@type": "giftAuctionState", gift: { "@type": "gift", id: "13" },
        state: { "@type": "auctionStateActive", start_date: now - 60, end_date: now + 1200,
          current_round_number: round, current_round_end_date: now + 900, min_bid: 500,
          user_bid: { "@type": "userAuctionBid", star_count: 520, next_bid_star_count: nextBid,
            owner_id: { "@type": "messageSenderUser", user_id: 42 } } } };
      case "placeGiftAuctionBid": return { "@type": "ok" };
      default: throw new Error("Unexpected test query");
    }
  });
  try {
    await vi.waitFor(() => expect(session.status().state).toBe("ready"));
    const bid = { giftId: "13", auctionId: "fixture-auction", stars: 550 };
    await expect(session.reviewGiftAuctionBid("43", bid)).resolves.toBeNull();
    await expect(session.reviewGiftAuctionBid("42", { ...bid, stars: 549 })).resolves.toBeNull();
    const stale = await session.reviewGiftAuctionBid("42", bid);
    expect(stale).toEqual(expect.any(String));
    round = 2;
    await expect(session.confirmGiftAuctionBid("42", stale!)).resolves.toBe("changed");
    const raised = await session.reviewGiftAuctionBid("42", bid);
    nextBid = 600;
    await expect(session.confirmGiftAuctionBid("42", raised!)).resolves.toBe("changed");
    expect(request.mock.calls.some(([query]) => query["@type"] === "placeGiftAuctionBid")).toBe(false);
    const token = await session.reviewGiftAuctionBid("42", { ...bid, stars: 600 });
    expect(token).toEqual(expect.any(String));
    await expect(Promise.all([session.confirmGiftAuctionBid("42", token!), session.confirmGiftAuctionBid("42", token!)]))
      .resolves.toEqual(["sent", "changed"]);
    expect(request.mock.calls.map(([query]) => query).filter((query) => query["@type"] === "placeGiftAuctionBid")).toEqual([{
      "@type": "placeGiftAuctionBid", gift_id: "13", star_count: 600, user_id: 42,
      text: { "@type": "formattedText", text: "", entities: [] }, is_private: true,
    }]);
  } finally { await session.close(); }
});

