test("binds a resale purchase to the approved recipient, currency and exact amount", async () => {
  let gramCents = 125;
  let increased = true;
  const { session, request } = harness((query) => {
    switch (query["@type"]) {
      case "getAuthorizationState": return { "@type": "authorizationStateReady" };
      case "getChat": return { "@type": "chat", id: query.chat_id, type: { "@type": "chatTypePrivate", user_id: query.chat_id } };
      case "getMe": return { "@type": "user", id: 42 };
      case "getUpgradedGift": return { "@type": "upgradedGift", name: query.name,
        owner_id: { "@type": "messageSenderUser", user_id: 74 },
        resale_parameters: { "@type": "giftResaleParameters", star_count: 300, gram_cent_count: gramCents } };
      case "sendResoldGift": return { "@type": increased ? "giftResaleResultPriceIncreased" : "giftResaleResultOk" };
      default: throw new Error("Unexpected test query");
    }
  });
  try {
    await vi.waitFor(() => expect(session.status().state).toBe("ready"));
    const payment = { slug: "Fixture-7", currency: "gram", amount: 125 } as const;
    const original = await session.reviewGiftResale("43", payment);
    expect(original).toEqual(expect.any(String));
    await expect(session.confirmGiftResale("44", original!)).resolves.toBe("changed");
    gramCents = 130;
    await expect(session.confirmGiftResale("43", original!)).resolves.toBe("changed");
    expect(request.mock.calls.some(([query]) => query["@type"] === "sendResoldGift")).toBe(false);
    const updated = await session.reviewGiftResale("43", { ...payment, amount: 130 });
    await expect(session.confirmGiftResale("43", updated!)).resolves.toBe("changed");
    expect(request).toHaveBeenLastCalledWith({
      "@type": "sendResoldGift", gift_name: "Fixture-7", owner_id: { "@type": "messageSenderUser", user_id: 43 },
      price: { "@type": "giftResalePriceGram", gram_cent_count: 130 }, text: { "@type": "formattedText", text: "", entities: [] }, is_private: true,
    });
    increased = false;
    const stars = await session.reviewGiftResale("43", { ...payment, currency: "stars", amount: 300 });
    await expect(Promise.all([session.confirmGiftResale("43", stars!), session.confirmGiftResale("43", stars!)]))
      .resolves.toEqual(["sent", "changed"]);
    expect(request).toHaveBeenLastCalledWith(expect.objectContaining({ "@type": "sendResoldGift",
      price: { "@type": "giftResalePriceStar", star_count: 300 } }));
    expect(request.mock.calls.filter(([query]) => query["@type"] === "sendResoldGift")).toHaveLength(2);
  } finally { await session.close(); }
});

