    expect(request).toHaveBeenLastCalledWith({ "@type": "searchGiftsForResale", gift_id: "13",
      order: { "@type": "giftForResaleOrderNumber" }, for_crafting: false, for_stars: true, attributes: [], offset: "more", limit: 20 });
    const attributes = [{ kind: "model" as const, id: "9007199254740993" }, { kind: "backdrop" as const, id: 7 }];
    const byAttributes = await session.searchGiftResale("42", { giftId: "13", order: "price", starsOnly: false, attributes });
