    await expect(session.reviewGiftListing("42", "fixture", { currency: "stars", amount: 4 })).resolves.toBeNull();
    const price = { currency: "gram" as const, amount: 125 };
    const stale = await session.reviewGiftListing("42", "fixture", price);
    expect(stale).toMatchObject({ price, earningsPerMille: 800 });
