test.each([
  [undefined, true],
  [17, true],
  [undefined, false],
  [17, false],
] as const)("opens unread history at the last read message (topic %s, known last message: %s)", async (topicId, knownLatest) => {
  const row = (id: number) => ({ "@type": "message", chat_id: 42, id,
    ...(topicId === undefined ? {} : { topic_id: { "@type": "messageTopicForum", forum_topic_id: topicId } }),
    content: { "@type": "messageText", text: { "@type": "formattedText", text: `Fixture ${id}` } } });
  const historyType = topicId === undefined ? "getChatHistory" : "getForumTopicHistory";
  const { session, request } = harness((query) => {
    switch (query["@type"]) {
      case "getAuthorizationState": return { "@type": "authorizationStateReady" };
      case "getChat": return { "@type": "chat", id: 42, title: "Fixture", unread_count: 4, last_read_inbox_message_id: 50, last_message: knownLatest ? row(53) : undefined };
      case "getForumTopic": return { "@type": "forumTopic", unread_count: 4, last_read_inbox_message_id: 50, last_message: knownLatest ? row(53) : undefined,
        info: { "@type": "forumTopicInfo", chat_id: 42, forum_topic_id: topicId, name: "Fixture topic" } };
      case historyType: return { "@type": "messages",
        messages: query.from_message_id === 50 ? [row(51), row(50), row(49)]
          : query.from_message_id === 51 ? [row(53), row(52), row(51)] : [row(53)] };
      default: throw new Error("Unexpected fixture request");
    }
  });
  try {
    await vi.waitFor(() => expect(session.status().state).toBe("ready"));
    const initial = await session.unreadHistory("42", undefined, topicId);
    expect(initial).toMatchObject({ openAt: "50", readInbox: 50, before: "49", after: "51" });
    expect(initial?.messages.map(({ id }) => id)).toEqual(["49", "50", "51"]);
    const next = await session.unreadHistory("42", "51", topicId);
    expect(next?.messages.map(({ id }) => id)).toEqual(["52", "53"]);
    expect(next?.after).toBe(knownLatest ? undefined : "53");
    if (!knownLatest) await expect(session.unreadHistory("42", "53", topicId)).resolves.toEqual({
      messages: [], before: null, readInbox: 50, unreadCount: 4,
    });
    expect(request.mock.calls.filter(([query]) => query["@type"] === historyType)
      .map(([query]) => [query.from_message_id, query.offset, query.forum_topic_id])).toEqual([[50, -20, topicId], [49, 0, topicId], [51, -20, topicId], ...(knownLatest ? [] : [[53, -20, topicId]])]);
  } finally { await session.close(); }
});

test("automatically downloads only eligible visible videos within the current policy", async () => {
  const size = 512 * 1024;
  const disabledLimits = { photo: 0, video: 0, file: 0 };
  const disabled = { private: disabledLimits, group: disabledLimits, channel: disabledLimits };
  const policy = { ...disabled, private: { ...disabledLimits, video: 1 }, channel: { ...disabledLimits, video: 2 } };
  let type: TdObject = { "@type": "chatTypePrivate", user_id: 55 };
  let local = { "@type": "localFile", can_be_downloaded: true, is_downloading_completed: false };
  let bytes = size;
  let has_protected_content = false;
  let has_spoiler = false;
  const { session, request } = harness((query) => {
    switch (query["@type"]) {
      case "getAuthorizationState": return { "@type": "authorizationStateReady" };
      case "getChat": return { "@type": "chat", id: 42, type };
      case "getMessage": return { "@type": "message", id: 50, chat_id: 42, has_protected_content,
        content: { "@type": "messageVideo", video: { "@type": "video", video: { "@type": "file", id: 42, size } }, has_spoiler } };
      case "getFile": return { "@type": "file", id: 42, size: bytes, local };
      case "downloadFile": return { "@type": "file", id: 42, local: { "@type": "localFile", is_downloading_completed: true } };
      default: throw new Error("Unexpected fixture request");
    }
  });
  const signal = new AbortController().signal;
  const prefetch = (read = async () => policy, topicId?: number) => session.prefetchVisibleMedia("42", "50", topicId, read, signal);
  const downloads = () => request.mock.calls.filter(([query]) => query["@type"] === "downloadFile");
  try {
    await vi.waitFor(() => expect(session.status().state).toBe("ready"));
    await expect(prefetch(async () => disabled)).resolves.toBe(false);
    await expect(prefetch(async () => ({ ...policy, private: disabledLimits }))).resolves.toBe(false);
    await expect(prefetch(undefined, 17)).resolves.toBe(false);
    has_protected_content = true;
    await expect(prefetch()).resolves.toBe(false);
    has_protected_content = false;
    has_spoiler = true;
    await expect(prefetch()).resolves.toBe(false);
    has_spoiler = false;
    bytes = 2 * 1024 * 1024;
    await expect(prefetch()).resolves.toBe(false);
    bytes = 0;
    await expect(prefetch()).resolves.toBe(false);
    bytes = size;
    local = { ...local, is_downloading_completed: true };
    await expect(prefetch()).resolves.toBe(false);
    local = { ...local, is_downloading_completed: false };
    const revoked = vi.fn().mockResolvedValueOnce(policy).mockResolvedValueOnce(disabled);
    await expect(prefetch(revoked)).resolves.toBe(false);
    expect(revoked).toHaveBeenCalledTimes(2);
    expect(downloads()).toEqual([]);
    await expect(prefetch()).resolves.toBe(true);
    expect(downloads()).toEqual([[{ "@type": "downloadFile", file_id: 42, priority: 1, offset: 0, limit: size, synchronous: true }, 45_000, signal]]);
    bytes = 2 * 1024 * 1024;
    type = { "@type": "chatTypeBasicGroup", basic_group_id: 55 };
    await expect(prefetch()).resolves.toBe(false);
    type = { "@type": "chatTypeSupergroup", supergroup_id: 55, is_channel: true };
    await expect(prefetch()).resolves.toBe(true);
    expect(downloads().map(([query]) => query.limit)).toEqual([size, bytes]);
    await expect(prefetch(async () => ({ ...policy, override: disabledLimits }))).resolves.toBe(false);
    expect(downloads()).toHaveLength(2);
    type = { "@type": "chatTypeBasicGroup", basic_group_id: 55 };
    await expect(prefetch(async () => ({ ...disabled, override: { ...disabledLimits, video: 2 } }))).resolves.toBe(true);
    expect(downloads()).toHaveLength(3);
  } finally { await session.close(); }
});

test("loads lightweight download counts and handles TDLib queue updates", async () => {
  const notifyDownloadCounts = vi.fn();
  const notifyDownloadProgress = vi.fn();
  let receive!: (event: TdObject) => void;
  const counts = { "@type": "downloadedFileCounts", active_count: 3, paused_count: 2, completed_count: 1 };
  const request = vi.fn(async (query: TdObject) => query["@type"] === "getAuthorizationState" ? { "@type": "authorizationStateReady" }
    : { "@type": "foundFileDownloads", total_counts: counts, files: [] });
  const session = createTelegram({ library: "fixture", directory: "fixture", key: "fixture", apiId: 1, apiHash: "fixture", notifyDownloadCounts, notifyDownloadProgress },
    (_, onUpdate) => { receive = onUpdate; return { request, close: async () => {} }; });
  try {
    await vi.waitFor(() => expect(session.status().state).toBe("ready"));
    await expect(session.downloadCounts()).resolves.toEqual({ active: 3, paused: 2, completed: 1 });
    expect(request).toHaveBeenLastCalledWith({ "@type": "searchFileDownloads", query: "", offset: "", limit: 1,
      only_active: false, only_completed: false });
    receive({ "@type": "updateFileDownload", counts });
    receive({ "@type": "updateFileRemovedFromDownloads", counts: { ...counts, active_count: -1 } });
    await vi.waitFor(() => expect(notifyDownloadCounts).toHaveBeenCalledExactlyOnceWith({ active: 3, paused: 2, completed: 1 }));
    receive({ "@type": "updateFileDownloads", total_count: 1, total_size: 4096, downloaded_size: 1024 });
    receive({ "@type": "updateFileDownloads", total_count: 1, total_size: 4096, downloaded_size: 8192 });
    await vi.waitFor(() => expect(notifyDownloadProgress).toHaveBeenCalledExactlyOnceWith({ totalBytes: 4096, downloadedBytes: 1024 }));
    await expect(session.downloadCounts()).resolves.toEqual({
      active: 3, paused: 2, completed: 1, progress: { totalBytes: 4096, downloadedBytes: 1024 },
    });
  } finally { await session.close(); }
});

