test.each([false, true])("fills initial history with 50 read messages across short pages (unread: %s)", async (unread) => {
  const row = (id: number) => ({ "@type": "message", chat_id: 42, id, content: { "@type": "messageText" } });
  const latest = unread ? 102 : 100;
  const { session, request } = harness((query) => {
    switch (query["@type"]) {
      case "getAuthorizationState": return { "@type": "authorizationStateReady" };
      case "getChat": return { "@type": "chat", id: 42, last_read_inbox_message_id: 100,
        unread_count: unread ? 2 : 0, last_message: row(latest) };
      case "getChatHistory": {
        const cursor = Number(query.from_message_id);
        const messages = query.offset === -20 ? [row(102), row(101), row(100)]
          : cursor === 0 ? [row(100)]
            : Array.from({ length: Math.min(Number(query.limit), 9, cursor) }, (_, index) => row(cursor - index));
        return { "@type": "messages", messages };
      }
      default: throw new Error("Unexpected fixture request");
    }
  });
  try {
    await vi.waitFor(() => expect(session.status().state).toBe("ready"));
    const initial = unread ? await session.unreadHistory("42") : await session.history("42");
    expect(initial?.messages.map(({ id }) => id))
      .toEqual(Array.from({ length: latest - 50 }, (_, index) => String(51 + index)));
    expect(initial?.before).toBe("51");
    expect(initial?.openAt).toBe(unread ? "100" : undefined);
    expect(request.mock.calls.some(([query]) => query["@type"] === "getChatHistory" && query.from_message_id === 51)).toBe(false);
    const older = await session.history("42", initial?.before ?? undefined);
    expect(older.messages.map(({ id }) => id)).toEqual(["43", "44", "45", "46", "47", "48", "49", "50"]);
    expect(request.mock.calls.some(([query]) => query["@type"] === "viewMessages")).toBe(false);
  } finally { await session.close(); }
});

