test.each(["group", "channel", "topic"] as const)("clears pins only in the reviewed %s scope", async (kind) => {
  const topic = kind === "topic" ? { id: 17, name: "Fixture topic" } : undefined;
  const channel = kind === "channel";
  let pin = 51;
  let permission = true;
  let name = "Fixture topic";
  let returnedTopic = 17;
  const { session, request } = harness((query) => {
    const raw = { "@type": "message", id: pin, chat_id: -42, is_pinned: true,
      ...(topic ? { topic_id: { "@type": "messageTopicForum", forum_topic_id: returnedTopic } } : {}) };
    switch (query["@type"]) {
      case "getAuthorizationState": return { "@type": "authorizationStateReady" };
      case "getChat": return { "@type": "chat", id: -42,
        type: { "@type": "chatTypeSupergroup", supergroup_id: 42, is_channel: channel } };
      case "getSupergroup": return { "@type": "supergroup", id: 42, is_channel: channel, is_forum: !!topic,
        status: { "@type": "chatMemberStatusAdministrator", rights: { "@type": "chatAdministratorRights", can_edit_messages: channel && permission, can_pin_messages: !channel && permission } } };
      case "getForumTopic": return { "@type": "forumTopic", info: {
        "@type": "forumTopicInfo", chat_id: -42, forum_topic_id: 17, name,
      } };
      case "searchChatMessages":
        expect(query).toMatchObject({ chat_id: -42, filter: { "@type": "searchMessagesFilterPinned" },
          topic_id: { "@type": "messageTopicForum", forum_topic_id: 17 } });
        return { "@type": "foundChatMessages", messages: [raw] };
      case "getChatPinnedMessage": return raw;
      case "unpinAllForumTopicMessages":
      case "unpinAllChatMessages": return { "@type": "ok" };
      default: throw new Error("Unexpected fixture request");
    }
  });
  const sent = () => request.mock.calls.filter(([query]) => String(query["@type"]).startsWith("unpinAll")).map(([query]) => query);
  try {
    await vi.waitFor(() => expect(session.status().state).toBe("ready"));
    if (topic) {
      await expect(session.unpinAllPreview("-42")).resolves.toBeNull();
      returnedTopic = 18;
      await expect(session.unpinAllPreview("-42", topic)).resolves.toBeNull();
      returnedTopic = 17;
      name = "Renamed fixture";
      await expect(session.unpinAllMessages("-42", "51", topic)).resolves.toBe("changed");
      name = topic.name;
    }
    await expect(session.unpinAllPreview("-42", topic)).resolves.toBe("51");
    pin = 52;
    await expect(session.unpinAllMessages("-42", "51", topic)).resolves.toBe("changed");
    permission = false;
    await expect(session.unpinAllMessages("-42", "52", topic)).resolves.toBe("changed");
    expect(sent()).toEqual([]);
    permission = true;
    await expect(session.unpinAllMessages("-42", "52", topic)).resolves.toBe("updated");
    expect(sent()).toEqual([topic ? { "@type": "unpinAllForumTopicMessages", chat_id: -42, forum_topic_id: 17 }
      : { "@type": "unpinAllChatMessages", chat_id: -42 }]);
  } finally { await session.close(); }
});

