test("paginates eligible speech notes and skips protected and oversized notes before decoding", async () => {
  const note = (id: number, duration: number, protectedContent = false) => ({
    "@type": "message", chat_id: -42, id, date: 300, has_protected_content: protectedContent,
    topic_id: { "@type": "messageTopicForum", forum_topic_id: 17 },
    content: { "@type": "messageVoiceNote", voice_note: {
      "@type": "voiceNote", duration, voice: { "@type": "file", id, size: 3000 },
    } },
  });
  const rows = [note(15, 30, true), note(14, 601), note(13, 600), note(12, 601), note(11, 10), note(10, 601), note(9, 10)];
  const transcribe = vi.fn(async (id: string) => `Synthetic transcript ${id}`);
  const engine = vi.spyOn(localTranscription, "createLocalTranscription").mockReturnValue({ transcribe, clear: vi.fn() });
  const { session, request } = harness((query) => {
    switch (query["@type"]) {
      case "getAuthorizationState": return { "@type": "authorizationStateReady" };
      case "getChat": return { "@type": "chat", id: -42, title: "Fixture forum" };
      case "getForumTopicHistory": return { "@type": "messages", messages: rows };
      case "getMessage": return rows.find(({ id }) => id === query.message_id)!;
      default: throw new Error("Unexpected fixture request");
    }
  });
  try {
    await vi.waitFor(() => expect(session.status().state).toBe("ready"));
    const range = { from: 0, until: 86400 };
    const first = await session.historyInDateRange("-42", range, undefined, undefined, 17);
    expect(first).toMatchObject({ before: "10", messages: [
      { id: "15", withheld: true }, { id: "14", voiceTranscript: "unavailable" }, { id: "13", voiceTranscript: "local" },
      { id: "12", voiceTranscript: "unavailable" }, { id: "11", voiceTranscript: "local" }, { id: "10", voiceTranscript: "unavailable" },
    ] });
    expect(await session.historyInDateRange("-42", range, first.before!, undefined, 17)).toMatchObject({
      messages: [{ id: "9", text: "Synthetic transcript -42:9", voiceTranscript: "local" }],
    });
    expect(transcribe.mock.calls.map(([id]) => id)).toEqual(["-42:13", "-42:11", "-42:9"]);
    expect(request.mock.calls.some(([query]) => query["@type"] === "downloadFile")).toBe(false);
  } finally {
    engine.mockRestore();
    await session.close();
  }
});

test("shares local transcripts only while the agent has access and the chat allows sharing", async () => {
  const directory = await mkdtemp(join(tmpdir(), "makosh-agent-voice-"));
  const path = join(directory, "fixture.ogg");
  const bytes = Buffer.from("Synthetic voice fixture");
  await writeFile(path, bytes);
  let protectedContent = false;
  let protectDuringTranscription = false;
  let revokeDuringTranscription = false;
  let granted = false;
  const host = createFakePluginHost({ pluginId: "makosh-telegram" });
  const downloads = registerDocumentDownloads(host.bb, () => undefined);
  let releaseCleanup!: () => void;
  let releaseDownload!: () => void;
  const cacheCleanup = new Promise<void>((resolve) => { releaseCleanup = resolve; });
  const nativeDownload = new Promise<void>((resolve) => { releaseDownload = resolve; });
  const trimDuringInference = vi.fn(async () => "cache cleared");
  const decodedAudio = vi.fn();
  const transcribe = vi.fn(async (_id: string, _key: string, getAudio: () => Promise<Buffer>) => {
    decodedAudio(await getAudio());
    await expect(downloads.cleanCache(trimDuringInference)).resolves.toBe("cache cleared");
    if (protectDuringTranscription) protectedContent = true;
    if (revokeDuringTranscription) granted = false;
    return "Synthetic transcript";
  });
  const engine = vi.spyOn(localTranscription, "createLocalTranscription").mockReturnValue({ transcribe, clear: vi.fn() });
  const speech = {
    "@type": "message", chat_id: -42, id: 14, date: 300,
    topic_id: { "@type": "messageTopicForum", forum_topic_id: 17 },
    content: { "@type": "messageVoiceNote", voice_note: { "@type": "voiceNote", duration: 1, voice: { "@type": "file", id: 14, size: 100 } } },
  };
  const { session, request } = harness(async (query) => {
    switch (query["@type"]) {
      case "getAuthorizationState": return { "@type": "authorizationStateReady" };
      case "getChat": return { "@type": "chat", id: -42, title: "Fixture forum", has_protected_content: protectedContent };
      case "downloadFile":
        await nativeDownload;
        return { "@type": "file", id: 14, local: { "@type": "localFile", is_downloading_completed: true, path } };
      case "getMessage": return speech;
      case "getForumTopicHistory": return { "@type": "messages", messages: [speech, {
        "@type": "message", chat_id: -42, id: 13, date: 299,
        topic_id: { "@type": "messageTopicForum", forum_topic_id: 17 },
        content: { "@type": "messageText", text: { "@type": "formattedText", text: "Earlier fixture message" } },
      }] };
      default: throw new Error("Unexpected fixture request");
    }
  }, vi.fn(), { directory, withMediaCacheTransfer: downloads.withCacheTransfer });
  try {
    await vi.waitFor(() => expect(session.status().state).toBe("ready"));
    type Input = { chatId: string; dateFrom: string; dateTo: string; forumTopicId: number };
    type Context = Pick<PluginAgentToolContext, "threadId" | "signal">;
    const tools = new Map<string, (input: Input, context: Context) => Promise<string>>();
    const bb = { agents: { registerTool: (tool: { name: string; execute: (input: Input, context: Context) => Promise<string> }) => {
      tools.set(tool.name, tool.execute);
    } } } as unknown as BbPluginApi;
    const context = { threadId: "fixture", signal: new AbortController().signal };
    registerAgentHistory(bb, async () => granted ? ["-42"] : ["-43"], () => session, () => context.signal);
    const read = () => tools.get(agentHistoryTool)!({
      chatId: "-42", dateFrom: "1970-01-01", dateTo: "1970-01-01", forumTopicId: 17,
    }, context);

    expect(JSON.parse(await read())).toHaveProperty("error");
    expect(transcribe).not.toHaveBeenCalled();
    expect(request.mock.calls.some(([query]) => query["@type"] === "downloadFile")).toBe(false);
    granted = true;
    const cleaning = downloads.cleanCache(() => cacheCleanup);
    const reading = read();
    await vi.waitFor(() => expect(transcribe).toHaveBeenCalledTimes(1));
    expect(request.mock.calls.some(([query]) => query["@type"] === "downloadFile")).toBe(false);
    releaseCleanup();
    await cleaning;
    await vi.waitFor(() => expect(request.mock.calls.some(([query]) => query["@type"] === "downloadFile")).toBe(true));
    await expect(downloads.cleanCache(trimDuringInference)).resolves.toBeUndefined();
    expect(trimDuringInference).not.toHaveBeenCalled();
    releaseDownload();
    expect(JSON.parse(await reading).messages).toMatchObject([
      { id: "14", text: "Synthetic transcript", voiceTranscript: "local" },
      { id: "13", text: "Earlier fixture message" },
    ]);
    expect(decodedAudio).toHaveBeenCalledExactlyOnceWith(bytes);
    expect(trimDuringInference).toHaveBeenCalledTimes(1);
    expect(request.mock.calls.map(([query]) => query).filter((query) => query["@type"] === "downloadFile")).toEqual([
      expect.objectContaining({ file_id: 14, synchronous: true }),
    ]);

    revokeDuringTranscription = true;
    expect(await read()).toBe("Telegram history access changed. No messages were shared.");
    expect(transcribe).toHaveBeenCalledTimes(2);
    revokeDuringTranscription = false;
    granted = true;

    protectDuringTranscription = true;
    const result = await read();
    expect(transcribe).toHaveBeenCalledTimes(3);
    expect(result).toBe("Could not read this Telegram conversation for the requested period.");
  } finally {
    releaseCleanup();
    releaseDownload();
    await session.close();
    await host.harness.lifecycle.dispose();
    engine.mockRestore();
    await rm(directory, { recursive: true, force: true });
  }
});

test.each(["group", "bot"] as const)("checks a %s topic and its reply again before the approved send", async (kind) => {
  const chat_id = kind === "group" ? -42 : 42;
  const chatId = String(chat_id);
  let open = true;
  let topicName = "Fixture topic";
  let botTopics = true;
  let groupForum = true;
  let changeWhileCheckingRights: (() => void) | undefined;
  let text = "Original from another participant";
  const topic = { "@type": "messageTopicForum", forum_topic_id: 17 };
  const original = () => ({
    "@type": "message", chat_id, id: 12, date: 300, topic_id: topic, is_outgoing: false,
    sender_id: { "@type": "messageSenderUser", user_id: 7 },
    content: { "@type": "messageText", text: { "@type": "formattedText", text } },
  });
  const { session, request } = harness((query) => {
    switch (query["@type"]) {
      case "getAuthorizationState": return { "@type": "authorizationStateReady" };
      case "getChat":
        changeWhileCheckingRights?.();
        changeWhileCheckingRights = undefined;
        return { "@type": "chat", id: chat_id, title: "Fixture conversation", type: kind === "group"
          ? { "@type": "chatTypeSupergroup", supergroup_id: 42, is_channel: false } : { "@type": "chatTypePrivate", user_id: chat_id } };
      case "getSupergroup": return { "@type": "supergroup", id: 42, is_forum: groupForum, is_channel: false,
        status: { "@type": "chatMemberStatusCreator", is_member: true } };
      case "getUser": return { "@type": "user", id: query.user_id, first_name: "Fixture participant",
        ...(query.user_id === 42 && { type: { "@type": "userTypeBot", has_topics: botTopics } }) };
      case "getForumTopicHistory": return { "@type": "messages", messages: [original()] };
      case "getForumTopic": return { "@type": "forumTopic", info: {
        "@type": "forumTopicInfo", chat_id, forum_topic_id: 17, name: topicName, is_closed: !open,
      } };
      case "getMessage": return original();
      case "sendMessage": return { "@type": "message", chat_id, id: 13, topic_id: topic, reply_to_message_id: query.reply_to_message_id };
      default: throw new Error("Unexpected TDLib request");
    }
  });
  await vi.waitFor(() => expect(session.status()).toEqual({ state: "ready" }));
  type Context = Pick<PluginAgentToolContext, "threadId" | "signal">;
  type Input = { chatId: string; dateFrom: string; dateTo: string; forumTopicId: number }
    | { replyToken: string; text: string } | { recipientId: string; forumTopicId: number; text: string };
  const tools = new Map<string, (input: Input, context: Context) => Promise<string>>();
  const requestInput = vi.fn<BbPluginApi["ui"]["requestInput"]>();
  const bb = { agents: { registerTool: (tool: { name: string; execute: (input: Input, context: Context) => Promise<string> }) => {
    tools.set(tool.name, tool.execute);
  } }, ui: { requestInput } } as unknown as BbPluginApi;
  const tokens = createReplyTokens();
  const context = { threadId: "fixture", signal: new AbortController().signal };
  registerAgentHistory(bb, async () => [chatId], () => session, () => context.signal, tokens);
  registerAgentSend(bb, async () => true, () => session, tokens);
  const result = JSON.parse(await tools.get(agentHistoryTool)!({
    chatId, dateFrom: "1970-01-01", dateTo: "1970-01-01", forumTopicId: 17,
  }, context));
  expect(result.messages).toEqual([{
    id: "12", text: "Original from another participant", author: "Fixture participant", date: 300, forumTopicId: 17,
    replyToken: expect.any(String),
  }]);
  expect(requestInput).not.toHaveBeenCalled();
  const dispatches = () => request.mock.calls.filter(([query]) => query["@type"] === "sendMessage");
  const reply = () => tools.get(agentSendTool)!({ replyToken: result.messages[0].replyToken, text: "Reviewed reply" }, context);
  const draft = () => tools.get(agentSendTool)!({ recipientId: chatId, forumTopicId: 17, text: "Reviewed new message" }, context);

  if (kind === "bot") {
    botTopics = false;
    await expect(draft()).resolves.toContain("topic is unavailable");
    expect(requestInput).not.toHaveBeenCalled();
    botTopics = true;
  }
  requestInput.mockResolvedValueOnce({ outcome: "cancelled", reason: "user" });
  await expect(reply()).resolves.toContain("Nothing was sent");
  expect(dispatches()).toHaveLength(0);
  for (const change of [() => { open = false; }, () => { topicName = "Renamed topic"; }, () => { text = "Edited participant message"; },
    () => { botTopics = false; groupForum = false; }]) {
    requestInput.mockImplementationOnce(async () => {
      changeWhileCheckingRights = change;
      return { outcome: "submitted", value: { id: chatId } };
    });
    await expect(reply()).resolves.toContain("no longer available. Nothing was sent.");
    expect(dispatches()).toHaveLength(0);
    open = true;
    botTopics = true;
    groupForum = true;
    topicName = "Fixture topic";
    text = "Original from another participant";
  }
  requestInput.mockImplementationOnce(async ({ payload }) => {
    expect(payload).toMatchObject({ text: "Reviewed reply", replyPreview: "Original from another participant",
      forumTopic: { id: 17, name: "Fixture topic" }, recipients: [{ id: chatId, kind: kind === "group" ? "Group" : "Direct message" }] });
    expect(dispatches()).toHaveLength(0);
    return { outcome: "submitted", value: { id: chatId } };
  });
  await expect(reply()).resolves.toBe("Telegram confirmed the message was sent.");
  await expect(reply()).resolves.toContain("invalid or expired");
  expect(dispatches()).toEqual([[expect.objectContaining({ chat_id, topic_id: topic,
    reply_to: { "@type": "inputMessageReplyToMessage", message_id: 12 },
    input_message_content: expect.objectContaining({ text: { "@type": "formattedText", text: "Reviewed reply", entities: [] } }),
  })]]);
  if (kind === "bot") {
    requestInput.mockImplementationOnce(async ({ payload }) => {
      expect(payload).toMatchObject({ text: "Reviewed new message", showRecipientId: true, forumTopic: { id: 17, name: "Fixture topic" } });
      expect(dispatches()).toHaveLength(1);
      return { outcome: "submitted", value: { id: chatId } };
    });
    await expect(draft()).resolves.toContain("confirmed");
    expect(dispatches()).toHaveLength(2);
    expect(dispatches()[1]?.[0]).toMatchObject({ chat_id, topic_id: topic });
    expect(dispatches()[1]?.[0]).not.toHaveProperty("reply_to");
  }
  await session.close();
});

test("keeps large Telegram history pages below the response budget without losing messages", async () => {
  const rows = Array.from({ length: 12 }, (_, index) => ({
    "@type": "message", id: 30 - index, date: 499 - index, chat_id: -42,
    content: { "@type": "messageText", text: { "@type": "formattedText", text: "Я".repeat(4096) } },
  }));
  const { session } = harness((query) => {
    switch (query["@type"]) {
      case "getAuthorizationState": return { "@type": "authorizationStateReady" };
      case "getChat": return { "@type": "chat", id: -42, title: "Fixture group" };
      case "getChatMessageByDate": return rows[0]!;
      case "getChatHistory": return { "@type": "messages", messages: rows.filter((row) => row.id <= Number(query.from_message_id)) };
      default: throw new Error("Unexpected test query");
    }
  });
  await vi.waitFor(() => expect(session.status()).toEqual({ state: "ready" }));
  const ids: string[] = [];
  let before: string | null | undefined;
  for (let page = 0; page < 4; page++) {
    const result = await session.historyInDateRange("-42", { from: 200, until: 500 }, before ?? undefined);
    expect(Buffer.byteLength(JSON.stringify(result))).toBeLessThan(49 * 1024);
    ids.push(...result.messages.map(({ id }) => id));
    before = result.before;
    if (!before) break;
  }
  expect(before).toBeNull();
  expect(ids).toEqual(rows.map(({ id }) => String(id)));
});

test.each(["modern", "legacy"] as const)("searches only granted chats using a %s cursor", async (mode) => {
  const hit = (id: number, chat_id: number, date: number) => ({
    "@type": "message", id, chat_id, date,
    content: { "@type": "messageText", text: { "@type": "formattedText", text: "Private fixture" } },
  });
  const { session, request } = harness((query) => {
    switch (query["@type"]) {
      case "getAuthorizationState": return { "@type": "authorizationStateReady" };
      case "getChat": return { "@type": "chat", id: query.chat_id,
        title: query.chat_id === -41 ? "Fixture group" : "Other title", has_protected_content: query.chat_id === -43 };
      case "getChatMessageByDate": return {
        ...hit(60, Number(query.chat_id), 499), content: { "@type": "messageText", text: { "@type": "formattedText", text: "Nonmatching anchor" } },
      };
      case "searchChatMessages": return { "@type": mode === "modern" ? "foundChatMessages" : "messages",
        next_from_message_id: 50, messages: query.from_message_id === 60 ? [hit(50, -42, 500)] : [hit(40, -42, 400)] };
      default: throw new Error("Unexpected TDLib query outside the granted chats");
    }
  });
  await vi.waitFor(() => expect(session.status()).toEqual({ state: "ready" }));
  const range = { from: 200, until: 500 };
  const granted = ["-41", "-42", "-43"];
  const first = await session.findRelatedChats("Fixture", range, granted);
  expect(first.chats).toMatchObject([{ id: "-41", matchedName: true }]);
  expect(first.next).toEqual({ chatId: "-42", before: "50" });
  const second = await session.findRelatedChats("Fixture", range, granted, first.next!);
  expect(second).toMatchObject({ chats: [{ id: "-42", matchedMessages: true }], next: null });
  expect(JSON.stringify(second)).not.toContain("Private fixture");
  expect(request.mock.calls.filter(([query]) => query["@type"] === "searchChatMessages")
    .map(([query]) => [query.chat_id, query.from_message_id])).toEqual([[-42, 60], [-42, 50]]);
});

test("discovers a granted chat by a rich message at the date boundary and reads its visible text", async () => {
  const rich = { "@type": "message", id: 60, chat_id: -42, date: 499, is_outgoing: false,
    content: { "@type": "messageRichMessage", message: { "@type": "richMessage", is_full: true, blocks: [
      { "@type": "pageBlockParagraph", text: { "@type": "richTexts", texts: [
        { "@type": "richTextPlain", text: "🙂 Project fixture " },
        { "@type": "richTextSpoiler", text: { "@type": "richTextPlain", text: "Hidden fixture" } },
        { "@type": "richTextPlain", text: " confirmed" },
      ] } },
    ] } },
  };
  let protectedContent = false;
  const { session, request } = harness((query) => {
    switch (query["@type"]) {
      case "getAuthorizationState": return { "@type": "authorizationStateReady" };
      case "getChat": return { "@type": "chat", id: query.chat_id, title: "Unrelated name" };
      case "getChatMessageByDate": return { ...rich, has_protected_content: protectedContent };
      case "getChatHistory":
      case "searchChatMessages": return { "@type": "messages", messages: [] };
      default: throw new Error("Unexpected rich history query");
    }
  });
  await vi.waitFor(() => expect(session.status().state).toBe("ready"));
  const dates = { from: 200, until: 500 };
  const found = await session.findRelatedChats("Project fixture", dates, ["-42"]);
  expect(found).toMatchObject({ chats: [{ id: "-42", matchedName: false, matchedMessages: true }] });
  expect(JSON.stringify(found)).not.toContain("Project fixture");
  expect(request.mock.calls.some(([query]) => query["@type"] === "searchChatMessages")).toBe(false);
  expect((await session.historyInDateRange("-42", dates)).messages).toMatchObject([{ id: "60", text: "🙂 Project fixture Spoiler confirmed" }]);
  expect((await session.findRelatedChats("Hidden fixture", dates, ["-42"])).chats).toEqual([]);
  protectedContent = true;
  expect((await session.findRelatedChats("Project fixture", dates, ["-42"])).chats).toEqual([]);
  expect((await session.historyInDateRange("-42", dates)).messages).toMatchObject([{ id: "60", withheld: true }]);
});

test("shares only published messages across Telegram agent discovery, search and history", async () => {
  const topic = { "@type": "messageTopicForum", forum_topic_id: 17 };
  const item = (id: number, text: string, outgoing = false) => ({
    "@type": "message", id, chat_id: -42, date: 85_000 + id, topic_id: topic, is_outgoing: outgoing,
    sender_id: { "@type": "messageSenderUser", user_id: outgoing ? 42 : 7 },
    content: { "@type": "messageText", text: { "@type": "formattedText", text } },
  });
  const unpublished = [
    { ...item(79, "Scheduled fixture"), scheduling_state: { "@type": "messageSchedulingStateSendAtDate", send_date: 85_079 } },
    { ...item(78, "Ephemeral fixture"), ephemeral_content: true },
  ];
  const published = [item(77, "Published fixture from someone else"), item(76, "Published fixture from the account", true)];
  let matches: ReturnType<typeof item>[] = unpublished;
  let conversationProtected = false;
  let protectAfterSearch = false;
  const { session, request } = harness((query) => {
    switch (query["@type"]) {
      case "getAuthorizationState": return { "@type": "authorizationStateReady" };
      case "getChat": return { "@type": "chat", id: query.chat_id, title: "Group only", has_protected_content: conversationProtected };
      case "getChatMessageByDate": return unpublished[0]!;
      case "getUser": return { "@type": "user", id: query.user_id, first_name: "Fixture participant" };
      case "getForumTopicHistory": return { "@type": "messages", messages: [...unpublished, ...published] };
      case "searchChatMessages":
        if (protectAfterSearch) conversationProtected = true;
        return { "@type": "foundChatMessages", next_from_message_id: 0, messages: matches };
      default: throw new Error("Unexpected fixture query");
    }
  });
  type Context = Pick<PluginAgentToolContext, "threadId" | "signal">;
  type Input = { dateFrom: string; dateTo: string; query?: string; chatId?: string; forumTopicId?: number };
  const tools = new Map<string, (input: Input, context: Context) => Promise<string>>();
  const requestInput = vi.fn();
  const bb = { agents: { registerTool: (tool: { name: string; execute: (input: Input, context: Context) => Promise<string> }) => {
    tools.set(tool.name, tool.execute);
  } }, ui: { requestInput } } as unknown as BbPluginApi;
  try {
    await vi.waitFor(() => expect(session.status().state).toBe("ready"));
    const context = { threadId: "agent-scope-fixture", signal: new AbortController().signal };
    registerAgentHistory(bb, async () => ["-42"], () => session, () => context.signal);
    const dates = { dateFrom: "1970-01-01", dateTo: "1970-01-01" };
    const scope = { ...dates, chatId: "-42", forumTopicId: 17 };
    const find = async () => JSON.parse(await tools.get(agentFindChatsTool)!({ ...dates, query: "fixture" }, context));
    expect(await find()).toEqual({ chats: [], next: null });
    matches = [...unpublished, ...published];
    expect(await find()).toMatchObject({ chats: [{ id: "-42", matchedMessages: true }], next: null });
    protectAfterSearch = true;
    expect(await find()).toEqual({ chats: [], next: null });
    protectAfterSearch = false;
    conversationProtected = false;

    const search = JSON.parse(await tools.get(agentSearchMessagesTool)!({ ...scope, query: "fixture" }, context));
    const history = JSON.parse(await tools.get(agentHistoryTool)!(scope, context));
    for (const page of [search, history]) {
      expect(page.messages.map(({ id, author }: { id: string; author: string }) => [id, author])).toEqual([
        ["77", "Fixture participant"], ["76", "You"],
      ]);
    }
    await expect(tools.get(agentHistoryTool)!({ ...scope, chatId: "-43" }, context)).resolves.toContain("disabled");
    expect(request).not.toHaveBeenCalledWith(expect.objectContaining({ chat_id: -43 }));
    expect(requestInput).not.toHaveBeenCalled();
  } finally { await session.close(); }
});

