test("downloads the sized Telegram preview and larger photo by different file IDs", async () => {
  const directory = await mkdtemp(join(tmpdir(), "makosh-photo-sizes-"));
  const path = join(directory, "photo.jpg");
  let failure = false;
  try {
    await writeFile(path, Buffer.from("ffd8ffe00000000000000000", "hex"));
    const photo = { "@type": "photo", sizes: [
      { "@type": "photoSize", width: 90, height: 90, photo: { "@type": "file", id: 1 } },
      { "@type": "photoSize", width: 640, height: 480, photo: { "@type": "file", id: 2 } },
      { "@type": "photoSize", width: 1280, height: 960, photo: { "@type": "file", id: 3 } },
    ] };
    const { session, request } = harness((query) => {
      switch (query["@type"]) {
        case "getAuthorizationState": return { "@type": "authorizationStateReady" };
        case "getMessage": return query.message_id === 27
          ? { "@type": "message", id: 27, chat_id: 42, content: { "@type": "messagePaidMedia", star_count: 12,
            media: [{ "@type": "paidMediaPhoto", photo }, { "@type": "paidMediaVideo", cover: photo }] } }
          : query.message_id === 25
          ? { "@type": "message", id: 25, chat_id: 42, content: { "@type": "messagePhoto", photo } }
          : { "@type": "message", id: 26, chat_id: 42, content: { "@type": "messageRichMessage",
            message: { "@type": "richMessage", blocks: [{ "@type": "pageBlockDivider" }, { "@type": "pageBlockPhoto", photo }] },
          } };
        case "downloadFile": return { "@type": "file", id: query.file_id,
          local: { "@type": "localFile", is_downloading_completed: !failure, path } };
        default: throw new Error("Unexpected test query");
      }
    }, undefined, directory);
    await vi.waitFor(() => expect(session.status()).toEqual({ state: "ready" }));
    await expect(session.photo("42", "25")).resolves.toMatchObject({ mime: "image/jpeg", hasLarger: true });
    await expect(session.photo("42", "25", "large")).resolves.toMatchObject({ mime: "image/jpeg" });
    const attachment = { index: 1, fileId: 3 };
    await expect(session.photo("42", "25", "preview", attachment)).rejects.toThrow("No eligible photo");
    await expect(session.photo("43", "26", "preview", attachment)).rejects.toThrow("No eligible photo");
    await expect(session.photo("42", "26", "preview", { ...attachment, index: 0 })).rejects.toThrow("No eligible photo");
    await expect(session.photo("42", "26", "preview", { ...attachment, fileId: 2 })).rejects.toThrow("No eligible photo");
    failure = true;
    const failed = await Promise.allSettled([session.photo("42", "25"), session.photo("42", "26", "preview", attachment)]);
    expect(failed.map(({ status }) => status)).toEqual(["rejected", "rejected"]);
    failure = false;
    await expect(Promise.all([session.photo("42", "25"), session.photo("42", "26", "preview", attachment)]))
      .resolves.toMatchObject([{ mime: "image/jpeg", hasLarger: true }, { mime: "image/jpeg", hasLarger: true }]);
    await expect(session.photo("42", "26", "large", attachment)).resolves.toMatchObject({ mime: "image/jpeg" });
    await expect(session.photo("42", "27", "preview", { index: 0, fileId: 3, paid: true })).resolves.toMatchObject({ mime: "image/jpeg", hasLarger: true });
    await expect(session.photo("42", "27", "preview", { index: 1, fileId: 2, paid: true })).rejects.toThrow("No eligible photo");
    await expect(session.photo("42", "27", "preview", { index: 1, fileId: 3, paid: true })).resolves.toMatchObject({ mime: "image/jpeg", hasLarger: true });
    const downloads = request.mock.calls.filter(([query]) => query["@type"] === "downloadFile");
    expect(downloads.map(([query]) => query.file_id)).toEqual([2, 3, 2, 2, 3, 2, 2]);
  } finally {
    await rm(directory, { recursive: true, force: true });
  }
});

