test("binds a community video avatar to the current visible photo and animation file", async () => {
  let access = true;
  let animated = true;
  let photoId = "9007199254741999";
  let videoId = 51;
  const { session, request } = harness((query) => {
    switch (query["@type"]) {
      case "getAuthorizationState": return { "@type": "authorizationStateReady" };
      case "getJoinedCommunities": return { "@type": "communities", community_ids: [7] };
      case "getCurrentState": return { "@type": "updates", updates: [{ "@type": "updateCommunity", community: {
        "@type": "community", id: 7, have_access: access, name: "Fixture community",
        status: { "@type": "communityMemberStatusMember" },
        photo: { "@type": "chatPhotoInfo", has_animation: animated },
      } }] };
      case "getCommunityFullInfo": return { "@type": "communityFullInfo", photo: {
        "@type": "chatPhoto", id: photoId,
        animation: null,
        small_animation: { "@type": "animatedChatPhoto", file: { "@type": "file", id: videoId, size: 128 } },
      } };
      default: throw new Error("Unexpected community video request");
    }
  });
  await vi.waitFor(() => expect(session.status().state).toBe("ready"));
  await expect(session.joinedCommunities()).resolves.toMatchObject([{ id: "7", hasAvatarVideo: true }]);
  expect(request.mock.calls.some(([query]) => query["@type"] === "getCommunityFullInfo")).toBe(false);
  await expect(session.communityAvatarVideoInfo("7")).resolves.toEqual({ photoId, fileId: 51 });
  await expect(session.communityAvatarVideoReference("7", photoId, 51)).resolves.toEqual({ id: 51, size: 128, mime: "video/mp4" });
  const originalPhoto = photoId;
  photoId = "9007199254742000";
  await expect(session.communityAvatarVideoReference("7", originalPhoto, 51)).rejects.toThrow("Community video unavailable");
  videoId = 52;
  await expect(session.communityAvatarVideoReference("7", photoId, 51)).rejects.toThrow("Community video unavailable");
  animated = false;
  await expect(session.communityAvatarVideoInfo("7")).resolves.toBeNull();
  animated = true;
  access = false;
  await expect(session.communityAvatarVideoReference("7", photoId, 52)).rejects.toThrow("Community video unavailable");
});

test("updates a community photo only with current edit rights and photo version", async () => {
  const directory = await mkdtemp(join(tmpdir(), "makosh-community-photo-"));
  const path = join(directory, "fixture.png");
  const preview = "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+aV9sAAAAASUVORK5CYII=";
  await writeFile(path, Buffer.from(preview, "base64"));
  const jpeg = Buffer.from([0xff, 0xd8, 0xff, 0xc0, 0, 8, 8, 0, 1, 0, 1, 1, 0xff, 0xd9]).toString("base64");
  let photoId = 0;
  let allowed = false;
  const { session, request } = harness((query) => {
    switch (query["@type"]) {
      case "getAuthorizationState": return { "@type": "authorizationStateReady" };
      case "getCurrentState": return { "@type": "updates", updates: [
        { "@type": "updateCommunity", community: { "@type": "community", id: 7, name: "Fixture", have_access: true,
          photo: photoId ? { "@type": "chatPhotoInfo", small: { "@type": "file", id: photoId } } : null,
          status: { "@type": "communityMemberStatusAdministrator",
            rights: { "@type": "communityAdministratorRights", can_change_info: allowed } } } },
      ] };
      case "setCommunityPhoto": photoId = query.photo === null ? 0 : 77; return { "@type": "ok" };
      case "downloadFile": return { "@type": "file", id: query.file_id,
        local: { "@type": "localFile", is_downloading_completed: true, path } };
      default: throw new Error("Unexpected community request");
    }
  }, undefined, directory);
  try {
    await vi.waitFor(() => expect(session.status().state).toBe("ready"));
    await expect(session.changeCommunityPhoto("7", null, jpeg)).resolves.toBe("unavailable");
    allowed = true;
    await expect(session.communityPhotoState("7")).resolves.toEqual({ version: null });
    await expect(session.changeCommunityPhoto("7", null, jpeg)).resolves.toBe("saved");
    const version = (await session.communityPhotoState("7"))!.version!;
    await expect(session.communityAvatar("7", 78)).rejects.toThrow("unavailable");
    expect(request.mock.calls.some(([query]) => query["@type"] === "downloadFile")).toBe(false);
    await expect(session.communityAvatar("7", 77)).resolves.toEqual({ mime: "image/png", base64: preview });
    await expect(session.changeCommunityPhoto("7", "f".repeat(64))).resolves.toBe("changed");
    await expect(session.changeCommunityPhoto("7", version)).resolves.toBe("saved");
    await expect(session.communityAvatar("7", 77)).rejects.toThrow("unavailable");
    const writes = request.mock.calls.flatMap(([query]) => query["@type"] === "setCommunityPhoto" ? [query] : []);
    expect(writes).toEqual([
      { "@type": "setCommunityPhoto", community_id: 7, photo: {
        "@type": "inputChatPhotoStatic", photo: { "@type": "inputFileLocal", path: expect.any(String) },
      } },
      { "@type": "setCommunityPhoto", community_id: 7, photo: null },
    ]);
  } finally {
    await session.close();
    await rm(directory, { recursive: true, force: true });
  }
});

