test("includes eligible owned bots when creating and adding to communities and rejects stale reviews", async () => {
  let owned = true;
  let attachment = 0;
  const { session, request } = harness((query) => {
    switch (query["@type"]) {
      case "getAuthorizationState": return { "@type": "authorizationStateReady" };
      case "getSuitableCommunityChats": return { "@type": "chats", chat_ids: [-42] };
      case "getOwnedBots": return { "@type": "users", user_ids: [43, 43, 44, 45] };
      case "getUser": return { "@type": "user", id: query.user_id,
        type: { "@type": "userTypeBot", can_be_edited: query.user_id === 43 ? owned : query.user_id === 44 } };
      case "getUserFullInfo": return { "@type": "userFullInfo", community_id: query.user_id === 43 ? attachment : 8 };
      case "createPrivateChat": return { "@type": "chat", id: 43, title: "Fixture bot", type: { "@type": "chatTypePrivate", user_id: query.user_id } };
      case "getChat": return query.chat_id === -42 ? { "@type": "chat", id: -42, title: "Fixture group" }
        : { "@type": "chat", id: 43, title: "Fixture bot", type: { "@type": "chatTypePrivate", user_id: 43 } };
      case "getCurrentState": return { "@type": "updates", updates: [
        { "@type": "updateCommunity", community: { "@type": "community", id: 7, have_access: true, name: "Fixture community",
          status: { "@type": "communityMemberStatusCreator" } } },
      ] };
      case "getCommunityFullInfo": return { "@type": "communityFullInfo", chats: [] };
      case "createCommunity": return { "@type": "communityId", id: 8 };
      case "addCommunityChat": return { "@type": "ok" };
      default: throw new Error("Unexpected community request");
    }
  });
  try {
    await vi.waitFor(() => expect(session.status().state).toBe("ready"));
    expect(schemas.communitySourceChats.output.parse(await session.communitySourceChats())).toEqual([
      { id: "-42", title: "Fixture group" }, { id: "43", title: "Fixture bot", bot: true },
    ]);
    expect(request.mock.calls.flatMap(([query]) => query["@type"] === "createPrivateChat" ? [query] : [])).toEqual([
      { "@type": "createPrivateChat", user_id: 43, force: true },
    ]);
    const create = { id: "43", name: "New fixture", hidden: true, expectedTitle: "Fixture bot" };
    const add = { id: "7", chat: "43", action: "add" as const, hidden: false, expectedTitle: "Fixture bot" };
    const mutations = () => request.mock.calls.flatMap(([query]) =>
      query["@type"] === "createCommunity" || query["@type"] === "addCommunityChat" ? [query] : []);
    expect(mutations()).toEqual([]);
    owned = false;
    await expect(session.createCommunity(create)).resolves.toBeNull();
    await expect(session.changeCommunityChat(add)).resolves.toBe("changed");
    owned = true;
    attachment = 8;
    await expect(session.createCommunity(create)).resolves.toBeNull();
    await expect(session.changeCommunityChat(add)).resolves.toBe("changed");
    attachment = 0;
    await expect(session.createCommunity({ ...create, expectedTitle: "Stale bot name" })).resolves.toBeNull();
    await expect(session.changeCommunityChat({ ...add, expectedTitle: "Stale bot name" })).resolves.toBe("changed");
    expect(mutations()).toEqual([]);
    await expect(session.createCommunity(create)).resolves.toMatchObject({ id: "8" });
    await expect(session.changeCommunityChat(add)).resolves.toBe("saved");
    expect(mutations()).toEqual([
      { "@type": "createCommunity", name: "New fixture", chat_id: 43, is_chat_hidden: true },
      { "@type": "addCommunityChat", community_id: 7, chat_id: 43, is_hidden: false },
    ]);
  } finally { await session.close(); }
});

