test("revalidates profile audio against the chat owner and current track position", async () => {
  let first = 77;
  let protectedChat = false;
  const { session, request } = harness((query) => {
    switch (query["@type"]) {
      case "getAuthorizationState": return { "@type": "authorizationStateReady" };
      case "getMe": return { "@type": "user", id: 41 };
      case "getChat": return { "@type": "chat", id: query.chat_id, has_protected_content: protectedChat,
        type: { "@type": "chatTypePrivate", user_id: 43 } };
      case "getUserProfileAudios": {
        expect(query.user_id).toBe(43);
        const audio = (id: number) => ({ "@type": "audio", title: "Fixture audio", performer: "Fixture performer",
          mime_type: id === 78 ? "audio/x-flac" : "audio/mpeg", audio: { "@type": "file", id, size: 1024 } });
        return { "@type": "audios", total_count: 2, audios: [audio(first), audio(78)]
          .slice(Number(query.offset), Number(query.offset) + Number(query.limit)) };
      }
      default: throw new Error("Unexpected profile audio request");
    }
  });
  try {
    await vi.waitFor(() => expect(session.status().state).toBe("ready"));
    await expect(session.profileAudio("42", 0)).resolves.toMatchObject({ next: null, tracks: [
      { index: 0, fileId: 77, title: "Fixture audio", performer: "Fixture performer", mime: "audio/mpeg" },
      { index: 1, fileId: 78, mime: "audio/flac" },
    ] });
    await expect(session.profileAudioReference("42", 0, 77)).resolves.toEqual({ id: 77, size: 1024, mime: "audio/mpeg" });
    await expect(session.profileAudioReference("42", 1, 78)).resolves.toEqual({ id: 78, size: 1024, mime: "audio/flac" });
    first = 79;
    await expect(session.profileAudioReference("42", 0, 77)).rejects.toThrow("unavailable");
    protectedChat = true;
    request.mockClear();
    await expect(session.profileAudio("42", 0)).resolves.toBeNull();
    expect(request.mock.calls.some(([query]) => query["@type"] === "getUserProfileAudios")).toBe(false);
  } finally { await session.close(); }
});

