    await expect(session.changeProfileAudio("42", { index: 1, fileId: 78, action: "down", neighbor: 79 })).resolves.toBe("saved");
    await expect(session.changeProfileAudio("42", { index: 1, fileId: 78, action: "remove" })).resolves.toBe("saved");
