test("reports playback only for matching, ordinary incoming voice and video notes", async () => {
  const file = { "@type": "file", id: 77, size: 1024 };
  const voice = { "@type": "messageVoiceNote", is_listened: false,
    voice_note: { "@type": "voiceNote", mime_type: "audio/ogg", voice: file } };
  const video = { "@type": "messageVideoNote", is_viewed: false,
    video_note: { "@type": "videoNote", video: file } };
  const row = (id: number, content: TdObject, extra?: TdObject) => ({
    ...extra, "@type": "message", chat_id: 42, id, is_outgoing: extra?.is_outgoing ?? false, content,
  });
  const rows = [row(8, voice), row(9, video), row(10, { ...voice, is_listened: true }),
    row(11, voice, { "@type": "message", is_outgoing: true }), row(12, video, { "@type": "message", ttl: 20 })];
  const { session, request } = harness((query) => {
    switch (query["@type"]) {
      case "getAuthorizationState": return { "@type": "authorizationStateReady" };
      case "getChat": return { "@type": "chat", id: 42, type: { "@type": "chatTypePrivate", user_id: 42 } };
      case "getChatHistory": return { "@type": "messages", messages: rows };
      case "getMessage": return rows.find(({ id }) => id === query.message_id) ?? { "@type": "ok" };
      case "openMessageContent": return { "@type": "ok" };
      default: throw new Error("Unexpected fixture query");
    }
  });
  try {
    await vi.waitFor(() => expect(session.status().state).toBe("ready"));
    const page = await session.history("42");
    expect(page.messages.find(({ id }) => id === "8")?.notePlayed).toBe(false);
    expect(page.messages.find(({ id }) => id === "10")?.notePlayed).toBe(true);
    expect(page.messages.find(({ id }) => id === "12")?.notePlayed).toBeUndefined();
    await expect(session.markNotePlayed("42", "8")).resolves.toBe(true);
    await expect(session.markNotePlayed("42", "9")).resolves.toBe(true);
    await expect(session.markNotePlayed("42", "10")).resolves.toBe(true);
    for (const id of ["11", "12", "13"]) await expect(session.markNotePlayed("42", id)).resolves.toBe(false);
    await expect(session.markNotePlayed("43", "8")).resolves.toBe(false);
    expect(request.mock.calls.filter(([query]) => query["@type"] === "openMessageContent").map(([query]) => query)).toEqual([
      { "@type": "openMessageContent", chat_id: 42, message_id: 8 },
      { "@type": "openMessageContent", chat_id: 42, message_id: 9 },
    ]);
  } finally { await session.close(); }
});

