test("edits the selected chat's reaction policy only with current permissions and settings", async () => {
  let editable = true;
  let available = { "@type": "chatAvailableReactionsAll", max_reaction_count: 5 } as TdObject;
  const { session, request } = harness((query) => {
    switch (query["@type"]) {
      case "getAuthorizationState": return { "@type": "authorizationStateReady" };
      case "getChat": return { "@type": "chat", id: -42, available_reactions: available,
        type: { "@type": "chatTypeSupergroup", supergroup_id: 7, is_channel: true } };
      case "getSupergroup": return { "@type": "supergroup", id: 7, is_channel: true,
        status: { "@type": "chatMemberStatusAdministrator", rights: { "@type": "chatAdministratorRights", can_change_info: editable } },
      };
      case "getCurrentState": return { "@type": "updates", updates: [
        { "@type": "updateActiveEmojiReactions", emojis: ["👍", "❤️", "👍"] },
      ] };
      case "setChatAvailableReactions": available = query.available_reactions as TdObject; return { "@type": "ok" };
      default: throw new Error("Unexpected fixture call");
    }
  });
  await vi.waitFor(() => expect(session.status()).toEqual({ state: "ready" }));
  const baseline = { mode: "all" as const, limit: 5 };
  const selected = { mode: "selected" as const, limit: 2, reactions: [
    { kind: "emoji" as const, emoji: "👍" }, { kind: "custom" as const, id: "9007199254740993" },
  ] };
  await expect(session.chatReactionSettings("-42")).resolves.toEqual({
    channel: true, editable: true, policy: baseline, activeEmoji: ["👍", "❤️"],
  });
  editable = false;
  await expect(session.setChatReactionPolicy("-42", selected, baseline)).resolves.toBe("unavailable");
  editable = true;
  await expect(session.setChatReactionPolicy("-43", selected, baseline)).resolves.toBe("unavailable");
  await expect(session.setChatReactionPolicy("-42", selected, { ...baseline, limit: 4 })).resolves.toBe("changed");
  expect(request.mock.calls.some(([query]) => query["@type"] === "setChatAvailableReactions")).toBe(false);
  await expect(session.setChatReactionPolicy("-42", selected, baseline)).resolves.toBe("saved");
  expect(request).toHaveBeenCalledWith({ "@type": "setChatAvailableReactions", chat_id: -42, available_reactions: {
    "@type": "chatAvailableReactionsSome", max_reaction_count: 2,
    reactions: [{ "@type": "reactionTypeEmoji", emoji: "👍" },
      { "@type": "reactionTypeCustomEmoji", custom_emoji_id: "9007199254740993" }],
  } });
  await expect(session.chatReactionSettings("-42")).resolves.toMatchObject({ policy: selected });
  const withStars = { ...selected, paid: true as const };
  await expect(session.setChatReactionPolicy("-42", withStars, selected)).resolves.toBe("saved");
  expect(request).toHaveBeenCalledWith({ "@type": "setChatAvailableReactions", chat_id: -42, available_reactions: {
    "@type": "chatAvailableReactionsSome", max_reaction_count: 2, reactions: [
      { "@type": "reactionTypeEmoji", emoji: "👍" },
      { "@type": "reactionTypeCustomEmoji", custom_emoji_id: "9007199254740993" },
      { "@type": "reactionTypePaid" },
    ],
  } });
  await expect(session.chatReactionSettings("-42")).resolves.toMatchObject({ policy: withStars });
  await expect(session.setChatReactionPolicy("-42", selected, selected)).resolves.toBe("changed");
  await expect(session.setChatReactionPolicy("-42", selected, withStars)).resolves.toBe("saved");
});

