test("commits a reviewed paid reaction and does not retry an ambiguous commit", async () => {
  let uncertain = false;
  const { session, request } = harness((query) => {
    switch (query["@type"]) {
      case "getAuthorizationState": return { "@type": "authorizationStateReady" };
      case "getMessageAvailableReactions": return { "@type": "availableReactions", top_reactions: [
        { "@type": "availableReaction", type: { "@type": "reactionTypePaid" } },
      ] };
      case "getOption": return { "@type": "optionValueInteger", value: "10" };
      case "getMessage": return { "@type": "message", id: query.message_id, chat_id: query.chat_id };
      case "getChatAvailablePaidMessageReactionSenders": return { "@type": "messageSenders", senders: [
        { "@type": "messageSenderChat", chat_id: -45 }, { "@type": "messageSenderUser", user_id: 7 },
      ] };
      case "getChat": return { "@type": "chat", id: query.chat_id, title: "Fixture channel" };
      case "addPendingPaidMessageReaction": return { "@type": "ok" };
      case "commitPendingPaidMessageReactions":
        if (uncertain) throw new Error("Fixture timeout");
        return { "@type": "ok" };
      default: throw new Error("Unexpected fixture query");
    }
  });
  await vi.waitFor(() => expect(session.status().state).toBe("ready"));
  const mutations = () => request.mock.calls.filter(([query]) => query["@type"] === "addPendingPaidMessageReaction"
    || query["@type"] === "commitPendingPaidMessageReactions").map(([query]) => query);
  await expect(session.sendPaidReaction("-42", "13", 11, true)).resolves.toBe("failed");
  expect(mutations()).toEqual([]);
  await expect(session.sendPaidReaction("-42", "13", 4, true)).resolves.toBe("sent");
  expect(mutations()).toEqual([
    { "@type": "addPendingPaidMessageReaction", chat_id: -42, message_id: 13, star_count: 4, type: { "@type": "paidReactionTypeAnonymous" } },
    { "@type": "commitPendingPaidMessageReactions", chat_id: -42, message_id: 13 },
  ]);
  await expect(session.paidReactionSenders("-42")).resolves.toEqual([{ id: "-45", name: "Fixture channel" }]);
  await expect(session.sendPaidReaction("-42", "13", 4, false, "-46")).resolves.toBe("failed");
  expect(mutations()).toHaveLength(2);
  await expect(session.sendPaidReaction("-42", "13", 4, false, "-45")).resolves.toBe("sent");
  expect(mutations()[2]).toMatchObject({ "@type": "addPendingPaidMessageReaction", type: { "@type": "paidReactionTypeChat", chat_id: -45 } });
  uncertain = true;
  await expect(session.sendPaidReaction("-42", "13", 4, false)).resolves.toBe("unknown");
  await expect(session.sendPaidReaction("-42", "13", 4, false)).resolves.toBe("unknown");
  expect(mutations()).toHaveLength(6);
});

test("sets or removes only allowed emoji reactions for the exact Telegram message", async () => {
  const emoji = (value: string) => ({ "@type": "reactionTypeEmoji", emoji: value });
  const standard = (value: string) => ({ kind: "emoji" as const, emoji: value });
  const custom = { kind: "custom" as const, id: "9007199254740993" };
  const tdCustom = { "@type": "reactionTypeCustomEmoji", custom_emoji_id: custom.id };
  const entry = (type: TdObject, needs_premium = false) => ({ "@type": "availableReaction", type, needs_premium });
  let chosen: TdObject | undefined;
  let wrongChat = false;
  let premium = false;
  const { session, request } = harness((query) => {
    switch (query["@type"]) {
      case "getAuthorizationState": return { "@type": "authorizationStateReady" };
      case "getMessage": return { "@type": "message", chat_id: wrongChat ? -99 : -42, id: 13,
        interaction_info: { "@type": "messageInteractionInfo", reactions: {
          "@type": "messageReactions", reactions: chosen ? [{
            "@type": "messageReaction", type: chosen, total_count: 1, is_chosen: true,
          }] : [],
        } } };
      case "getMessageAvailableReactions": return { "@type": "availableReactions",
        top_reactions: [entry(emoji("👍")), entry({ "@type": "reactionTypePaid" }), entry(tdCustom, true)],
        popular_reactions: [entry(emoji("👍")), entry(emoji("❤️"))],
      };
      case "getMe": return { "@type": "user", id: 7, is_premium: premium };
      case "addMessageReaction": chosen = query.reaction_type as TdObject; return { "@type": "ok" };
      case "removeMessageReaction": chosen = undefined; return { "@type": "ok" };
      default: throw new Error("Unexpected fixture call");
    }
  });
  await vi.waitFor(() => expect(session.status()).toEqual({ state: "ready" }));
  expect(await session.listReactions("-42", "13")).toEqual([standard("👍"), standard("❤️")]);
  await expect(session.setReaction("-42", "13", custom, true)).resolves.toBe(false);
  wrongChat = true;
  await expect(session.setReaction("-42", "13", standard("👍"), true)).resolves.toBe(false);
  wrongChat = false;
  await expect(session.setReaction("-42", "13", standard("👍"), true)).resolves.toBe(true);
  await expect(session.setReaction("-42", "13", standard("👍"), true)).resolves.toBe(true);
  await expect(session.setReaction("-42", "13", standard("👍"), false)).resolves.toBe(true);
  premium = true;
  expect(await session.listReactions("-42", "13")).toEqual([standard("👍"), custom, standard("❤️")]);
  await expect(session.setReaction("-42", "13", custom, true)).resolves.toBe(true);
  premium = false;
  await expect(session.setReaction("-42", "13", custom, false)).resolves.toBe(true);
  expect(request.mock.calls.filter(([query]) => query["@type"] === "addMessageReaction" || query["@type"] === "removeMessageReaction")).toEqual([
    [{ "@type": "addMessageReaction", chat_id: -42, message_id: 13, reaction_type: emoji("👍"),
      is_big: false, update_recent_reactions: true }],
    [{ "@type": "removeMessageReaction", chat_id: -42, message_id: 13, reaction_type: emoji("👍") }],
    [{ "@type": "addMessageReaction", chat_id: -42, message_id: 13, reaction_type: tdCustom,
      is_big: false, update_recent_reactions: true }],
    [{ "@type": "removeMessageReaction", chat_id: -42, message_id: 13, reaction_type: tdCustom }],
  ]);
});

