test("sends a forward comment first, rechecks the source, and reports partial delivery", async () => {
  const target = { id: "-43", name: "Destination fixture", kind: "Group" as const, topic: { id: 17, name: "Fixture topic" } };
  const topic = { "@type": "messageTopicForum", forum_topic_id: 17 };
  const at = Math.floor(Date.now() / 1000) + 3600;
  const delivery = { at, silent: true };
  let protectedSource = false;
  let forwardConfirmation: "sent" | "refused" | "unknown" = "sent";
  let commentConfirmation: "sent" | "refused" | "unknown" = "sent";
  let protectAfterComment = false;
  const { session, request } = harness((query) => {
    switch (query["@type"]) {
      case "getAuthorizationState": return { "@type": "authorizationStateReady" };
      case "getChat": return { "@type": "chat", id: query.chat_id, title: "Destination fixture",
        has_protected_content: query.chat_id === -42 && protectedSource,
        type: { "@type": "chatTypeSupergroup", supergroup_id: 43 } };
      case "getMessage": return { "@type": "message", id: query.message_id, chat_id: -42, can_be_forwarded: true };
      case "getSupergroup": return { "@type": "supergroup", id: 43, status: { "@type": "chatMemberStatusAdministrator" } };
      case "getForumTopic": return { "@type": "forumTopic", info: {
        "@type": "forumTopicInfo", chat_id: -43, forum_topic_id: 17, name: target.topic.name,
      } };
      case "sendMessage":
        if (protectAfterComment) protectedSource = true;
        if (commentConfirmation === "unknown") return { "@type": "ok" };
        return { "@type": "message", id: 25, chat_id: -43, topic_id: topic,
          scheduling_state: { "@type": "messageSchedulingStateSendAtDate", send_date: at },
          ...(commentConfirmation === "refused" ? { sending_state: { "@type": "messageSendingStateFailed" } } : {}) };
      case "forwardMessages":
        if (forwardConfirmation === "unknown") return { "@type": "ok" };
        return { "@type": "messages", messages: (query.message_ids as number[]).map((id) =>
          forwardConfirmation === "refused" ? null : { "@type": "message", id: id + 100, chat_id: -43, topic_id: topic,
            scheduling_state: { "@type": "messageSchedulingStateSendAtDate", send_date: at } }) };
      default: throw new Error("Unexpected fixture call");
    }
  });
  const writes = () => request.mock.calls.map(([query]) => query).filter(({ "@type": method }) => method === "sendMessage" || method === "forwardMessages");
  const single = () => session.forwardMessage("-42", "12", target, undefined, undefined, delivery, " Fixture comment ");
  try {
    await vi.waitFor(() => expect(session.status().state).toBe("ready"));
    protectedSource = true;
    await expect(single()).resolves.toBe("refused");
    expect(writes()).toEqual([]);
    protectedSource = false;
    commentConfirmation = "unknown";
    await expect(single()).resolves.toBe("commentUnknown");
    commentConfirmation = "refused";
    await expect(single()).resolves.toBe("commentRefused");
    commentConfirmation = "sent";
    protectAfterComment = true;
    await expect(single()).resolves.toBe("forwardRefusedAfterComment");
    expect(writes().map(({ "@type": method }) => method)).toEqual(["sendMessage", "sendMessage", "sendMessage"]);

    protectedSource = false;
    protectAfterComment = false;
    forwardConfirmation = "unknown";
    await expect(single()).resolves.toBe("forwardUnknownAfterComment");
    forwardConfirmation = "refused";
    await expect(single()).resolves.toBe("forwardRefusedAfterComment");
    forwardConfirmation = "sent";
    await expect(session.forwardSelectedMessages("-42", ["12", "10"], target, undefined, delivery, " Fixture comment ")).resolves.toBe("sent");
    const options = { disable_notification: true, scheduling_state: { send_date: at } };
    expect(writes().slice(-2)).toMatchObject([
      { "@type": "sendMessage", chat_id: -43, topic_id: topic, options,
        input_message_content: { "@type": "inputMessageText", text: { text: "Fixture comment" }, clear_draft: false } },
      { "@type": "forwardMessages", chat_id: -43, topic_id: topic, options, from_chat_id: -42, message_ids: [10, 12] },
    ]);
  } finally { await session.close(); }
});

