test("filters global results by both chat type and archive membership", async () => {
  const group = { "@type": "chatTypeBasicGroup" };
  const supergroup = { "@type": "chatTypeSupergroup", is_channel: false };
  const channel = { "@type": "chatTypeSupergroup", is_channel: true };
  const privateChat = { "@type": "chatTypePrivate" };
  const rows = [
    { id: -41, type: group, list: "chatListArchive" },
    { id: -42, type: supergroup, list: "chatListArchive" },
    { id: -43, type: group, list: "chatListMain" },
    { id: -44, type: channel, list: "chatListArchive" },
    { id: 45, type: privateChat, list: "chatListArchive" },
  ];
  const { session, request } = harness((query) => {
    switch (query["@type"]) {
      case "getAuthorizationState": return { "@type": "authorizationStateReady" };
      case "searchMessages": return { "@type": "foundMessages", messages: rows.map(({ id }) => ({
        "@type": "message", id: 1, chat_id: id, date: 300,
        content: { "@type": "messageDocument", document: { document: { id: 7, size: 10 } } },
      })), next_offset: "next-fixture" };
      case "getChat": {
        const chat = rows.find(({ id }) => id === query.chat_id)!;
        return { "@type": "chat", id: chat.id, type: chat.type, chat_lists: [{ "@type": chat.list }] };
      }
      default: throw new Error("Unexpected fixture request");
    }
  });
  try {
    await vi.waitFor(() => expect(session.status().state).toBe("ready"));
    const result = await session.globalSearch("", "media", undefined, "document", { from: 299, until: 301 }, {
      chatType: "group", list: "archive",
    });
    expect(result.hits.map(({ chat }) => chat.id)).toEqual(["-41", "-42"]);
    expect(request.mock.calls.map(([query]) => query)).toContainEqual(expect.objectContaining({
      "@type": "searchMessages", filter: { "@type": "searchMessagesFilterDocument" },
      min_date: 299, max_date: 300, chat_list: { "@type": "chatListArchive" },
      chat_type_filter: { "@type": "searchMessagesChatTypeFilterGroup" },
    }));
    const channels = await session.globalSearch("fixture", "messages", undefined, undefined, undefined, { chatType: "channel" });
    expect(channels.hits.map(({ chat }) => chat.id)).toEqual(["-44"]);
  } finally { await session.close(); }
});

test("moves one sticker in an owned pack and checks the expected order before and after", async () => {
  const id = "9007199254740997";
  let order = [71, 72, 73];
  let owned: boolean | undefined;
  const { session, request } = harness((query) => {
    switch (query["@type"]) {
      case "getAuthorizationState": return { "@type": "authorizationStateReady" };
      case "getOwnedStickerSets": return { "@type": "stickerSets", total_count: 1,
        sets: [{ "@type": "stickerSetInfo", id, title: "Owned fixture" }] };
      case "getStickerSet": return { "@type": "stickerSet", id, title: "Owned fixture", is_owned: owned, stickers: order.map((fileId) => ({
        "@type": "sticker", emoji: `Fixture ${fileId}`, set_id: id, sticker: { "@type": "file", id: fileId },
      })) };
      case "setStickerPositionInSet": {
        const fileId = Number((query.sticker as TdObject).id);
        order = order.filter((value) => value !== fileId);
        order.splice(Number(query.position), 0, fileId);
        return { "@type": "ok" };
      }
      default: throw new Error("Unexpected fixture query");
    }
  });
  const mutations = () => request.mock.calls.map(([query]) => query).filter((query) => query["@type"] === "setStickerPositionInSet");
  try {
    await vi.waitFor(() => expect(session.status().state).toBe("ready"));
    await expect(session.ownedStickerPacks()).resolves.toEqual({ packs: [{ id, title: "Owned fixture" }], next: null });
    await expect(session.ownedStickerPack(id)).resolves.toMatchObject({ id });
    await expect(session.moveOwnedSticker(id, 72, "up", [72, 71, 73])).resolves.toEqual({ state: "changed" });
    await expect(session.moveOwnedSticker(id, 71, "up", order)).resolves.toEqual({ state: "unavailable" });
    owned = false;
    await expect(session.moveOwnedSticker(id, 72, "up", order)).resolves.toEqual({ state: "unavailable" });
    expect(mutations()).toEqual([]);
    owned = true;
    await expect(session.moveOwnedSticker(id, 72, "up", order)).resolves.toMatchObject({
      state: "saved", pack: { id, stickers: [{ id: 72 }, { id: 71 }, { id: 73 }] },
    });
    expect(mutations()).toEqual([{ "@type": "setStickerPositionInSet", sticker: { "@type": "inputFileId", id: 72 }, position: 0 }]);
  } finally { await session.close(); }
});

test("sets and resets a regular pack's cover after checking ownership and its current thumbnail", async () => {
  const directory = await mkdtemp(join(tmpdir(), "makosh-sticker-cover-"));
  const image = "UklGRiQAAABXRUJQVlA4TBcAAAAvY8AYAAdQwYYUtv9hABLC//1SRP9TiQA=";
  const id = "9007199254740997";
  const name = "Fixture_Pack";
  let cover: number | null = null;
  let owned = true;
  let path: string | undefined;
  const { session, request } = harness((query) => {
    switch (query["@type"]) {
      case "getAuthorizationState": return { "@type": "authorizationStateReady" };
      case "getStickerSet":
      case "searchStickerSet": return { "@type": "stickerSet", id, name, title: "Fixture pack", is_owned: owned,
        sticker_type: { "@type": "stickerTypeRegular" }, stickers: [],
        thumbnail: cover === null ? null : { "@type": "thumbnail", file: { "@type": "file", id: cover } },
      };
      case "setStickerSetThumbnail":
        if (query.thumbnail === null) cover = null;
        else {
          path = (query.thumbnail as TdObject).path as string;
          expect(readFileSync(path).toString("base64")).toBe(image);
          cover = 71;
        }
        return { "@type": "ok" };
      default: throw new Error("Unexpected fixture query");
    }
  }, undefined, directory);
  const mutations = () => request.mock.calls.map(([query]) => query).filter((query) => query["@type"] === "setStickerSetThumbnail");
  try {
    await vi.waitFor(() => expect(session.status().state).toBe("ready"));
    await expect(session.setOwnedStickerImageCover(id, null, "YWJj")).resolves.toEqual({ state: "unavailable" });
    await expect(session.setOwnedStickerImageCover(id, 71, image)).resolves.toEqual({ state: "changed" });
    owned = false;
    await expect(session.setOwnedStickerImageCover(id, null, image)).resolves.toEqual({ state: "unavailable" });
    expect(mutations()).toEqual([]);
    owned = true;
    await expect(session.setOwnedStickerImageCover(id, null, image)).resolves.toMatchObject({ state: "saved", pack: { imageCoverFileId: 71 } });
    await expect(session.ownedStickerImageCover(id, 72)).resolves.toBeNull();
    await expect(session.setOwnedStickerImageCover(id, 71, null)).resolves.toMatchObject({ state: "saved", pack: { imageCoverFileId: null } });
    expect(mutations()).toEqual([
      { "@type": "setStickerSetThumbnail", user_id: 0, name, thumbnail: { "@type": "inputFileLocal", path }, format: { "@type": "stickerFormatWebp" } },
      { "@type": "setStickerSetThumbnail", user_id: 0, name, thumbnail: null, format: null },
    ]);
    expect(path && existsSync(path)).toBe(false);
  } finally { await session.close(); await rm(directory, { recursive: true, force: true }); }
});

