test("deletes only the freshly verified owned pack and confirms its name is no longer available", async () => {
  const target = { id: "9007199254740997", name: "Owned_Fixture", title: "Fixture pack", stickerIds: [71, 72] };
  let returnedId = target.id;
  let owned = true;
  let deleted = false;
  let apply = false;
  const { session, request } = harness((query) => {
    switch (query["@type"]) {
      case "getAuthorizationState": return { "@type": "authorizationStateReady" };
      case "searchStickerSet":
        if (deleted) throw new TdError(400, "STICKERSET_INVALID");
        return { "@type": "stickerSet", id: returnedId, name: target.name, title: target.title, is_owned: owned,
          stickers: target.stickerIds.map((id) => ({ "@type": "sticker", set_id: returnedId, sticker: { "@type": "file", id } })) };
      case "deleteStickerSet":
        deleted = apply;
        return { "@type": "ok" };
      default: throw new Error("Unexpected fixture query");
    }
  });
  const mutations = () => request.mock.calls.map(([query]) => query).filter((query) => query["@type"] === "deleteStickerSet");
  try {
    await vi.waitFor(() => expect(session.status().state).toBe("ready"));
    await expect(session.deleteOwnedStickerPack({ ...target, title: "Previous title" })).resolves.toBe("changed");
    await expect(session.deleteOwnedStickerPack({ ...target, stickerIds: [71] })).resolves.toBe("changed");
    returnedId = "9007199254740996";
    await expect(session.deleteOwnedStickerPack(target)).resolves.toBe("unavailable");
    returnedId = target.id;
    owned = false;
    await expect(session.deleteOwnedStickerPack(target)).resolves.toBe("unavailable");
    expect(mutations()).toEqual([]);
    owned = true;
    await expect(session.deleteOwnedStickerPack(target)).resolves.toBe("unknown");
    apply = true;
    await expect(session.deleteOwnedStickerPack(target)).resolves.toBe("deleted");
    const mutation = { "@type": "deleteStickerSet", name: target.name };
    const lookup = { "@type": "searchStickerSet", name: target.name, ignore_cache: true };
    expect(mutations()).toEqual([mutation, mutation]);
    expect(request.mock.calls.slice(-3).map(([query]) => query)).toEqual([lookup, mutation, lookup]);
  } finally { await session.close(); }
});

test("renames an owned sticker pack using its verified Telegram name and title", async () => {
  const id = "9007199254740997";
  let title = "Fixture title";
  let isOwned = true;
  let persist = false;
  const { session, request } = harness((query) => {
    switch (query["@type"]) {
      case "getAuthorizationState": return { "@type": "authorizationStateReady" };
      case "getStickerSet": return { "@type": "stickerSet", id, name: "Owned_Fixture", title, is_owned: isOwned, stickers: [] };
      case "setStickerSetTitle":
        if (persist) title = String(query.title);
        return { "@type": "ok" };
      default: throw new Error("Unexpected fixture query");
    }
  });
  const mutations = () => request.mock.calls.map(([query]) => query).filter((query) => query["@type"] === "setStickerSetTitle");
  try {
    await vi.waitFor(() => expect(session.status().state).toBe("ready"));
    await expect(session.ownedStickerPack(id)).resolves.toMatchObject({ id, canRename: true });
    await expect(session.renameOwnedStickerPack(id, "Old title", "New title")).resolves.toBe("changed");
    await expect(session.renameOwnedStickerPack(id, title, "🙂".repeat(51))).resolves.toBe("unavailable");
    isOwned = false;
    await expect(session.renameOwnedStickerPack(id, title, "New title")).resolves.toBe("unavailable");
    expect(mutations()).toEqual([]);
    isOwned = true;
    await expect(session.renameOwnedStickerPack(id, title, "New title")).resolves.toBe("unknown");
    persist = true;
    await expect(session.renameOwnedStickerPack(id, title, " Новый набор 🙂 ")).resolves.toBe("saved");
    expect(mutations()).toEqual([
      { "@type": "setStickerSetTitle", name: "Owned_Fixture", title: "New title" },
      { "@type": "setStickerSetTitle", name: "Owned_Fixture", title: "Новый набор 🙂" },
    ]);
    await expect(session.ownedStickerPack(id)).resolves.toMatchObject({ id, title: "Новый набор 🙂" });
  } finally { await session.close(); }
});

test("loads only bounded and currently shareable photo and video thumbnails for global media results", async () => {
  const directory = await mkdtemp(join(tmpdir(), "makosh-global-media-thumbnail-"));
  const path = join(directory, "fixture.jpg");
  const image = Buffer.from([255, 216, 255, 224, 0, 16, 74, 70, 73, 70, 0, 1]);
  const file = (id: number, size = image.length) => ({ "@type": "file", id, size });
  const photo = { "@type": "messagePhoto", photo: { "@type": "photo", sizes: [
    { "@type": "photoSize", width: 90, height: 70, photo: file(71) },
    { "@type": "photoSize", width: 1024, height: 800, photo: file(72, 100_000) },
  ] } };
  const rows = [
    { id: 20, content: photo },
    { id: 21, content: { "@type": "messageVideo", video: { "@type": "video", mime_type: "video/mp4", duration: 90,
      thumbnail: { "@type": "thumbnail", width: 640, height: 360, format: { "@type": "thumbnailFormatJpeg" }, file: file(73) }, video: file(74, 5_000_000),
    } } },
    { id: 22, content: { ...photo, has_spoiler: true } },
    { id: 23, content: photo, self_destruct_type: { "@type": "messageSelfDestructTypeImmediately" } },
    { id: 24, content: { "@type": "messageVideoNote", video_note: { "@type": "videoNote", length: 384, duration: 35,
      thumbnail: { "@type": "thumbnail", format: { "@type": "thumbnailFormatJpeg" }, file: file(75) }, video: file(76, 500_000),
    } } },
  ].map((row) => ({ ...row, "@type": "message", chat_id: 42 }));
  let protectedChat = false;
  const { session, request } = harness((query) => {
    switch (query["@type"]) {
      case "getAuthorizationState": return { "@type": "authorizationStateReady" };
      case "searchMessages": return { "@type": "foundMessages", messages: rows, next_offset: "" };
      case "getChat": return { "@type": "chat", id: query.chat_id, title: "Fixture chat", has_protected_content: protectedChat,
        type: { "@type": "chatTypePrivate", user_id: 42 } };
      case "getMessage": return rows.find(({ id }) => id === query.message_id) ?? { "@type": "ok" };
      case "downloadFile": return { "@type": "file", id: query.file_id, local: { "@type": "localFile", is_downloading_completed: true, path } };
      default: throw new Error("Unexpected test query");
    }
  }, undefined, directory);
  const downloads = () => request.mock.calls.map(([query]) => query).filter((query) => query["@type"] === "downloadFile");
  try {
    await writeFile(path, image);
    await vi.waitFor(() => expect(session.status().state).toBe("ready"));
    const page = await session.globalSearch("", "media");
    expect(page.hits.map(({ message, thumbnail, thumbnailFileId }) => [message.id, thumbnail, thumbnailFileId])).toEqual([
      ["20", true, 71], ["21", true, 73], ["22", undefined, undefined], ["23", undefined, undefined],
    ]);
    expect(page.hits[1]?.message.document).toMatchObject({ posterSize: { width: 320, height: 180 }, durationSeconds: 90 });
    const notes = await session.globalSearch("", "media", undefined, "voiceVideoNotes");
    expect(notes.hits).toMatchObject([{ thumbnail: true, message: { id: "24", videoNote: true,
      document: { posterSize: { width: 320, height: 320 }, durationSeconds: 35 } } }]);
    expect(downloads()).toHaveLength(0);
    await expect(session.globalMediaThumbnail("42", "22")).resolves.toBeNull();
    await expect(session.globalMediaThumbnail("42", "23")).resolves.toBeNull();
    await expect(session.globalMediaThumbnail("43", "20")).resolves.toBeNull();
    protectedChat = true;
    await expect(session.globalMediaThumbnail("42", "20")).resolves.toBeNull();
    expect(downloads()).toHaveLength(0);
    protectedChat = false;
    const expected = { mime: "image/jpeg", base64: image.toString("base64") };
    await expect(session.globalMediaThumbnail("42", "20", 74)).resolves.toBeNull();
    expect(downloads()).toHaveLength(0);
    await expect(session.globalMediaThumbnail("42", "20", 71)).resolves.toEqual(expected);
    await expect(session.globalMediaThumbnail("42", "21")).resolves.toEqual(expected);
    await expect(session.globalMediaThumbnail("42", "24")).resolves.toEqual(expected);
    expect(downloads()).toEqual([71, 73, 75].map((file_id) =>
      ({ "@type": "downloadFile", file_id, priority: 6, limit: 65_537, synchronous: true })));
    await expect(session.downloadThumbnail("42", "20", 71)).resolves.toBeNull();
    await expect(session.downloadThumbnail("42", "20", 74)).resolves.toBeNull();
    await expect(session.downloadThumbnail("42", "22", 72)).resolves.toBeNull();
    await expect(session.downloadThumbnail("42", "23", 72)).resolves.toBeNull();
    expect(downloads()).toHaveLength(3);
    await expect(session.downloadThumbnail("42", "20", 72)).resolves.toEqual(expected);
    await expect(session.downloadThumbnail("42", "21", 74)).resolves.toEqual(expected);
    expect(downloads().map(({ file_id }) => file_id)).toEqual([71, 73, 75, 71, 73]);
  } finally {
    await session.close();
    await rm(directory, { recursive: true, force: true });
  }
});

test("paginates global media search and excludes mismatched previews and protected content", async () => {
  const document: TdObject = { "@type": "message", chat_id: 42, id: 20,
    content: { "@type": "messageDocument", document: { "@type": "document", file_name: "Fixture filename.txt",
      document: { "@type": "file", id: 27, size: 512 } },
      caption: { "@type": "formattedText", text: "Fixture caption", entities: [] } } };
  const nonMedia: TdObject = { ...document, id: 21, content: { "@type": "messageText",
    text: { "@type": "formattedText", text: "Unrelated text" } } };
  const { session, request } = harness((query) => {
    switch (query["@type"]) {
      case "getAuthorizationState": return { "@type": "authorizationStateReady" };
      case "searchMessages": return { "@type": "foundMessages", messages: query.offset
        ? [{ ...document, id: 19, self_destruct_type: { "@type": "messageSelfDestructTypeImmediately" } }]
        : [nonMedia, document], next_offset: query.offset ? "" : "next-media" };
      case "getChat": return { "@type": "chat", id: query.chat_id, title: "Fixture destination", type: { "@type": "chatTypePrivate", user_id: 42 } };
      default: throw new Error("Unexpected test query");
    }
  });
  try {
    await vi.waitFor(() => expect(session.status().state).toBe("ready"));
    const first = await session.globalSearch("", "media", undefined, "document");
    expect(first.hits).toHaveLength(1);
    expect(first.hits[0]?.message).toMatchObject({ id: "20", document: { name: "Fixture filename.txt", caption: "Fixture caption" } });
    expect(first.next).toBe("next-media");
    expect(request).toHaveBeenCalledWith(expect.objectContaining({ "@type": "searchMessages", query: "", offset: "",
      filter: { "@type": "searchMessagesFilterDocument" } }));
    const next = await session.globalSearch("", "media", first.next!, "document");
    expect(next).toMatchObject({ next: null, hits: [{ message: { id: "19", text: "Protected message" } }] });
    expect(next.hits[0]?.message).not.toHaveProperty("document");
    expect(request).toHaveBeenCalledWith(expect.objectContaining({ "@type": "searchMessages", query: "", offset: "next-media",
      filter: { "@type": "searchMessagesFilterDocument" } }));
  } finally { await session.close(); }
});

