test("edits own and delegated member tags only when the reviewed tag is current", async () => {
  let canManage = false;
  let tag = "Fixture";
  const { session, request } = harness((query) => {
    switch (query["@type"]) {
      case "getAuthorizationState": return { "@type": "authorizationStateReady" };
      case "getMe": return { "@type": "user", id: 7 };
      case "getChat": return { "@type": "chat", id: -42, type: { "@type": "chatTypeBasicGroup", basic_group_id: 4 } };
      case "getBasicGroup": return { "@type": "basicGroup", id: 4, is_active: true,
        status: { "@type": "chatMemberStatusAdministrator", rights: {
          "@type": "chatAdministratorRights", can_manage_tags: canManage,
        } } };
      case "getChatMember": return { "@type": "chatMember", member_id: query.member_id, tag,
        status: { "@type": "chatMemberStatusMember" } };
      case "setChatMemberTag": tag = String(query.tag); return { "@type": "ok" };
      default: throw new Error("Unexpected fixture query");
    }
  });
  try {
    await vi.waitFor(() => expect(session.status().state).toBe("ready"));
    await expect(session.setChatMemberTag("-42", "43", "Fixture", "New example")).resolves.toBe("unavailable");
    await expect(session.setChatMemberTag("-42", "7", "", "New example")).resolves.toBe("changed");
    await expect(session.setChatMemberTag("-42", "7", "Fixture", "New example")).resolves.toBe("tagSaved");
    canManage = true;
    await expect(session.setChatMemberTag("-42", "43", "New example", "")).resolves.toBe("tagSaved");
    expect(request.mock.calls.filter(([query]) => query["@type"] === "setChatMemberTag")).toEqual([
      [{ "@type": "setChatMemberTag", chat_id: -42, user_id: 7, tag: "New example" }],
      [{ "@type": "setChatMemberTag", chat_id: -42, user_id: 43, tag: "" }],
    ]);
  } finally { await session.close(); }
});

test("adds only a verified contact to a chat that still allows member invitations", async () => {
  let canInvite = false;
  let status = "chatMemberStatusLeft";
  const member_id = { "@type": "messageSenderUser", user_id: 43 };
  const { session, request } = harness((query) => {
    switch (query["@type"]) {
      case "getAuthorizationState": return { "@type": "authorizationStateReady" };
      case "getChat": return { "@type": "chat", id: -42, title: "Fixture group", type: { "@type": "chatTypeSupergroup", supergroup_id: 4 },
        permissions: { "@type": "chatPermissions", can_invite_users: canInvite } };
      case "getSupergroup": return { "@type": "supergroup", id: 4, status: { "@type": "chatMemberStatusMember" } };
      case "getUser": return { "@type": "user", id: 43, is_contact: true, first_name: "Fixture contact" };
      case "getChatMember": return { "@type": "chatMember", member_id, status: { "@type": status } };
      case "addChatMember": return { "@type": "failedToAddMembers", failed_to_add_members: [] };
      default: throw new Error("Unexpected fixture query");
    }
  });
  try {
    await vi.waitFor(() => expect(session.status().state).toBe("ready"));
    await expect(session.canAddChatMember("-42", "Fixture group")).resolves.toBe(false);
    await expect(session.addChatMember("-42", "Fixture group", "43", "Fixture contact")).resolves.toBe("unavailable");
    canInvite = true;
    await expect(session.canAddChatMember("-42", "Fixture group")).resolves.toBe(true);
    await expect(session.addChatMember("-42", "Old title", "43", "Fixture contact")).resolves.toBe("unavailable");
    await expect(session.addChatMember("-42", "Fixture group", "43", "Old name")).resolves.toBe("changed");
    await expect(session.addChatMember("-42", "Fixture group", "43", "Fixture contact")).resolves.toBe("added");
    status = "chatMemberStatusMember";
    await expect(session.addChatMember("-42", "Fixture group", "43", "Fixture contact")).resolves.toBe("alreadyMember");
    expect(request.mock.calls.filter(([query]) => query["@type"] === "addChatMember")).toEqual([[
      { "@type": "addChatMember", chat_id: -42, user_id: 43, forward_limit: 0 },
    ]]);
  } finally { await session.close(); }
});

test("adds reviewed contacts in one supergroup request and reports Telegram's partial result", async () => {
  let canInvite = true;
  let basic = false;
  let denyInvitationsAfterReview = false;
  const { session, request } = harness((query) => {
    switch (query["@type"]) {
      case "getAuthorizationState": return { "@type": "authorizationStateReady" };
      case "getChat": return { "@type": "chat", id: -42, title: "Fixture group",
        type: basic ? { "@type": "chatTypeBasicGroup", basic_group_id: 4 } : { "@type": "chatTypeSupergroup", supergroup_id: 4 },
        permissions: { "@type": "chatPermissions", can_invite_users: canInvite } };
      case "getSupergroup": return { "@type": "supergroup", id: 4, status: { "@type": "chatMemberStatusMember" } };
      case "getBasicGroup": return { "@type": "basicGroup", id: 4, is_active: true, status: { "@type": "chatMemberStatusMember" } };
      case "getUser": return { "@type": "user", id: query.user_id, is_contact: true, first_name: `Fixture ${query.user_id}` };
      case "getChatMember": {
        if (denyInvitationsAfterReview) canInvite = false;
        const member_id = query.member_id as TdObject;
        return { "@type": "chatMember", member_id, status: {
          "@type": member_id.user_id === 45 ? "chatMemberStatusMember" : "chatMemberStatusLeft",
        } };
      }
      case "addChatMembers": return { "@type": "failedToAddMembers",
        failed_to_add_members: [{ "@type": "failedToAddMember", user_id: 44 }] };
      case "addChatMember": return { "@type": "failedToAddMembers", failed_to_add_members: [] };
      default: throw new Error("Unexpected fixture query");
    }
  });
  const contacts = [{ id: "43", name: "Fixture 43" }, { id: "44", name: "Fixture 44" },
    { id: "45", name: "Fixture 45" }, { id: "46", name: "Old name" }];
  try {
    await vi.waitFor(() => expect(session.status().state).toBe("ready"));
    await expect(session.addChatMembers("-42", "Fixture group", contacts)).resolves.toEqual([
      { id: "43", outcome: "added" }, { id: "44", outcome: "unavailable" },
      { id: "45", outcome: "alreadyMember" }, { id: "46", outcome: "changed" },
    ]);
    expect(request.mock.calls.filter(([query]) => query["@type"] === "addChatMembers")).toEqual([
      [{ "@type": "addChatMembers", chat_id: -42, user_ids: [43, 44] }],
    ]);
    denyInvitationsAfterReview = true;
    await expect(session.addChatMembers("-42", "Fixture group", contacts.slice(0, 2))).resolves
      .toEqual(contacts.slice(0, 2).map(({ id }) => ({ id, outcome: "unavailable" })));
    expect(request.mock.calls.filter(([query]) => query["@type"] === "addChatMembers")).toHaveLength(1);
    denyInvitationsAfterReview = false;
    canInvite = true;
    basic = true;
    await expect(session.addChatMembers("-42", "Fixture group", contacts.slice(0, 2))).resolves
      .toEqual(contacts.slice(0, 2).map(({ id }) => ({ id, outcome: "added" })));
    expect(request.mock.calls.filter(([query]) => query["@type"] === "addChatMember")).toHaveLength(2);
  } finally { await session.close(); }
});

test("delegates only reviewed administrator rights and preserves rights outside the editor", async () => {
  const member_id = { "@type": "messageSenderUser", user_id: 43 };
  let status: TdObject = { "@type": "chatMemberStatusMember" };
  const rights = { "@type": "chatAdministratorRights", can_promote_members: true, can_delete_messages: true };
  const available = ["can_delete_messages", "can_promote_members"] as const;
  const { session, request } = harness((query) => {
    switch (query["@type"]) {
      case "getAuthorizationState": return { "@type": "authorizationStateReady" };
      case "getChat": return { "@type": "chat", id: -42, type: { "@type": "chatTypeSupergroup", supergroup_id: 4 } };
      case "getSupergroup": return { "@type": "supergroup", id: 4, status: { "@type": "chatMemberStatusAdministrator", rights } };
      case "getChatMember": return { "@type": "chatMember", member_id, status };
      case "setChatMemberStatus": return { "@type": "ok" };
      default: throw new Error("Unexpected fixture query");
    }
  });
  try {
    await vi.waitFor(() => expect(session.status().state).toBe("ready"));
    await expect(session.saveChatAdministrator("-42", "43", [], ["can_delete_messages"])).resolves.toBe("changed");
    await expect(session.saveChatAdministrator("-42", "43", [...available], ["can_post_messages"])).resolves.toBe("unavailable");
    await expect(session.saveChatAdministrator("-42", "43", [...available], ["can_delete_messages"])).resolves.toBe("administratorSaved");
    status = { "@type": "chatMemberStatusAdministrator", can_be_edited: true,
      rights: { "@type": "chatAdministratorRights", can_delete_messages: true, can_manage_video_chats: true } };
    await expect(session.saveChatAdministrator("-42", "43", [...available], ["can_promote_members"], [])).resolves.toBe("changed");
    await expect(session.saveChatAdministrator("-42", "43", [...available], ["can_promote_members"], ["can_delete_messages"])).resolves.toBe("administratorSaved");
    const writes = request.mock.calls.filter(([query]) => query["@type"] === "setChatMemberStatus");
    expect(writes).toHaveLength(2);
    expect(writes[1]?.[0]).toMatchObject({ chat_id: -42, member_id, status: { "@type": "chatMemberStatusAdministrator", rights: {
      can_delete_messages: false, can_promote_members: true, can_manage_video_chats: true,
    } } });
  } finally { await session.close(); }
});

test("applies and lifts individual restrictions without changing group membership", async () => {
  const member_id = { "@type": "messageSenderUser", user_id: 43 };
  const status = { "@type": "chatMemberStatusRestricted", restricted_until_date: 0, is_member: false };
  const defaults = { can_send_basic_messages: true, can_send_photos: true, can_invite_users: false };
  let currentStatus: TdObject = status;
  const { session, request } = harness((query) => {
    switch (query["@type"]) {
      case "getAuthorizationState": return { "@type": "authorizationStateReady" };
      case "getChat": return { "@type": "chat", id: -42, type: { "@type": "chatTypeSupergroup", supergroup_id: 4, is_channel: false },
        permissions: { "@type": "chatPermissions", ...defaults } };
      case "getSupergroup": return { "@type": "supergroup", id: 4, is_channel: false,
        status: { "@type": "chatMemberStatusCreator", is_member: true } };
      case "getUser": return { "@type": "user", id: 43, first_name: "Fixture" };
      case "getSupergroupMembers": return { "@type": "chatMembers", total_count: 1, members: [{ "@type": "chatMember", member_id, status }] };
      case "getChatMember": return { "@type": "chatMember", member_id, status: currentStatus };
      case "setChatMemberStatus": return { "@type": "ok" };
      default: throw new Error("Unexpected fixture query");
    }
  });
  try {
    await vi.waitFor(() => expect(session.status().state).toBe("ready"));
    await expect(session.chatMembers("-42", "Fixture", 0, "restricted")).resolves.toEqual({
      canLiftRestrictions: true, canRemoveMembers: true, canDeleteMemberMessages: true, restrictionDefaults: defaults, next: null, members: [
        { id: "43", name: "Fixture", role: "restricted", restriction: { until: 0, isMember: false } },
      ],
    });
    expect(request).toHaveBeenCalledWith({
      "@type": "getSupergroupMembers", supergroup_id: 4,
      filter: { "@type": "supergroupMembersFilterRestricted", query: "Fixture" }, offset: 0, limit: 30,
    });
    await expect(session.liftChatMemberRestrictions("-42", "43", 0, true)).resolves.toBe("changed");
    await expect(session.liftChatMemberRestrictions("-42", "43", 0, false)).resolves.toBe("lifted");
    status.is_member = true;
    await expect(session.liftChatMemberRestrictions("-42", "43", 0, true)).resolves.toBe("lifted");
    currentStatus = { "@type": "chatMemberStatusMember" };
    await expect(session.restrictChatMember("-42", "43", 0, { ...defaults, can_send_photos: false }, ["can_send_basic_messages"])).resolves.toBe("changed");
    await expect(session.restrictChatMember("-42", "43", 0, defaults, ["can_invite_users"])).resolves.toBe("unavailable");
    await expect(session.restrictChatMember("-42", "43", 0, defaults, ["can_send_photos"])).resolves.toBe("restricted");
    const values = { ...defaults, can_send_photos: false };
    const expiry = Math.floor(Date.now() / 1000) + 86400;
    currentStatus = { "@type": "chatMemberStatusRestricted", is_member: false, restricted_until_date: expiry,
      permissions: { "@type": "chatPermissions", ...values } };
    const previous = { values, isMember: false, until: expiry };
    await expect(session.restrictChatMember("-42", "43", undefined, defaults, ["can_send_basic_messages"],
      { ...previous, isMember: true })).resolves.toBe("changed");
    await expect(session.restrictChatMember("-42", "43", undefined, defaults, ["can_send_basic_messages"], previous)).resolves.toBe("restricted");
    expect(request.mock.calls.filter(([query]) => query["@type"] === "setChatMemberStatus")).toEqual([
      [{ "@type": "setChatMemberStatus", chat_id: -42, member_id, status: { "@type": "chatMemberStatusLeft" } }],
      [{ "@type": "setChatMemberStatus", chat_id: -42, member_id, status: { "@type": "chatMemberStatusMember" } }],
      [{ "@type": "setChatMemberStatus", chat_id: -42, member_id, status: {
        "@type": "chatMemberStatusRestricted", is_member: true, restricted_until_date: 0,
        permissions: { "@type": "chatPermissions", ...defaults, can_send_photos: false },
      } }],
      [{ "@type": "setChatMemberStatus", chat_id: -42, member_id, status: {
        "@type": "chatMemberStatusRestricted", is_member: false, restricted_until_date: expiry,
        permissions: { "@type": "chatPermissions", ...defaults, can_send_basic_messages: false },
      } }],
    ]);
  } finally { await session.close(); }
});

test("creates a monthly subscription invite only for a permitted channel and price", async () => {
  let allowed = false;
  const { session, request } = harness((query) => {
    switch (query["@type"]) {
      case "getAuthorizationState": return { "@type": "authorizationStateReady" };
      case "getChat": return { "@type": "chat", id: -42, type: { "@type": "chatTypeSupergroup", supergroup_id: 42, is_channel: true } };
      case "getSupergroup": return { "@type": "supergroup", id: 42, is_channel: true,
        status: { "@type": "chatMemberStatusAdministrator", rights: { "@type": "chatAdministratorRights", can_invite_users: allowed } } };
      case "getOption": return { "@type": "optionValueInteger", value: "100" };
      case "getMe": return { "@type": "user", id: 5 };
      case "createChatSubscriptionInviteLink": return { "@type": "chatInviteLink", invite_link: "https://t.me/+fixture_paid",
        creator_user_id: 5, name: query.name, subscription_pricing: query.subscription_pricing };
      case "getChatInviteLink":
      case "editChatSubscriptionInviteLink": return { "@type": "chatInviteLink", invite_link: "https://t.me/+fixture_paid",
        creator_user_id: 5, name: query.name ?? "Fixture",
        subscription_pricing: { "@type": "starSubscriptionPricing", star_count: 12, period: 2592000 } };
      default: throw new Error("Unexpected fixture query");
    }
  });
  await vi.waitFor(() => expect(session.status().state).toBe("ready"));
  await expect(session.subscriptionInviteLimit("-42")).resolves.toBeNull();
  await expect(session.createSubscriptionInvite("-42", "Fixture", 12)).rejects.toThrow("unavailable");
  allowed = true;
  await expect(session.createSubscriptionInvite("-42", "Fixture", 101)).rejects.toThrow("unavailable");
  expect(request.mock.calls.some(([query]) => query["@type"] === "createChatSubscriptionInviteLink")).toBe(false);
  await expect(session.createSubscriptionInvite("-42", "Fixture", 12)).resolves.toMatchObject({
    subscription: true, name: "Fixture", pricing: { stars: 12, period: 2592000 },
  });
  expect(request).toHaveBeenLastCalledWith({ "@type": "createChatSubscriptionInviteLink", chat_id: -42, name: "Fixture",
    subscription_pricing: { "@type": "starSubscriptionPricing", star_count: 12, period: 2592000 } });
  const expected = { name: "Fixture", expires: 0, limit: 0, approval: false, pricing: { stars: 12, period: 2592000 } };
  const draft = { name: "Renamed", expires: 0, limit: 0, approval: false };
  await expect(session.editManagedInvite("-42", "https://t.me/+fixture_paid", { ...expected, pricing: { ...expected.pricing, stars: 13 } }, draft))
    .resolves.toEqual({ state: "changed" });
  await expect(session.editManagedInvite("-42", "https://t.me/+fixture_paid", expected, { ...draft, limit: 1 }))
    .resolves.toEqual({ state: "unavailable" });
  expect(request.mock.calls.some(([query]) => query["@type"] === "editChatSubscriptionInviteLink")).toBe(false);
  await expect(session.editManagedInvite("-42", "https://t.me/+fixture_paid", expected, draft))
    .resolves.toMatchObject({ state: "saved", invite: { name: "Renamed", pricing: expected.pricing } });
  expect(request).toHaveBeenLastCalledWith({ "@type": "editChatSubscriptionInviteLink", chat_id: -42,
    invite_link: "https://t.me/+fixture_paid", name: "Renamed" });
});

test("manages only invite links owned by the active account for the selected chat", async () => {
  const link = "https://t.me/+TestOnlyToken_42";
  const own = { "@type": "chatInviteLink", invite_link: link, creator_user_id: 5,
    name: "Fixture", date: 123, creates_join_request: true, pending_join_request_count: 2 };
  let creator = 5;
  let subscription = false;
  let revoked = false;
  const { session, request } = harness((query) => {
    switch (query["@type"]) {
      case "getAuthorizationState": return { "@type": "authorizationStateReady" };
      case "getMe": return { "@type": "user", id: 5 };
      case "getChat": return { "@type": "chat", id: query.chat_id, type: { "@type": "chatTypeSupergroup" } };
      case "getChatInviteLinks": return { "@type": "chatInviteLinks", invite_links: query.is_revoked
        ? [{ ...own, is_revoked: true }, own, { ...own, creator_user_id: 6, is_revoked: true }]
        : [own, { ...own, creator_user_id: 6 }] };
      case "createChatInviteLink": return own;
      case "getChatInviteLink": return { ...own, creator_user_id: creator, is_revoked: revoked,
        ...(subscription ? { subscription_pricing: { "@type": "starSubscriptionPricing" } } : {}) };
      case "editChatInviteLink": return { ...own, name: query.name, expiration_date: query.expiration_date,
        member_limit: query.member_limit, creates_join_request: query.creates_join_request };
      case "deleteRevokedChatInviteLink": return { "@type": "ok" };
      case "revokeChatInviteLink": return { "@type": "chatInviteLinks", invite_links: [{ ...own, is_revoked: true }] };
      default: throw new Error("Unexpected fixture query");
    }
  });
  try {
    await vi.waitFor(() => expect(session.status().state).toBe("ready"));
    await expect(session.managedInvites("-42")).resolves.toMatchObject({ links: [{ link, pending: 2 }], next: null });
    expect((await session.managedInvites("-42"))?.links).toHaveLength(1);
    await expect(session.createManagedInvite("-42", { name: "Fixture", expires: 0, limit: 0, approval: true }))
      .resolves.toMatchObject({ link, approval: true });
    const expected = { name: "Fixture", expires: 0, limit: 0, approval: true };
    const draft = { name: "Edited fixture", expires: 0, limit: 5, approval: false };
    await expect(session.editManagedInvite("-42", link, { ...expected, name: "Stale" }, draft)).resolves.toEqual({ state: "changed" });
    subscription = true;
    await expect(session.editManagedInvite("-42", link, expected, draft)).resolves.toEqual({ state: "unavailable" });
    subscription = false;
    await expect(session.editManagedInvite("-42", link, expected, draft)).resolves.toMatchObject({ state: "saved", invite: { link, ...draft } });
    creator = 6;
    await expect(session.editManagedInvite("-42", link, expected, draft)).resolves.toEqual({ state: "unavailable" });
    expect(request.mock.calls.filter(([query]) => query["@type"] === "editChatInviteLink")).toEqual([[
      { "@type": "editChatInviteLink", chat_id: -42, invite_link: link, name: "Edited fixture",
        expiration_date: 0, member_limit: 5, creates_join_request: false },
    ]]);
    await expect(session.revokeManagedInvite("-42", link)).resolves.toBe(false);
    creator = 5;
    await expect(session.revokeManagedInvite("-42", link)).resolves.toBe(true);
    expect((await session.managedInvites("-42", undefined, true))?.links).toHaveLength(1);
    await expect(session.deleteRevokedManagedInvite("-42", link)).resolves.toBe(false);
    revoked = true;
    creator = 6;
    await expect(session.deleteRevokedManagedInvite("-42", link)).resolves.toBe(false);
    creator = 5;
    await expect(session.deleteRevokedManagedInvite("-42", link)).resolves.toBe(true);
    expect(request.mock.calls.filter(([query]) => query["@type"] === "deleteRevokedChatInviteLink")).toEqual([[
      { "@type": "deleteRevokedChatInviteLink", chat_id: -42, invite_link: link },
    ]]);
    expect(request.mock.calls.filter(([query]) => query["@type"] === "revokeChatInviteLink")).toEqual([[
      { "@type": "revokeChatInviteLink", chat_id: -42, invite_link: link },
    ]]);
  } finally { await session.close(); }
});

