    await expect(session.previewGroupPack("-42", "sticker", "https://example.com/addstickers/FixturePack")).resolves.toBeNull();
    await expect(session.previewGroupPack("-42", "sticker", "FixtureEmoji")).resolves.toBeNull();
    const regular = await session.previewGroupPack("-42", "sticker", "https://t.me/addstickers/FixturePack");
    expect(regular).toEqual({ id: sticker.id, name: sticker.name, title: sticker.title });
    await expect(session.setGroupPack("-42", "sticker", "12", regular)).resolves.toBe("changed");
    await expect(session.setGroupPack("-42", "sticker", null, { ...regular!, title: "Wrong title" })).resolves.toBe("changed");
    admin = false;
    await expect(session.setGroupPack("-42", "sticker", null, regular)).resolves.toBe("unavailable");
    admin = true;
    await expect(session.setGroupPack("-42", "sticker", null, regular)).resolves.toBe("saved");
    await expect(session.groupPacks("-42")).resolves.toMatchObject({ sticker: { id: sticker.id, title: sticker.title, canRemove: true } });
    await expect(session.previewGroupPack("-42", "emoji", "https://t.me/addemoji/FixtureEmoji")).resolves.toBeNull();
    boosted = true;
    const custom = await session.previewGroupPack("-42", "emoji", "https://t.me/addemoji/FixtureEmoji");
    expect(custom).toEqual({ id: emoji.id, name: emoji.name, title: emoji.title });
    await expect(session.setGroupPack("-42", "emoji", null, custom)).resolves.toBe("saved");
    boosted = false;
    await expect(session.setGroupPack("-42", "emoji", emoji.id, null)).resolves.toBe("saved");
    expect(request.mock.calls.filter(([query]) => query["@type"].startsWith("setSupergroup")).map(([query]) => query)).toEqual([
      { "@type": "setSupergroupStickerSet", supergroup_id: 42, sticker_set_id: sticker.id },
      { "@type": "setSupergroupCustomEmojiStickerSet", supergroup_id: 42, custom_emoji_sticker_set_id: emoji.id },
      { "@type": "setSupergroupCustomEmojiStickerSet", supergroup_id: 42, custom_emoji_sticker_set_id: "0" },
    ]);
