test("recovers a completed basic group upgrade after a timeout and from the old chat", async () => {
  let owner = false;
  let upgraded = false;
  let validMigration = true;
  const { session, request } = harness((query) => {
    switch (query["@type"]) {
      case "getAuthorizationState": return { "@type": "authorizationStateReady" };
      case "getChat": return { "@type": "chat", id: -43, title: "Fixture basic group",
        type: { "@type": "chatTypeBasicGroup", basic_group_id: 43 } };
      case "getBasicGroup": return { "@type": "basicGroup", id: 43, is_active: !upgraded, upgraded_to_supergroup_id: upgraded ? 44 : 0,
        status: { "@type": owner ? "chatMemberStatusCreator" : "chatMemberStatusAdministrator", is_member: true } };
      case "getBasicGroupFullInfo": return { "@type": "basicGroupFullInfo", description: "Fixture description" };
      case "upgradeBasicGroupChatToSupergroupChat":
        upgraded = true;
        throw new TdTimeoutError();
      case "createSupergroupChat":
        return { "@type": "chat", id: -44, title: "Fixture supergroup",
          type: { "@type": "chatTypeSupergroup", supergroup_id: validMigration ? 44 : 99, is_channel: false } };
      default: throw new Error("Unexpected fixture query");
    }
  });
  try {
    await vi.waitFor(() => expect(session.status().state).toBe("ready"));
    expect((await session.chatInfo("-43"))?.canUpgrade).toBeUndefined();
    await expect(session.upgradeBasicGroup("-43", "Fixture basic group")).resolves.toBe("unavailable");
    owner = true;
    expect(schemas.chatInfo.output.parse(await session.chatInfo("-43"))?.canUpgrade).toBe(true);
    await expect(session.upgradeBasicGroup("-43", "Stale title")).resolves.toBe("changed");
    expect(schemas.upgradeBasicGroup.output.parse(await session.upgradeBasicGroup("-43", "Fixture basic group")))
      .toEqual({ group: { id: "-44", title: "Fixture supergroup", upgradeRequired: false } });
    expect(schemas.chatInfo.output.parse(await session.chatInfo("-43"))).toEqual({
      title: "Fixture basic group", description: "", editable: false, migration: { group: { id: "-44", title: "Fixture supergroup" } },
    });
    validMigration = false;
    expect(schemas.chatInfo.output.parse(await session.chatInfo("-43"))?.migration).toEqual({});
    expect(request).toHaveBeenCalledWith({ "@type": "createSupergroupChat", supergroup_id: 44, force: false });
    expect(request.mock.calls.filter(([query]) => query["@type"] === "upgradeBasicGroupChatToSupergroupChat").map(([query]) => query))
      .toEqual([{ "@type": "upgradeBasicGroupChatToSupergroupChat", chat_id: -43 }]);
    expect(request.mock.calls.some(([query]) => ["getSuitableDiscussionChats", "setChatDiscussionGroup"].includes(query["@type"]))).toBe(false);
  } finally { await session.close(); }
});

