    administrator = true;
    await expect(session.reportAntiSpamFalsePositive("-99", eventId)).resolves.toBe("unavailable");
    reportable = false;
    await expect(session.reportAntiSpamFalsePositive("-42", eventId)).resolves.toBe("unavailable");
    reportable = true;
    sourceChat = -99;
    await expect(session.reportAntiSpamFalsePositive("-42", eventId)).resolves.toBe("unavailable");
    sourceChat = -42;
    returnedId = "9007199254741998";
