test("resolves the affected user or chat and the approver in Telegram member events", async () => {
  const member = { "@type": "chatMemberStatusMember" };
  const administrator = { "@type": "chatMemberStatusAdministrator" };
  const withRights = (rights: Record<string, unknown>) => ({
    ...administrator, rights: { "@type": "chatAdministratorRights", ...rights },
  });
  const restricted = (permissions: Record<string, unknown>) => ({
    "@type": "chatMemberStatusRestricted", is_member: true, permissions: { "@type": "chatPermissions", ...permissions },
  });
  const left = { "@type": "chatMemberStatusLeft" };
  const banned = (until: number) => ({ "@type": "chatMemberStatusBanned", banned_until_date: until });
  const limited = (until: number, isMember = true) => ({
    "@type": "chatMemberStatusRestricted", restricted_until_date: until, is_member: isMember,
  });
  const transition = (old_status: Record<string, unknown>, new_status: Record<string, unknown>) => ({
    "@type": "chatEventMemberRestricted", member_id: { "@type": "messageSenderUser", user_id: 51 }, old_status, new_status,
  });
  const acts = [
    { "@type": "chatEventMemberPromoted", user_id: 51, old_status: member, new_status: administrator },
    { "@type": "chatEventMemberRestricted", member_id: { "@type": "messageSenderChat", chat_id: -55 },
      old_status: { "@type": "chatMemberStatusLeft" }, new_status: { "@type": "chatMemberStatusBanned" } },
    { "@type": "chatEventMemberTagChanged", user_id: 51, old_tag: "", new_tag: "Volunteer" },
    { "@type": "chatEventMemberJoinedByRequest", approver_user_id: 42 },
    { "@type": "chatEventMemberInvited", user_id: 99, status: member },
    { "@type": "chatEventMemberRestricted", member_id: { "@type": "unknown", chat_id: -111 },
      old_status: member, new_status: { "@type": "chatMemberStatusBanned" } },
    { "@type": "chatEventMemberPromoted", user_id: 51,
      old_status: withRights({ can_delete_messages: false, can_pin_messages: true, can_manage_topics: true }),
      new_status: withRights({ can_delete_messages: true, can_pin_messages: false, can_manage_tags: true }) },
    { "@type": "chatEventMemberRestricted", member_id: { "@type": "messageSenderUser", user_id: 51 },
      old_status: restricted({ can_send_basic_messages: true, can_send_messages: false, can_send_photos: true, can_add_web_page_previews: false }),
      new_status: restricted({ can_send_basic_messages: true, can_send_messages: true, can_send_photos: false, can_add_web_page_previews: true }) },
    { "@type": "chatEventMemberLeft" },
    { "@type": "chatEventMemberJoined" },
    transition(member, left),
    transition(member, banned(1234567890)),
    transition(banned(1234567890), banned(0)),
    transition(banned(0), left),
    transition(member, limited(0)),
    transition(limited(0), limited(1234567890)),
    transition(limited(1234567890), member),
    transition(limited(0, false), left),
    transition(member, banned(2147483648)),
  ];
  const { session, request } = harness((query) => {
    switch (query["@type"]) {
      case "getAuthorizationState": return { "@type": "authorizationStateReady" };
      case "getChat": return { "@type": "chat", id: query.chat_id, title: "Fixture sender chat", type: { "@type": "chatTypeSupergroup" } };
      case "getUser": return { "@type": "user", id: query.user_id,
        first_name: query.user_id === 42 ? "Fixture admin" : query.user_id === 51 ? "Fixture member" : "" };
      case "getChatEventLog": return { "@type": "chatEvents", events: acts.map((action, index) => ({
        "@type": "chatEvent", id: String(30 - index), date: 123, member_id: { "@type": "messageSenderUser", user_id: 42 }, action,
      })) };
      default: throw new Error("Unexpected fixture query");
    }
  });
  try {
    await vi.waitFor(() => expect(session.status().state).toBe("ready"));
    const page = schemas.chatEvents.output.parse(await session.chatEvents("-42", "", undefined, ["members"]));
    expect(page?.events.slice(0, 4).map(({ action }) => action)).toEqual([
      "Administrator status changed", "Chat sender banned", "Member tag changed", "Join request approved",
    ]);
    expect(page?.events.slice(0, 8).map(({ member, memberChange, approver }) => [member, memberChange, approver])).toEqual([
      ["Fixture member", { field: "status", before: "Member", after: "Administrator" }, undefined],
      ["Fixture sender chat", { field: "status", before: "Outside the chat", after: "Banned" }, undefined],
      ["Fixture member", { field: "tag", before: "", after: "Volunteer" }, undefined],
      [undefined, undefined, "Fixture admin"],
      ["Telegram user 99", undefined, undefined],
      [undefined, undefined, undefined],
      ["Fixture member", undefined, undefined],
      ["Fixture member", undefined, undefined],
    ]);
    expect(page?.events.slice(8).map(({ action, moderationPeriod }) => [action, moderationPeriod])).toEqual([
      ["Member left", undefined], ["Member joined", undefined], ["Member removed", undefined],
      ["Member banned", { kind: "ban", until: 1234567890 }],
      ["Ban duration changed", { kind: "ban", until: 0, previousUntil: 1234567890 }],
      ["Member unbanned", undefined], ["Member restricted", { kind: "restriction", until: 0 }],
      ["Restriction duration changed", { kind: "restriction", until: 1234567890, previousUntil: 0 }],
      ["Member restrictions lifted", undefined], ["Member restrictions lifted", undefined],
      ["Member banned", undefined],
    ]);
    expect(page?.events.slice(0, 6).every(({ permissionChanges }) => permissionChanges === undefined)).toBe(true);
    expect(page?.events[6]?.permissionChanges).toEqual([
      { kind: "administrator", key: "can_delete_messages", enabled: true },
      { kind: "administrator", key: "can_pin_messages", enabled: false },
    ]);
    expect(page?.events[7]?.permissionChanges).toEqual([
      { kind: "member", key: "can_send_photos", enabled: false },
      { kind: "member", key: "can_add_web_page_previews", enabled: true },
    ]);
    expect(request.mock.calls.filter(([query]) => query["@type"] === "getUser" && query.user_id === 51)).toHaveLength(1);
    expect(request.mock.calls.filter(([query]) => query["@type"] === "getUser" && query.user_id === 42)).toHaveLength(1);
    expect(request).not.toHaveBeenCalledWith(expect.objectContaining({ "@type": "getChat", chat_id: -111 }));
  } finally { await session.close(); }
});

test("loads channel comments only from the verified linked discussion and paginates without the root post", async () => {
  const make = (id: number, chat_id: number) => ({ "@type": "message", id, chat_id,
    content: { "@type": "messageText", text: { "@type": "formattedText", text: "Fixture" } },
  });
  const { session, request } = harness((query) => {
    switch (query["@type"]) {
      case "getAuthorizationState": return { "@type": "authorizationStateReady" };
      case "getChat": return { "@type": "chat", id: query.chat_id, title: "Fixture",
        type: { "@type": "chatTypeSupergroup", is_channel: query.chat_id === -42 } };
      case "getMessage": return { ...make(77, -42), is_channel_post: true };
      case "getMessageThread": return { "@type": "messageThreadInfo", chat_id: -43, message_thread_id: 10 };
      case "getMessageThreadHistory": return { "@type": "messages", messages: query.from_message_id
        ? [make(20, -43), make(15, -43), make(10, -43)] : [make(20, -43), make(19, -44)] };
      default: throw new Error("Unexpected fixture query");
    }
  });
  try {
    await vi.waitFor(() => expect(session.status().state).toBe("ready"));
    const first = await session.channelDiscussion("-42", "77");
    expect(first.chat.id).toBe("-43");
    expect(first.messages.map(({ id }) => id)).toEqual(["20"]);
    expect(first.before).toBe("20");
    const next = await session.channelDiscussion("-42", "77", first.before!);
    expect(next.messages.map(({ id }) => id)).toEqual(["15"]);
    expect(next.before).toBeNull();
    await expect(session.channelDiscussion("-43", "77")).rejects.toThrow("channel post");
    expect(request.mock.calls.filter(([query]) => query["@type"] === "getMessageThreadHistory")).toHaveLength(2);
  } finally { await session.close(); }
});

