test("confirms only the reviewed unconfirmed device using its exact int64 session ID", async () => {
  const id = "-9007199254741022";
  const currentId = "1";
  let pending = true;
  let password = false;
  let location = "Fixture location";
  const { session, request } = harness((query) => {
    switch (query["@type"]) {
      case "getAuthorizationState": return { "@type": "authorizationStateReady" };
      case "getActiveSessions": return { "@type": "sessions", sessions: [
        { "@type": "session", id: currentId, is_current: true, is_unconfirmed: true },
        { "@type": "session", id, is_current: false, is_unconfirmed: pending, is_password_pending: password,
          application_name: "Fixture", device_model: "Fixture device", log_in_date: 1700000000, location },
      ] };
      case "confirmSession": pending = false; return { "@type": "ok" };
      default: throw new Error("Unexpected fixture request");
    }
  });
  try {
    await vi.waitFor(() => expect(session.status().state).toBe("ready"));
    const [current, other] = await session.activeDevices();
    expect(current?.unconfirmed).toBeUndefined();
    expect(other?.unconfirmed).toMatchObject({ location, signedInAt: 1700000000 });
    expect(await session.pendingDeviceSignIns()).toBe(1);
    const revision = other!.unconfirmed!.revision;
    await expect(session.confirmDevice(currentId, revision)).resolves.toBe("changed");
    password = true;
    expect((await session.activeDevices())[1]).toMatchObject({ passwordPending: true });
    await expect(session.confirmDevice(id, revision)).resolves.toBe("changed");
    password = false;
    location = "Updated fixture location";
    await expect(session.confirmDevice(id, revision)).resolves.toBe("changed");
    const latest = (await session.activeDevices())[1]!.unconfirmed!.revision;
    await expect(Promise.all([session.confirmDevice(id, latest), session.confirmDevice(id, latest)]))
      .resolves.toEqual(["confirmed", "unavailable"]);
    await expect(session.confirmDevice(id, latest)).resolves.toBe("changed");
    expect(await session.pendingDeviceSignIns()).toBe(0);
    expect(request.mock.calls.filter(([query]) => query["@type"] === "confirmSession")).toEqual([
      [{ "@type": "confirmSession", session_id: id }],
    ]);
  } finally { await session.close(); }
});

test("updates a known Telegram privacy audience while preserving exceptions and refusing stale rules", async () => {
  const exception = { "@type": "userPrivacySettingRuleRestrictUsers", user_ids: [42] };
  let rules = [exception, { "@type": "userPrivacySettingRuleAllowContacts" }, { "@type": "userPrivacySettingRuleRestrictAll" }];
  const { session, request } = harness((query) => {
    switch (query["@type"]) {
      case "getAuthorizationState": return { "@type": "authorizationStateReady" };
      case "getUserPrivacySettingRules": return { "@type": "userPrivacySettingRules", rules };
      case "setUserPrivacySettingRules":
        rules = (query.rules as TdObject).rules as typeof rules;
        return { "@type": "ok" };
      default: throw new Error("Unexpected fixture query");
    }
  });
  try {
    await vi.waitFor(() => expect(session.status().state).toBe("ready"));
    const before = await session.telegramPrivacy("phone");
    expect(before).toMatchObject({ audience: "contacts", exceptions: 1 });
    expect(before).not.toHaveProperty("rules");
    await expect(session.saveTelegramPrivacy("phone", "nobody", before.version)).resolves.toBe("saved");
    expect(rules).toEqual([exception, { "@type": "userPrivacySettingRuleRestrictAll" }]);
    await expect(session.saveTelegramPrivacy("phone", "everyone", before.version)).resolves.toBe("changed");
    rules = [{ "@type": "userPrivacySettingRuleRestrictContacts" }, { "@type": "userPrivacySettingRuleAllowAll" }] as typeof rules;
    const custom = await session.telegramPrivacy("phone");
    expect(custom.audience).toBeNull();
    await expect(session.saveTelegramPrivacy("phone", "everyone", custom.version)).resolves.toBe("unsupported");
    expect(request.mock.calls.filter(([query]) => query["@type"] === "setUserPrivacySettingRules")).toHaveLength(1);
  } finally { await session.close(); }
});

