test("edits a reviewed person or group privacy exception without rewriting unrelated rules", async () => {
  const groupRule = { "@type": "userPrivacySettingRuleRestrictChatMembers", chat_ids: [-7, -8] };
  const premiumRule = { "@type": "userPrivacySettingRuleAllowPremiumUsers" };
  const base = [{ "@type": "userPrivacySettingRuleAllowContacts" }, { "@type": "userPrivacySettingRuleRestrictAll" }];
  let rules: TdObject[] = [groupRule, premiumRule, ...base];
  const { session, request } = harness((query) => {
    switch (query["@type"]) {
      case "getAuthorizationState": return { "@type": "authorizationStateReady" };
      case "getUserPrivacySettingRules": return { "@type": "userPrivacySettingRules", rules };
      case "searchChats": return { "@type": "chats", chat_ids: [-7, -9] };
      case "searchContacts": return { "@type": "users", user_ids: [42] };
      case "getUser": return { "@type": "user", id: query.user_id, first_name: "Fixture contact" };
      case "getChat": return { "@type": "chat", id: query.chat_id, title: "Fixture group",
        type: query.chat_id === -9 ? { "@type": "chatTypeSupergroup", is_channel: true } : { "@type": "chatTypeBasicGroup" } };
      case "setUserPrivacySettingRules": rules = (query.rules as TdObject).rules as TdObject[]; return { "@type": "ok" };
      default: throw new Error("Unexpected privacy exception fixture query");
    }
  });
  const person = { kind: "person" as const, id: "42" };
  const group = { kind: "group" as const, id: "-7" };
  try {
    await vi.waitFor(() => expect(session.status().state).toBe("ready"));
    const start = (await session.privacyExceptions("invites", 0))!;
    expect(start.entries).toEqual(["-7", "-8"].map((id) => ({ target: { ...group, id }, name: "Fixture group", decision: "restrict" })));
    expect(await session.searchPrivacyExceptionTargets("Fixture")).toEqual([{ target: person, name: "Fixture contact" }, { target: group, name: "Fixture group" }]);
    const add = { key: "invites", version: start.version, target: person, action: "add", decision: "allow" } as const;
    await expect(session.changePrivacyException({ ...add, target: { kind: "group", id: "-9" } })).resolves.toBe("unsupported");
    await expect(session.changePrivacyException(add)).resolves.toBe("saved");
    const allow = { "@type": "userPrivacySettingRuleAllowUsers", user_ids: [42] };
    expect(rules).toEqual([allow, groupRule, premiumRule, ...base]);
    await expect(session.changePrivacyException(add)).resolves.toBe("changed");
    await expect(session.privacyExceptions("invites", 0, start.version)).resolves.toBeNull();
    const fresh = (await session.privacyExceptions("invites", 0))!;
    await expect(session.changePrivacyException({ ...add, version: fresh.version, decision: "restrict" })).resolves.toBe("unsupported");
    await expect(session.changePrivacyException({ ...add, version: fresh.version, target: group, action: "remove", decision: "restrict" })).resolves.toBe("saved");
    expect(rules).toEqual([allow, { ...groupRule, chat_ids: [-8] }, premiumRule, ...base]);
    expect(request.mock.calls.filter(([query]) => query["@type"] === "setUserPrivacySettingRules")).toHaveLength(2);
  } finally { await session.close(); }
});

