test("reads slow mode for supergroups and verifies rights and the previous delay before saving", async () => {
  let channel = false;
  let editable = false;
  let delay = 30;
  let membersHidden = false;
  let antiSpamEnabled = false;
  const { session, request } = harness((query) => {
    switch (query["@type"]) {
      case "getAuthorizationState": return { "@type": "authorizationStateReady" };
      case "getChat": return { "@type": "chat", id: -42,
        type: { "@type": "chatTypeSupergroup", supergroup_id: 7, is_channel: channel },
        permissions: { "@type": "chatPermissions" } };
      case "getSupergroup": return { "@type": "supergroup", id: 7, is_channel: channel,
        status: { "@type": "chatMemberStatusAdministrator",
          rights: { "@type": "chatAdministratorRights", can_restrict_members: editable } } };
      case "getSupergroupFullInfo": return { "@type": "supergroupFullInfo", slow_mode_delay: delay,
        has_hidden_members: membersHidden, can_hide_members: editable,
        has_aggressive_anti_spam_enabled: antiSpamEnabled, can_toggle_aggressive_anti_spam: editable };
      case "toggleSupergroupHasHiddenMembers": membersHidden = query.has_hidden_members === true; return { "@type": "ok" };
      case "toggleSupergroupHasAggressiveAntiSpamEnabled": antiSpamEnabled = query.has_aggressive_anti_spam_enabled === true; return { "@type": "ok" };
      case "setChatSlowModeDelay": delay = Number(query.slow_mode_delay); return { "@type": "ok" };
      default: throw new Error("Unexpected test query");
    }
  });
  try {
    await vi.waitFor(() => expect(session.status().state).toBe("ready"));
    await expect(session.groupSlowMode("-42")).resolves.toEqual({ delay: 30, editable: false });
    await expect(session.saveGroupSlowMode("-42", 60, 30)).resolves.toBe("unavailable");
    await expect(session.groupMemberVisibility("-42")).resolves.toEqual({ hidden: false, editable: false });
    await expect(session.saveGroupMemberVisibility("-42", true, false)).resolves.toBe("unavailable");
    await expect(session.groupAntiSpam("-42")).resolves.toEqual({ enabled: false, editable: false });
    await expect(session.saveGroupAntiSpam("-42", true, false)).resolves.toBe("unavailable");
    editable = true;
    await expect(session.saveGroupAntiSpam("-42", false, true)).resolves.toBe("changed");
    await expect(session.saveGroupAntiSpam("-42", true, false)).resolves.toBe("saved");
    await expect(session.groupAntiSpam("-42")).resolves.toEqual({ enabled: true, editable: true });
    await expect(session.saveGroupMemberVisibility("-42", false, true)).resolves.toBe("changed");
    await expect(session.saveGroupMemberVisibility("-42", true, false)).resolves.toBe("saved");
    await expect(session.groupMemberVisibility("-42")).resolves.toEqual({ hidden: true, editable: true });
    await expect(session.saveGroupSlowMode("-42", 60, 10)).resolves.toBe("changed");
    await expect(session.saveGroupSlowMode("-42", 60, 30)).resolves.toBe("saved");
    await expect(session.groupSlowMode("-42")).resolves.toEqual({ delay: 60, editable: true });
    channel = true;
    await expect(session.groupSlowMode("-42")).resolves.toBeNull();
    await expect(session.groupMemberVisibility("-42")).resolves.toBeNull();
    await expect(session.groupAntiSpam("-42")).resolves.toBeNull();
    expect(request.mock.calls.filter(([query]) => query["@type"] === "toggleSupergroupHasAggressiveAntiSpamEnabled")).toEqual([[
      { "@type": "toggleSupergroupHasAggressiveAntiSpamEnabled", supergroup_id: 7, has_aggressive_anti_spam_enabled: true },
    ]]);
    expect(request.mock.calls.filter(([query]) => query["@type"] === "toggleSupergroupHasHiddenMembers")).toEqual([[
      { "@type": "toggleSupergroupHasHiddenMembers", supergroup_id: 7, has_hidden_members: true },
    ]]);
    expect(request.mock.calls.filter(([query]) => query["@type"] === "setChatSlowModeDelay")).toEqual([[
      { "@type": "setChatSlowModeDelay", chat_id: -42, slow_mode_delay: 60 },
    ]]);
  } finally { await session.close(); }
});

