test("resolves collectible gift links and rejects unrelated URLs and mismatched gifts", async () => {
  let name = "FixtureGift-42";
  const { session, request } = harness((query) => {
    if (query["@type"] === "getAuthorizationState") return { "@type": "authorizationStateReady" };
    if (query["@type"] === "getUpgradedGift") return { "@type": "upgradedGift", name, title: "Fixture Gift", number: 42,
      model: { "@type": "upgradedGiftModel", name: "Fixture model", rarity: { "@type": "upgradedGiftAttributeRarityRare" } } };
    throw new Error("Unexpected fixture query");
  });
  try {
    await vi.waitFor(() => expect(session.status().state).toBe("ready"));
    for (const url of ["https://example.org/nft/FixtureGift-42", "tg://nft?slug=FixtureGift-42&extra=1"]) {
      await expect(session.resolveCollectibleGift(url)).resolves.toBeNull();
    }
    expect(request.mock.calls.some(([query]) => query["@type"] === "getUpgradedGift")).toBe(false);
    await expect(session.resolveCollectibleGift("tg://nft?slug=FixtureGift-42")).resolves.toMatchObject({
      slug: "FixtureGift-42", title: "Fixture Gift", number: 42, details: { model: { name: "Fixture model", rarity: "rare" } },
    });
    expect(request).toHaveBeenCalledWith({ "@type": "getUpgradedGift", name: "FixtureGift-42" });
    name = "OtherGift-42";
    await expect(session.resolveCollectibleGift("https://t.me/nft/FixtureGift-42")).resolves.toBeNull();
  } finally { await session.close(); }
});

