test("reads administrator boost history and keeps gift codes out of the result", async () => {
  let administrator = false;
  const base = { "@type": "chatBoost", count: 1, start_date: 1700000000, expiration_date: 1900000000 };
  const { session, request } = harness((query) => {
    switch (query["@type"]) {
      case "getAuthorizationState": return { "@type": "authorizationStateReady" };
      case "getChat": return { "@type": "chat", id: -42, title: "Fixture",
        type: { "@type": "chatTypeSupergroup", supergroup_id: 42, is_channel: false } };
      case "getSupergroup": return { "@type": "supergroup", id: 42, is_channel: false,
        status: { "@type": administrator ? "chatMemberStatusAdministrator" : "chatMemberStatusMember" } };
      case "getUser": return { "@type": "user", id: 52, first_name: "Fixture member" };
      case "getChatBoosts": return { "@type": "foundChatBoosts", next_offset: "second", boosts: [
        { ...base, id: "a", source: { "@type": "chatBoostSourcePremium", user_id: 52 } },
        { ...base, id: "b", count: 3, source: { "@type": "chatBoostSourceGiveaway", user_id: 0, star_count: 250, is_unclaimed: true,
          gift_code: "synthetic-code" } },
      ] };
      default: throw new Error("Unexpected fixture query");
    }
  });
  try {
    await vi.waitFor(() => expect(session.status().state).toBe("ready"));
    await expect(session.chatBoostHistory("-42", false)).resolves.toBeNull();
    expect(request.mock.calls.some(([query]) => query["@type"] === "getChatBoosts")).toBe(false);
    administrator = true;
    const page = await session.chatBoostHistory("-42", false);
    expect(page).toEqual({ next: "second", boosts: [
      { id: "a", source: "premium", name: "Fixture member", count: 1, startedAt: 1700000000, expiresAt: 1900000000 },
      { id: "b", source: "giveaway", count: 3, stars: 250, unclaimed: true, startedAt: 1700000000, expiresAt: 1900000000 },
    ] });
    await expect(session.chatBoostHistory("-42", true, "second")).resolves.toEqual({ next: null, boosts: [page!.boosts[1]] });
    expect(request).toHaveBeenCalledWith({ "@type": "getChatBoosts", chat_id: -42, only_gift_codes: true, offset: "second", limit: 30 });
  } finally { await session.close(); }
});

test("applies only reviewed boost slots while preserving cooldown and transfer identity", async () => {
  const now = Math.floor(Date.now() / 1000);
  const expiresAt = now + 3600;
  const slot = (id: number, source: number, cooldown = 0) => ({ "@type": "chatBoostSlot",
    slot_id: id, currently_boosted_chat_id: source, expiration_date: expiresAt, cooldown_until_date: cooldown });
  let rows = [slot(1, 0), slot(2, -43), slot(3, -43, now + 3600)];
  const { session, request } = harness((query) => {
    switch (query["@type"]) {
      case "getAuthorizationState": return { "@type": "authorizationStateReady" };
      case "getChat": return { "@type": "chat", id: query.chat_id, title: query.chat_id === -43 ? "Fixture source" : "Fixture channel",
        type: { "@type": "chatTypeSupergroup", is_channel: true } };
      case "getAvailableChatBoostSlots": return { "@type": "chatBoostSlots", slots: rows };
      case "boostChat":
        rows = [slot(1, -42), slot(2, -42), slot(3, -43, now + 3600)];
        return { "@type": "chatBoostSlots", slots: rows };
      default: throw new Error("Unexpected fixture query");
    }
  });
  try {
    await vi.waitFor(() => expect(session.status().state).toBe("ready"));
    const free = { slot: 1, source: null, expiresAt, cooldownUntil: 0 };
    const transfer = { slot: 2, source: "-43", expiresAt, cooldownUntil: 0 };
    const locked = { slot: 3, source: "-43", expiresAt, cooldownUntil: now + 3600 };
    await expect(session.chatBoostSlots("-42")).resolves.toEqual([
      free, { ...transfer, sourceName: "Fixture source" }, { ...locked, sourceName: "Fixture source" },
    ]);
    await expect(session.applyChatBoosts("-42", "Fixture channel", [locked])).resolves.toBe("changed");
    await expect(session.applyChatBoosts("-42", "Wrong chat", [free])).resolves.toBe("changed");
    await expect(session.applyChatBoosts("-42", "Fixture channel", [{ ...transfer, source: null }])).resolves.toBe("changed");
    expect(request.mock.calls.filter(([query]) => query["@type"] === "boostChat")).toHaveLength(0);
    await expect(session.applyChatBoosts("-42", "Fixture channel", [free, transfer])).resolves.toBe("applied");
    expect(request).toHaveBeenCalledWith({ "@type": "boostChat", chat_id: -42, slot_ids: [1, 2] });
    await expect(session.applyChatBoosts("-42", "Fixture channel", [free, transfer])).resolves.toBe("changed");
    expect(request.mock.calls.filter(([query]) => query["@type"] === "boostChat")).toHaveLength(1);
  } finally { await session.close(); }
});

test("limits chat emoji status changes to eligible administrators and allowed statuses", async () => {
  let admin = false;
  let boosted = false;
  let emojiStatus: unknown;
  let giftAvailable = true;
  const collectible = (id: string, owner: number) => ({
    "@type": "receivedGift", gift: { "@type": "sentGiftUpgraded", gift: {
      "@type": "upgradedGift", id, title: "Fixture collectible", name: "Fixture-1",
      owner_id: { "@type": "messageSenderChat", chat_id: owner },
      model: { "@type": "upgradedGiftModel", sticker: { "@type": "sticker", full_type: { "@type": "stickerFullTypeRegular" } } },
    } },
  });
  const { session, request } = harness((query) => {
    switch (query["@type"]) {
      case "getAuthorizationState": return { "@type": "authorizationStateReady" };
      case "getChat": return { "@type": "chat", id: -42, title: "Fixture channel", emoji_status: emojiStatus,
        type: { "@type": "chatTypeSupergroup", supergroup_id: 42, is_channel: true } };
      case "getSupergroup": return { "@type": "supergroup", id: 42, is_channel: true,
        status: admin ? { "@type": "chatMemberStatusAdministrator", rights: { "@type": "chatAdministratorRights", can_change_info: true } }
          : { "@type": "chatMemberStatusMember" } };
      case "getSupergroupFullInfo": return { "@type": "supergroupFullInfo", description: "" };
      case "getChatBoostStatus": return { "@type": "chatBoostStatus", level: boosted ? 8 : 0, boost_count: 12,
        next_level_boost_count: 15, applied_slot_ids: [1, 1, 2], boost_url: "https://t.me/FixtureChannel?boost" };
      case "getChatBoostLevelFeatures": return { "@type": "chatBoostLevelFeatures", can_set_emoji_status: query.level === 8,
        can_recognize_speech: true, story_per_day_count: 8, custom_emoji_reaction_count: 3 };
      case "getThemedChatEmojiStatuses": return { "@type": "emojiStatusCustomEmojis", custom_emoji_ids: ["22"] };
      case "getDefaultChatEmojiStatuses": return { "@type": "emojiStatusCustomEmojis", custom_emoji_ids: ["22", "23"] };
      case "getDisallowedChatEmojiStatuses": return { "@type": "emojiStatusCustomEmojis", custom_emoji_ids: ["23"] };
      case "getReceivedGifts":
        expect(query.owner_id).toEqual({ "@type": "messageSenderChat", chat_id: -42 });
        expect(query.exclude_upgraded).toBe(false);
        expect(query.exclude_unsaved).toBe(true);
        return { "@type": "receivedGifts", gifts: [...(giftAvailable ? [collectible("8", -42)] : []), collectible("9", -43)] };
      case "setChatEmojiStatus": emojiStatus = query.emoji_status; return { "@type": "ok" };
      default: throw new Error("Unexpected fixture query");
    }
  });
  try {
    await vi.waitFor(() => expect(session.status().state).toBe("ready"));
    const change = { key: "emoji:22", expected: null, duration: 0 };
    await expect(session.saveChatEmojiStatus("-42", change)).resolves.toBe("unsupported");
    expect(request.mock.calls.some(([query]) => query["@type"] === "getChatBoostStatus")).toBe(false);
    admin = true;
    await expect(session.chatEmojiChoices("-42")).resolves.toEqual([]);
    boosted = true;
    await expect(session.chatInfo("-42")).resolves.toMatchObject({ canSetEmojiStatus: true, boosts: {
      level: 8, count: 12, next: 15, applied: 2, link: "https://t.me/boost/fixturechannel", storiesPerDay: 8,
      customReactions: 3, features: ["emojiStatus", "transcription"],
    } });
    await expect(session.chatEmojiChoices("-42")).resolves.toEqual([
      { key: "emoji:22", emoji: "22", section: "themed" },
      { key: "gift:8", section: "gifts", giftTitle: "Fixture collectible" },
    ]);
    await expect(session.saveChatEmojiStatus("-42", { ...change, key: "emoji:23" })).resolves.toBe("unsupported");
    await expect(session.saveChatEmojiStatus("-42", change)).resolves.toBe("saved");
    expect(request).toHaveBeenCalledWith({ "@type": "setChatEmojiStatus", chat_id: -42, emoji_status: {
      "@type": "emojiStatus", type: { "@type": "emojiStatusTypeCustomEmoji", custom_emoji_id: "22" }, expiration_date: 0,
    } });
    await expect(session.saveChatEmojiStatus("-42", { ...change, key: null })).resolves.toBe("changed");
    await expect(session.saveChatEmojiStatus("-42", { ...change, key: null,
      expected: { key: "emoji:22", emoji: "22", expiresAt: 0 } })).resolves.toBe("saved");
    expect(request).toHaveBeenCalledWith({ "@type": "setChatEmojiStatus", chat_id: -42, emoji_status: null });
    await expect(session.saveChatEmojiStatus("-42", { ...change, key: "gift:9" })).resolves.toBe("unsupported");
    giftAvailable = false;
    await expect(session.saveChatEmojiStatus("-42", { ...change, key: "gift:8" })).resolves.toBe("unsupported");
    giftAvailable = true;
    await expect(session.saveChatEmojiStatus("-42", { ...change, key: "gift:8" })).resolves.toBe("saved");
    expect(request).toHaveBeenCalledWith({ "@type": "setChatEmojiStatus", chat_id: -42, emoji_status: {
      "@type": "emojiStatus", expiration_date: 0, type: {
        "@type": "emojiStatusTypeUpgradedGift", upgraded_gift_id: "8", gift_title: "Fixture collectible", gift_name: "Fixture-1",
        model_custom_emoji_id: "0", symbol_custom_emoji_id: "0", backdrop_colors: null,
      },
    } });
  } finally { await session.close(); }
});

test("updates one group information field and refuses stale values or missing permission", async () => {
  let title = "Fixture Group";
  let description = "Initial description";
  let canChange = false;
  const { session, request } = harness((query) => {
    switch (query["@type"]) {
      case "getAuthorizationState": return { "@type": "authorizationStateReady" };
      case "getChat": return { "@type": "chat", id: -42, title,
        type: { "@type": "chatTypeBasicGroup", basic_group_id: 17 },
        permissions: { "@type": "chatPermissions", can_change_info: canChange } };
      case "getBasicGroup": return { "@type": "basicGroup", id: 17, is_active: true, status: { "@type": "chatMemberStatusMember" } };
      case "getBasicGroupFullInfo": return { "@type": "basicGroupFullInfo", description };
      case "setChatTitle": title = String(query.title); return { "@type": "ok" };
      case "setChatDescription": description = String(query.description); return { "@type": "ok" };
      default: throw new Error("Unexpected test query");
    }
  });
  try {
    await vi.waitFor(() => expect(session.status().state).toBe("ready"));
    await expect(session.chatInfo("-42")).resolves.toEqual({ title, description, editable: false, photoVersion: null });
    const name = { field: "title" as const, value: "Updated fixture", expected: title };
    await expect(session.saveChatInfo("-42", name)).resolves.toBe("unavailable");
    canChange = true;
    await expect(session.saveChatInfo("-42", { ...name, expected: "Stale fixture" })).resolves.toBe("changed");
    await expect(session.saveChatInfo("-42", name)).resolves.toBe("saved");
    await expect(session.saveChatInfo("-42", { field: "description", value: "", expected: description })).resolves.toBe("saved");
    await expect(session.chatInfo("-42")).resolves.toEqual({ title: "Updated fixture", description: "", editable: true, photoVersion: null });
    expect(request.mock.calls.filter(([query]) => ["setChatTitle", "setChatDescription"].includes(query["@type"]))).toEqual([
      [{ "@type": "setChatTitle", chat_id: -42, title: "Updated fixture" }],
      [{ "@type": "setChatDescription", chat_id: -42, description: "" }],
    ]);
  } finally { await session.close(); }
});

test("updates a chat photo only with unchanged photo identity and Telegram permission", async () => {
  const directory = await mkdtemp(join(tmpdir(), "makosh-chat-photo-"));
  const jpeg = Buffer.from([0xff, 0xd8, 0xff, 0xc0, 0, 8, 8, 0, 1, 0, 1, 1, 0xff, 0xd9]);
  let photoId = 0;
  let allowed = false;
  const { session, request } = harness((query) => {
    switch (query["@type"]) {
      case "getAuthorizationState": return { "@type": "authorizationStateReady" };
      case "getChat": return { "@type": "chat", id: -42, title: "Fixture", photo: photoId
        ? { "@type": "chatPhotoInfo", small: { "@type": "file", id: photoId } } : null,
        type: { "@type": "chatTypeSupergroup", supergroup_id: 17, is_channel: true } };
      case "getSupergroup": return { "@type": "supergroup", id: 17, is_channel: true,
        status: { "@type": "chatMemberStatusAdministrator", rights: { "@type": "chatAdministratorRights", can_change_info: allowed } } };
      case "getSupergroupFullInfo": return { "@type": "supergroupFullInfo", description: "" };
      case "setChatPhoto": photoId = query.photo === null ? 0 : 2; return { "@type": "ok" };
      default: throw new Error("Unexpected test query");
    }
  }, undefined, directory);
  try {
    await vi.waitFor(() => expect(session.status().state).toBe("ready"));
    const base64 = jpeg.toString("base64");
    await expect(session.saveChatPhoto("-42", base64, null)).resolves.toBe("unavailable");
    allowed = true;
    photoId = 1;
    await expect(session.saveChatPhoto("-42", base64, null)).resolves.toBe("changed");
    const info = (await session.chatInfo("-42"))!;
    expect(info.photoVersion).toMatch(/^[0-9a-f]{64}$/);
    await expect(session.saveChatPhoto("-42", base64, info.photoVersion!)).resolves.toBe("saved");
    const writes = request.mock.calls.filter(([query]) => query["@type"] === "setChatPhoto");
    expect(writes).toHaveLength(1);
    const photo = writes[0]?.[0].photo as TdObject;
    expect(photo).toMatchObject({ "@type": "inputChatPhotoStatic", photo: { "@type": "inputFileLocal" } });
    await expect(readFile(String((photo.photo as TdObject).path))).rejects.toMatchObject({ code: "ENOENT" });
    const current = (await session.chatInfo("-42"))!.photoVersion!;
    expect(current).not.toBe(info.photoVersion);
    await expect(session.removeChatPhoto("-42", info.photoVersion!)).resolves.toBe("changed");
    allowed = false;
    await expect(session.removeChatPhoto("-42", current)).resolves.toBe("unavailable");
    allowed = true;
    await expect(session.removeChatPhoto("-42", current)).resolves.toBe("saved");
    expect(request.mock.calls.filter(([query]) => query["@type"] === "setChatPhoto").slice(1)).toEqual([
      [{ "@type": "setChatPhoto", chat_id: -42, photo: null }],
    ]);
    expect((await session.chatInfo("-42"))?.photoVersion).toBeNull();
  } finally {
    await session.close();
    await rm(directory, { recursive: true, force: true });
  }
});

