test("preserves text-label links in edited messages and captions at the adjusted offsets", async () => {
  const url = "https://example.com/fixture";
  const text = "See linked label.";
  const entity = { "@type": "textEntity", offset: 4, length: 12, type: { "@type": "textEntityTypeTextUrl", url } };
  const formatted = { "@type": "formattedText", text, entities: [entity] };
  const row = { "@type": "message", chat_id: 42, is_outgoing: true, can_be_edited: true };
  const message = (formattedText: unknown) => ({ ...row, id: 25, content: { "@type": "messageText", text: formattedText } });
  const caption = (formattedText: unknown) => ({ ...row, id: 26, content: {
    "@type": "messageVideo", caption: formattedText,
    video: { "@type": "video", mime_type: "video/mp4", video: { "@type": "file", id: 7, size: 100 } },
  } });
  const { session, request } = harness((query) => {
    switch (query["@type"]) {
      case "getAuthorizationState": return { "@type": "authorizationStateReady" };
      case "getMessage": return Number(query.message_id) === 25 ? message(formatted) : caption(formatted);
      case "editMessageText": return message((query.input_message_content as TdObject).text);
      case "editMessageCaption": return caption(query.caption);
      default: throw new Error("Unexpected fixture query");
    }
  });
  try {
    await vi.waitFor(() => expect(session.status().state).toBe("ready"));
    const changed = "🙂 See linked label.";
    const links = [{ offset: 7, length: 12, url, hidden: true }];
    await expect(session.editText("42", "25", changed, text)).resolves.toMatchObject({ state: "sent", message: { links } });
    await expect(session.editCaption("42", "26", changed, text)).resolves.toMatchObject({ state: "sent", message: { links } });
    const original = [{ offset: 4, length: 12, url }];
    const replacement = [{ ...original[0]!, url: "https://example.org/updated" }];
    await expect(session.editText("42", "25", text, text, [], undefined, undefined,
      { original: [], replacement })).resolves.toEqual({ state: "failed" });
    expect(request.mock.calls.filter(([query]) => query["@type"] === "editMessageText")).toHaveLength(1);
    await expect(session.editText("42", "25", text, text, [], undefined, undefined, { original, replacement })).resolves.toMatchObject({
      state: "sent", message: { links: [{ ...replacement[0], hidden: true }] },
    });
    const removedCaption = await session.editCaption("42", "26", text, text, [], undefined, undefined, { original, replacement: [] });
    expect(removedCaption.state).toBe("sent");
    if (removedCaption.state === "sent") expect(removedCaption.message.links).toBeUndefined();
    const removed = await session.editText("42", "25", "See .", text);
    expect(removed.state).toBe("sent");
    if (removed.state === "sent") expect(removed.message.links).toBeUndefined();
  } finally { await session.close(); }
});

