test("lists and pages only installed custom emoji packs for the composer", async () => {
  const id = "9223372036854775807";
  const type = "stickerTypeCustomEmoji";
  let archived = false;
  const pack = { "@type": "stickerSetInfo", id, title: "Fixture installed pack", is_installed: true, is_archived: false,
    sticker_type: { "@type": type } };
  const first = 9007199254740993n;
  const entries = Array.from({ length: 21 }, (_, index) => ({
    "@type": "sticker", set_id: id, emoji: "🐱",
    full_type: { "@type": "stickerFullTypeCustomEmoji", custom_emoji_id: String(first + BigInt(index)) },
  }));
  const { session, request } = harness((query) => {
    switch (query["@type"]) {
      case "getAuthorizationState": return { "@type": "authorizationStateReady" };
      case "getInstalledStickerSets": return { "@type": "stickerSets", sets: [pack,
        { ...pack, id: "71", is_archived: true }, { ...pack, id: "72", sticker_type: { "@type": "stickerTypeRegular" } },
        { ...pack, id: "73", is_installed: false },
      ] };
      case "getStickerSet": return { ...pack, "@type": "stickerSet", is_archived: archived,
        stickers: [{ ...entries[0], set_id: "73" }, ...entries, entries[0]],
      };
      default: throw new Error("Unexpected TDLib call");
    }
  });
  try {
    await vi.waitFor(() => expect(session.status().state).toBe("ready"));
    await expect(session.installedEmojiPacks()).resolves.toEqual([{ id, title: pack.title }]);
    expect(request).toHaveBeenLastCalledWith({ "@type": "getInstalledStickerSets", sticker_type: { "@type": type } });
    const initial = schemas.installedEmojiPage.output.parse(await session.installedEmojiPage(id, 0));
    expect(initial?.choices).toHaveLength(20);
    expect(initial?.next).toBe(20);
    await expect(session.installedEmojiPage(id, 20)).resolves.toEqual({
      id, title: pack.title, choices: [{ id: String(first + 20n), emoji: "🐱" }], next: null,
    });
    await expect(session.installedEmojiPage("73", 0)).resolves.toBeNull();
    archived = true;
    await expect(session.installedEmojiPage(id, 20)).resolves.toBeNull();
  } finally { await session.close(); }
});

test("adds a verified message sticker to an owned regular pack and recognizes the same remote file", async () => {
  const packId = "9007199254740997";
  const name = "Fixture_Pack";
  const title = "Fixture sticker pack";
  const regular = { "@type": "stickerTypeRegular" };
  let allowed = true;
  let added = false;
  const file = (id: number) => ({ "@type": "file", id, remote: { "@type": "remoteFile", unique_id: "same-file" } });
  const { session, request } = harness((query) => {
    switch (query["@type"]) {
      case "getAuthorizationState": return { "@type": "authorizationStateReady" };
      case "getChat": return { "@type": "chat", id: 42, has_protected_content: !allowed };
      case "getMessage": return { "@type": "message", id: 101, chat_id: 42,
        content: { "@type": "messageSticker", sticker: { "@type": "sticker", sticker: file(71), emoji: "🐱",
          format: { "@type": "stickerFormatWebp" }, full_type: { "@type": "stickerFullTypeRegular" } } } };
      case "getOwnedStickerSets": return { "@type": "stickerSets", total_count: 3, sets: [
        { "@type": "stickerSetInfo", id: packId, title, sticker_type: regular, size: 2 },
        { "@type": "stickerSetInfo", id: "95", title: "Full regular pack", sticker_type: regular, size: 120 },
        { "@type": "stickerSetInfo", id: "96", title: "Emoji pack", sticker_type: { "@type": "stickerTypeCustomEmoji" } },
      ] };
      case "getStickerSet":
      case "searchStickerSet": return { "@type": "stickerSet", id: packId, title, name, is_owned: true, sticker_type: regular, stickers: added
        ? [{ "@type": "sticker", set_id: packId, sticker: file(72) }] : [] };
      case "addStickerToSet": added = true; return { "@type": "ok" };
      default: throw new Error("Unexpected fixture query");
    }
  });
  const mutations = () => request.mock.calls.map(([query]) => query).filter((query) => query["@type"] === "addStickerToSet");
  try {
    await vi.waitFor(() => expect(session.status().state).toBe("ready"));
    await expect(session.ownedStickerDestinations("42", "101")).resolves.toEqual({ sourceFileId: 71, packs: [{ id: packId, title }], next: null });
    await expect(session.addMessageStickerToOwnedPack("42", "101", 72, packId, title)).resolves.toBe("changed");
    await expect(session.addMessageStickerToOwnedPack("42", "101", 71, packId, "Earlier pack title")).resolves.toBe("changed");
    allowed = false;
    await expect(session.ownedStickerDestinations("42", "101")).resolves.toBeNull();
    await expect(session.addMessageStickerToOwnedPack("42", "101", 71, packId, title)).resolves.toBe("unavailable");
    expect(mutations()).toEqual([]);
    allowed = true;
    await expect(session.addMessageStickerToOwnedPack("42", "101", 71, packId, title)).resolves.toBe("added");
    await expect(session.addMessageStickerToOwnedPack("42", "101", 71, packId, title)).resolves.toBe("already");
    expect(mutations()).toEqual([{ "@type": "addStickerToSet", user_id: 0, name, sticker: {
      "@type": "newSticker", sticker: { "@type": "inputFileId", id: 71 }, format: { "@type": "stickerFormatWebp" }, emojis: "🐱", keywords: [],
    } }]);
  } finally { await session.close(); }
});

test("creates one regular pack from the reviewed message using the selected Telegram short name", async () => {
  const id = "9007199254740997";
  let occupied = false;
  let nameTakenDuringCreate = false;
  let protectedChat = false;
  const pack = { "@type": "stickerSet", id, name: "Fixture_Pack", title: "Fixture title", is_owned: true,
    sticker_type: { "@type": "stickerTypeRegular" }, stickers: [{ "@type": "sticker", set_id: id, sticker: { "@type": "file", id: 72 } }] };
  const { session, request } = harness((query) => {
    switch (query["@type"]) {
      case "getAuthorizationState": return { "@type": "authorizationStateReady" };
      case "getChat": return { "@type": "chat", id: 42, has_protected_content: protectedChat };
      case "getMessage": return { "@type": "message", id: 101, chat_id: 42,
        content: { "@type": "messageSticker", sticker: { "@type": "sticker", emoji: "🐱",
          sticker: { "@type": "file", id: 71 }, full_type: { "@type": "stickerFullTypeRegular" }, format: { "@type": "stickerFormatWebp" } } } };
      case "checkStickerSetName": return { "@type": occupied ? "checkStickerSetNameResultNameOccupied" : "checkStickerSetNameResultOk" };
      case "createNewStickerSet":
        if (nameTakenDuringCreate) throw new TdError(400, "PACK_SHORT_NAME_OCCUPIED");
        occupied = true;
        return pack;
      case "searchStickerSet": return pack;
      default: throw new Error("Unexpected fixture query");
    }
  });
  const create = (fileId = 71, name = "Fixture_Pack") => session.createOwnedPackFromMessage("42", "101", fileId, name, " Fixture title ");
  const mutations = () => request.mock.calls.map(([query]) => query).filter((query) => query["@type"] === "createNewStickerSet");
  try {
    await vi.waitFor(() => expect(session.status().state).toBe("ready"));
    await expect(create(71, "bad name")).resolves.toBe("nameInvalid");
    await expect(create(72)).resolves.toBe("changed");
    protectedChat = true;
    await expect(create()).resolves.toBe("unavailable");
    expect(mutations()).toEqual([]);
    protectedChat = false;
    await expect(create()).resolves.toBe("created");
    await expect(create()).resolves.toBe("nameTaken");
    expect(mutations()).toEqual([{ "@type": "createNewStickerSet", user_id: 0, name: "Fixture_Pack", title: "Fixture title",
      sticker_type: { "@type": "stickerTypeRegular" }, needs_repainting: false, source: "", stickers: [{
        "@type": "newSticker", sticker: { "@type": "inputFileId", id: 71 }, format: { "@type": "stickerFormatWebp" }, emojis: "🐱", keywords: [],
      }] }]);
    expect(request).toHaveBeenCalledWith({ "@type": "searchStickerSet", name: "Fixture_Pack", ignore_cache: true });
    occupied = false;
    nameTakenDuringCreate = true;
    await expect(create()).resolves.toBe("nameTaken");
  } finally { await session.close(); }
});

test("creates an owned pack from a bounded staged static WebP and removes the staging file after confirmation", async () => {
  const directory = await mkdtemp(join(tmpdir(), "makosh-sticker-image-"));
  const image = "UklGRiQAAABXRUJQVlA4TBcAAAAv/8EPAAdQwYYUtv8BAEX6/58i+p/6DwA=";
  const id = "9007199254740997";
  const name = "Fixture_Pack";
  const title = "Fixture title";
  let path: string | undefined;
  const pack = { "@type": "stickerSet", id, name, title, is_owned: true, sticker_type: { "@type": "stickerTypeRegular" },
    stickers: [{ "@type": "sticker", set_id: id, sticker: { "@type": "file", id: 72 } }] };
  const { session, request } = harness((query) => {
    switch (query["@type"]) {
      case "getAuthorizationState": return { "@type": "authorizationStateReady" };
      case "checkStickerSetName": return { "@type": "checkStickerSetNameResultOk" };
      case "createNewStickerSet": {
        const item = (query.stickers as TdObject[])[0]!;
        path = ((item.sticker as TdObject).path) as string;
        expect(path.startsWith(directory)).toBe(true);
        expect(readFileSync(path).toString("base64")).toBe(image);
        return pack;
      }
      case "searchStickerSet": return pack;
      default: throw new Error("Unexpected fixture query");
    }
  }, undefined, directory);
  try {
    await vi.waitFor(() => expect(session.status().state).toBe("ready"));
    const tooSmall = Buffer.from(image, "base64");
    tooSmall[21] = 0;
    tooSmall[22] &= 0xc0;
    await expect(session.createOwnedPackFromImage(name, title, ["🐱"], tooSmall.toString("base64"))).resolves.toBe("unavailable");
    await expect(session.createOwnedPackFromImage(name, title, ["text"], image)).resolves.toBe("unavailable");
    expect(request).not.toHaveBeenCalledWith(expect.objectContaining({ "@type": "checkStickerSetName" }));
    await expect(session.createOwnedPackFromImage(name, title, ["🐱"], image)).resolves.toBe("created");
    expect(request).toHaveBeenCalledWith(expect.objectContaining({ "@type": "createNewStickerSet", name, title, stickers: [
      { "@type": "newSticker", sticker: { "@type": "inputFileLocal", path }, format: { "@type": "stickerFormatWebp" }, emojis: "🐱", keywords: [] },
    ] }), 120_000);
    expect(path && existsSync(path)).toBe(false);
  } finally { await session.close(); await rm(directory, { recursive: true, force: true }); }
});

