test.skipIf(!videoTestBin).each(["chat", "shortcut", "channel inbox"])("normalizes a synthetic clip to a square Telegram video note for %s", async (destination) => {
  const directory = await mkdtemp(join(tmpdir(), "makosh-video-note-"));
  const clip = join(directory, "fixture.mp4");
  let output: { path: string; length: number; duration: number; width: number; height: number } | undefined;
  const inbox = destination === "channel inbox";
  const inboxTopic = (id: number) => ({ "@type": "messageTopicDirectMessages", direct_messages_chat_topic_id: id });
  const { session, request } = harness((query) => {
    switch (query["@type"]) {
      case "getAuthorizationState": return { "@type": "authorizationStateReady" };
      case "getChat": return inbox ? { "@type": "chat", id: query.chat_id, type: { "@type": "chatTypeSupergroup",
        supergroup_id: -Number(query.chat_id), is_channel: query.chat_id === -42 } }
        : { "@type": "chat", id: 42, type: { "@type": "chatTypePrivate", user_id: 42 } };
      case "getSupergroupFullInfo": return { "@type": "supergroupFullInfo", direct_messages_chat_id: query.supergroup_id === 42 ? -43 : -42 };
      case "getSupergroup": return query.supergroup_id === 42
        ? { "@type": "supergroup", id: 42, is_channel: true, status: { "@type": "chatMemberStatusAdministrator",
          rights: { "@type": "chatAdministratorRights", can_manage_direct_messages: true } } }
        : { "@type": "supergroup", id: 43, is_direct_messages_group: true, is_administered_direct_messages_group: true };
      case "getDirectMessagesChatTopic": return { "@type": "directMessagesChatTopic", chat_id: -43, id: 8 };
      case "getMessage": return { "@type": "message", id: query.message_id, chat_id: -43, topic_id: inboxTopic(query.message_id === 9 ? 8 : 7) };
      case "getOption": return { "@type": "optionValueString", value: "1.8.99" };
      case "checkQuickReplyShortcutName":
      case "loadQuickReplyShortcuts": return { "@type": "ok" };
      case "getCurrentState": return { "@type": "updates", updates: [{ "@type": "updateQuickReplyShortcuts", shortcut_ids: [] }] };
      case "sendMessage":
      case "addQuickReplyShortcutMessage": {
        const content = query.input_message_content as TdObject;
        expect(content["@type"]).toBe("inputMessageVideoNote");
        expect(content.caption).toBeUndefined();
        if (inbox) expect(query).toMatchObject({ chat_id: -43, topic_id: inboxTopic(8),
          reply_to: { "@type": "inputMessageReplyToMessage", message_id: 9 } });
        const video = content.video_note as TdObject;
        expect(video["@type"]).toBe("inputVideoNote");
        const path = String((video.video_note as TdObject).path);
        const probe = JSON.parse(execFileSync(`${videoTestBin}/ffprobe`, ["-v", "error", "-select_streams", "v:0",
          "-show_entries", "stream=width,height", "-of", "json", path], { encoding: "utf8" }));
        output = { path, length: Number(video.length), duration: Number(video.duration),
          width: probe.streams[0].width, height: probe.streams[0].height };
        if (inbox) return { "@type": "message", id: 27, chat_id: -43, topic_id: inboxTopic(8), is_outgoing: true,
          reply_to: { "@type": "messageReplyToMessage", chat_id: -43, message_id: 9 },
          content: { "@type": "messageVideoNote", video_note: { "@type": "videoNote", duration: 1,
            length: 384, video: { "@type": "file", id: 227, size: 4200 } } } };
        return { "@type": destination === "chat" ? "message" : "quickReplyMessage", id: 7, chat_id: 42, is_outgoing: true,
          content: { "@type": "messageVideoNote" } };
      }
      default: throw new Error("Unexpected fixture query");
    }
  }, undefined, directory);
  try {
    execFileSync(`${videoTestBin}/ffmpeg`, ["-v", "error", "-f", "lavfi", "-i", "color=blue:s=160x90:r=15",
      "-t", "0.5", "-c:v", "libx264", "-pix_fmt", "yuv420p", clip]);
    await vi.waitFor(() => expect(session.status().state).toBe("ready"));
    const bytes = await readFile(clip);
    if (destination === "chat") {
      await expect(session.sendVideoNote("42", bytes.toString("base64"), "mp4")).resolves.toMatchObject({ state: "sent" });
    } else if (inbox) {
      const recording = { base64: bytes.toString("base64"), format: "mp4" as const };
      await expect(session.sendChannelInboxVideoNote("-42", "-43", "8", recording, "10")).resolves.toEqual({ state: "failed" });
      expect(request.mock.calls.some(([query]) => query["@type"] === "sendMessage")).toBe(false);
      await expect(session.sendChannelInboxVideoNote("-42", "-43", "8", recording, "9")).resolves.toMatchObject({
        state: "sent", message: { id: "27", replyTo: "9", videoNote: true },
      });
    } else {
      const body = new ReadableStream<Uint8Array>({ start(controller) { controller.enqueue(bytes); controller.close(); } });
      const lifecycle = { onPendingUpload: vi.fn(), onDispatch: vi.fn(), signal: new AbortController().signal };
      await expect(session.addQuickReplyDocumentStream({ name: "fixture", filename: "fixture.mp4", size: bytes.length,
        caption: "", videoNote: true }, body, () => true, lifecycle)).resolves.toEqual({ state: "submitted" });
      expect(lifecycle.onDispatch).toHaveBeenCalledOnce();
    }
    expect(output).toMatchObject({ length: 384, duration: 1, width: 384, height: 384 });
    await expect(readFile(output!.path)).rejects.toMatchObject({ code: "ENOENT" });
  } finally {
    await session.close();
    await rm(directory, { recursive: true, force: true });
  }
});

test.skipIf(!videoTestBin).each(["ogg", "webm", "mp4"] as const)(
  "sends a packed waveform with a synthetic %s voice note", async (format) => {
    const directory = await mkdtemp(join(tmpdir(), "makosh-voice-wave-"));
    const input = join(directory, `fixture.${format}`);
    let sentWaveform: unknown;
    const { session, request } = harness((query) => {
      switch (query["@type"]) {
        case "getAuthorizationState": return { "@type": "authorizationStateReady" };
        case "getChat": return { "@type": "chat", id: 42, type: { "@type": "chatTypePrivate", user_id: 42 } };
        case "getOption": return { "@type": "optionValueString", value: "1.8.99" };
        case "sendMessage": {
          const content = query.input_message_content as TdObject;
          expect(content["@type"]).toBe("inputMessageVoiceNote");
          const voice = content.voice_note as TdObject;
          expect(voice).toMatchObject({ "@type": "inputVoiceNote", duration: 1, voice_note: { "@type": "inputFileLocal" } });
          sentWaveform = voice.waveform;
          return { "@type": "message", id: 7, chat_id: 42, is_outgoing: true, content: { "@type": "messageVoiceNote" } };
        }
        default: throw new Error("Unexpected fixture query");
      }
    }, undefined, directory);
    try {
      execFileSync(`${videoTestBin}/ffmpeg`, ["-v", "error",
        "-f", "lavfi", "-i", "anullsrc=r=48000:cl=mono:d=0.3",
        "-f", "lavfi", "-i", "sine=frequency=440:sample_rate=48000:duration=0.4",
        "-filter_complex", "[0:a][1:a]concat=n=2:v=0:a=1", "-c:a", format === "mp4" ? "aac" : "libopus", input]);
      await vi.waitFor(() => expect(session.status().state).toBe("ready"));
      const bytes = await readFile(input);
      await expect(session.sendVoice("42", bytes.toString("base64"), 1, format)).resolves.toMatchObject({ state: "sent" });
      const waveform = decodeVoiceWaveform(sentWaveform);
      expect(waveform).toHaveLength(100);
      expect(waveform?.slice(0, 20)).toEqual(Array(20).fill(0));
      expect(waveform?.slice(-20).every((bar) => bar > 0)).toBe(true);
      expect(request.mock.calls.filter(([query]) => query["@type"] === "sendMessage")).toHaveLength(1);
      await expect(session.sendVoice("42", bytes.toString("base64"), 1, format, undefined, undefined, undefined,
        { startMs: 350, endMs: 650 })).resolves.toMatchObject({ state: "sent" });
      expect(decodeVoiceWaveform(sentWaveform)).toHaveLength(100);
      expect(decodeVoiceWaveform(sentWaveform)?.every((bar) => bar > 0)).toBe(true);
      await expect(session.sendVoice("42", bytes.toString("base64"), 1, format, undefined, undefined, undefined,
        { startMs: 600, endMs: 1100 })).resolves.toMatchObject({ state: "failed" });
      expect(request.mock.calls.filter(([query]) => query["@type"] === "sendMessage")).toHaveLength(2);
    } finally {
      await session.close();
      await rm(directory, { recursive: true, force: true });
    }
  },
);

