test("checks the previous media caption and keeps its placement when changing or clearing it", async () => {
  let text = "Fixture caption";
  let allowed = true;
  let above = true;
  const row = () => ({ "@type": "message", id: 9, chat_id: 42, is_outgoing: true, can_be_edited: allowed,
    content: { "@type": "messageVideo", show_caption_above_media: above,
      video: { "@type": "video", mime_type: "video/mp4", video: { "@type": "file", id: 7, size: 100 } },
      caption: { "@type": "formattedText", text, entities: [] } } });
  const { session, request } = harness((query) => {
    switch (query["@type"]) {
      case "getAuthorizationState": return { "@type": "authorizationStateReady" };
      case "getMessage": return row();
      case "editMessageCaption":
        text = String((query.caption as TdObject).text);
        above = query.show_caption_above_media === true;
        return row();
      default: throw new Error("Unexpected fixture query");
    }
  });
  try {
    await vi.waitFor(() => expect(session.status().state).toBe("ready"));
    await expect(session.editCaption("42", "9", "Next caption", "Stale caption")).resolves.toEqual({ state: "failed" });
    await expect(session.editCaption("42", "9", "Next caption", "Fixture caption")).resolves.toMatchObject({
      state: "sent", message: { editableCaption: true, captionAboveMedia: true, document: { caption: "Next caption" } },
    });
    await expect(session.editCaption("42", "9", "Next caption", "Next caption", [], undefined,
      { above: false, expected: false })).resolves.toEqual({ state: "failed" });
    const moved = await session.editCaption("42", "9", "Next caption", "Next caption", [], undefined,
      { above: false, expected: true });
    expect(moved).toMatchObject({ state: "sent", message: { canMoveCaption: true, document: { caption: "Next caption" } } });
    if (moved.state === "sent") expect(moved.message.captionAboveMedia).toBeUndefined();
    allowed = false;
    await expect(session.editCaption("42", "9", "", "Next caption")).resolves.toEqual({ state: "failed" });
    allowed = true;
    const cleared = await session.editCaption("42", "9", "", "Next caption");
    expect(cleared.state).toBe("sent");
    if (cleared.state === "sent") expect(cleared.message.document?.caption).toBeUndefined();
    expect(request.mock.calls.filter(([query]) => query["@type"] === "editMessageCaption")).toEqual([
      [{ "@type": "editMessageCaption", chat_id: 42, message_id: 9,
        caption: { "@type": "formattedText", text: "Next caption", entities: [] }, show_caption_above_media: true }],
      [{ "@type": "editMessageCaption", chat_id: 42, message_id: 9,
        caption: { "@type": "formattedText", text: "Next caption", entities: [] }, show_caption_above_media: false }],
      [{ "@type": "editMessageCaption", chat_id: 42, message_id: 9,
        caption: { "@type": "formattedText", text: "", entities: [] }, show_caption_above_media: false }],
    ]);
  } finally { await session.close(); }
});

test.skipIf(!videoTestBin).each([
  ["mp4", "h264", false], ["mov", "h264", false], ["mov", "hevc", false],
  ["mp4", "hevc", false], ["mov", "hevc", true],
])("prepares %s %s video with HDR=%s", async (extension, codec, hdr) => {
  const directory = await mkdtemp(join(tmpdir(), "makosh-upload-video-"));
  const name = `fixture.${extension}`;
  const clip = join(directory, name);
  const at = Math.floor(Date.now() / 1000) + 3600;
  const effect = "9007199254740997";
  let outputAudio: string | undefined;
  const { session, request } = harness((query) => {
    switch (query["@type"]) {
      case "getAuthorizationState": return { "@type": "authorizationStateReady" };
      case "getChat": return { "@type": "chat", id: 42, type: { "@type": "chatTypePrivate", user_id: 42 } };
      case "getOption": return { "@type": "optionValueString", value: "1.8.99" };
      case "getMe": return { "@type": "user", id: 7, is_premium: false };
      case "getUser": return { "@type": "user", id: 42, type: { "@type": "userTypeRegular" },
        status: { "@type": "userStatusOffline", was_online: 1700000000 } };
      case "getCurrentState": return { "@type": "updates", updates: [{ "@type": "updateAvailableMessageEffects", reaction_effect_ids: [effect] }] };
      case "getMessageEffect": return { "@type": "messageEffect", id: query.effect_id, emoji: "🔥", is_premium: false,
        type: { "@type": "messageEffectTypeEmojiReaction" } };
      case "sendMessage": {
        const video = ((query.input_message_content as TdObject).video as TdObject).video as TdObject;
        outputAudio = execFileSync(`${videoTestBin}/ffprobe`, ["-v", "error", "-select_streams", "a:0",
          "-show_entries", "stream=codec_name", "-of", "csv=p=0", String(video.path)], { encoding: "utf8" }).trim();
        return { "@type": "message", id: 7, chat_id: 42, is_outgoing: true, scheduling_state: (query.options as TdObject).scheduling_state,
          effect_id: (query.options as TdObject).effect_id, content: { "@type": "messageVideo" } };
      }
      default: throw new Error("Unexpected fixture query");
    }
  }, undefined, directory);
  const send = (bytes: Buffer, delivery: import("../src/core/contract.ts").AttachmentSendDelivery = { silent: true, at }) =>
    session.sendDocumentStream("42", name, "Fixture caption", bytes.length,
    new ReadableStream<Uint8Array>({ start(controller) { controller.enqueue(bytes); controller.close(); } }),
    () => true, undefined, undefined, true, { spoiler: true, captionAbove: true }, delivery);
  try {
    execFileSync(`${videoTestBin}/ffmpeg`, ["-v", "error", "-f", "lavfi", "-i", "color=blue:s=160x90:r=15",
      "-f", "lavfi", "-i", "sine=frequency=440:sample_rate=48000",
      "-t", "0.5", "-c:v", codec === "hevc" ? "libx265" : "libx264",
      ...(codec === "hevc" ? ["-x265-params", hdr
        ? "log-level=error:pools=1:colorprim=bt2020:transfer=smpte2084:colormatrix=bt2020nc" : "log-level=error:pools=1"] : []),
      ...(hdr ? ["-movflags", "+write_colr"] : []),
      "-pix_fmt", hdr ? "yuv420p10le" : "yuv420p", "-c:a", extension === "mov" ? "pcm_s16le" : "aac", clip]);
    await vi.waitFor(() => expect(session.status().state).toBe("ready"));
    await expect(send(Buffer.from("Not an MP4"))).resolves.toEqual({ state: "failed", uploadRejection: "video_preparation_failed" });
    const result = await send(await readFile(clip));
    if (hdr) {
      expect(result).toEqual({ state: "failed", uploadRejection: "video_preparation_failed" });
      expect(request.mock.calls.some(([query]) => query["@type"] === "sendMessage")).toBe(false);
      return;
    }
    expect(result).toMatchObject({ state: "sent" });
    expect(outputAudio).toBe("aac");
    const calls = request.mock.calls.filter(([query]) => query["@type"] === "sendMessage");
    expect(calls).toEqual([[expect.objectContaining({ options: { "@type": "messageSendOptions", disable_notification: true,
      scheduling_state: { "@type": "messageSchedulingStateSendAtDate", send_date: at } }, input_message_content: {
      "@type": "inputMessageVideo", video: { "@type": "inputVideo", width: 160, height: 90, duration: 1, supports_streaming: true,
        video: { "@type": "inputFileLocal", path: expect.stringMatching((extension === "mov" || codec === "hevc") ? /telegram-video\.mp4$/ : /fixture\.mp4$/) } },
      caption: { "@type": "formattedText", text: "Fixture caption", entities: [] },
      has_spoiler: true, show_caption_above_media: true,
    } })]]);
    if (extension === "mp4" && codec === "h264") {
      const bytes = await readFile(clip);
      const input = { id: "42", name, size: bytes.length, caption: "Fixture caption", delivery: { effect, silent: true, whenOnline: true } };
      expect(schemas.prepareDocumentUpload.input.safeParse(input).success).toBe(false);
      const { delivery } = schemas.prepareDocumentUpload.input.parse({ ...input, video: true });
      await expect(send(bytes, delivery)).resolves.toMatchObject({ state: "sent", message: { effectId: effect } });
      expect(request).toHaveBeenLastCalledWith(expect.objectContaining({
        "@type": "sendMessage", options: { "@type": "messageSendOptions", disable_notification: true, effect_id: effect,
          scheduling_state: { "@type": "messageSchedulingStateSendWhenOnline" } },
      }));
    }
  } finally {
    await session.close();
    await rm(directory, { recursive: true, force: true });
  }
});

test.skipIf(!videoTestBin).each(["1.8.69", "1.8.99"])("trims or preserves original video and sends its chosen cover on TDLib %s", async (version) => {
  const directory = await mkdtemp(join(tmpdir(), "makosh-edited-video-"));
  const name = "fixture.mp4";
  const clip = join(directory, name);
  const edit = { startMs: 500, endMs: 1500, quality: "480", coverMs: 1250 } as const;
  const staged: string[] = [];
  let originalQuality = false;
  let sourceBytes: Buffer;
  const pixel = (path: string) => execFileSync(`${videoTestBin}/ffmpeg`, ["-v", "error", "-i", path,
    "-frames:v", "1", "-vf", "scale=1:1,format=rgb24", "-f", "rawvideo", "pipe:1"]);
  const { session, request } = harness((query) => {
    switch (query["@type"]) {
      case "getAuthorizationState": return { "@type": "authorizationStateReady" };
      case "getChat": return { "@type": "chat", id: 42, type: { "@type": "chatTypePrivate", user_id: 42 } };
      case "getOption": return { "@type": "optionValueString", value: version };
      case "sendMessage": {
        const content = query.input_message_content as TdObject;
        const media = version === "1.8.99" ? content.video as TdObject : content;
        expect(media).toMatchObject({ "@type": version === "1.8.99" ? "inputVideo" : "inputMessageVideo",
          width: originalQuality ? 640 : 480, height: originalQuality ? 360 : 270, duration: originalQuality ? 2 : 1, supports_streaming: true });
        expect(content.caption).toMatchObject({ text: "Fixture caption" });
        expect(content.has_spoiler).toBe(true);
        const video = String((media.video as TdObject).path);
        const cover = String((media.cover as TdObject).path);
        staged.push(video, cover);
        if (originalQuality) expect(readFileSync(video)).toEqual(sourceBytes);
        const first = pixel(video);
        const chosen = pixel(cover);
        expect(first[0]).toBeGreaterThan(first[2]);
        expect(chosen[2]).toBeGreaterThan(chosen[0]);
        const seconds = Number(execFileSync(`${videoTestBin}/ffprobe`, ["-v", "error",
          "-show_entries", "format=duration", "-of", "csv=p=0", video], { encoding: "utf8" }).trim());
        expect(seconds).toBeCloseTo(originalQuality ? 2 : 1, 1);
        return { "@type": "message", id: 7, chat_id: 42, is_outgoing: true, content: { "@type": "messageVideo" } };
      }
      default: throw new Error("Unexpected fixture query");
    }
  }, undefined, directory);
  try {
    execFileSync(`${videoTestBin}/ffmpeg`, ["-v", "error", "-f", "lavfi", "-i", "color=red:s=640x360:r=20:d=1",
      "-f", "lavfi", "-i", "color=blue:s=640x360:r=20:d=1", "-filter_complex", "[0:v][1:v]concat=n=2:v=1:a=0",
      "-c:v", "libx264", "-pix_fmt", "yuv420p", clip]);
    await vi.waitFor(() => expect(session.status().state).toBe("ready"));
    sourceBytes = await readFile(clip);
    const blob = new Blob([new Uint8Array(sourceBytes)]);
    const send = (videoEdit: import("../src/core/contract.ts").VideoEdit) => session.sendDocumentStream("42", name, "Fixture caption", blob.size,
      blob.stream(), () => true, undefined, undefined, true, { spoiler: true, videoEdit });
    await expect(send({ ...edit, endMs: 3000 })).resolves.toEqual({ state: "failed", uploadRejection: "video_preparation_failed" });
    expect(request.mock.calls.filter(([query]) => query["@type"] === "sendMessage")).toHaveLength(0);
    await expect(send(edit)).resolves.toMatchObject({ state: "sent" });
    originalQuality = true;
    const coverOnly = { startMs: 0, endMs: 2000, quality: "original", coverMs: 1250 } as const;
    await expect(send({ ...coverOnly, endMs: 1750 })).resolves.toEqual({ state: "failed", uploadRejection: "video_preparation_failed" });
    await expect(send(coverOnly)).resolves.toMatchObject({ state: "sent" });
    expect(request.mock.calls.filter(([query]) => query["@type"] === "sendMessage")).toHaveLength(2);
    expect(staged).toHaveLength(4);
    expect(staged.some(existsSync)).toBe(false);
  } finally {
    await session.close();
    await rm(directory, { recursive: true, force: true });
  }
});

const hdrCoverTestSupported = videoTestBin && (() => {
  try {
    const help = execFileSync(`${videoTestBin}/ffmpeg`, ["-hide_banner", "-h", "filter=scale"], { encoding: "utf8" });
    return help.includes("perceptual tone mapping") && help.includes("out_transfer");
  } catch {
    return false;
  }
})();

test.skipIf(!hdrCoverTestSupported).each([
  { transfer: "smpte2084", unsupported: true },
  { transfer: "arib-std-b67", unsupported: false },
])("retains $transfer HDR in original and trimmed video and tone-maps the cover and GIF to SDR", async ({ transfer, unsupported }) => {
  const directory = await mkdtemp(join(tmpdir(), "makosh-hdr-cover-"));
  const name = "hdr-fixture.mp4";
  const clip = join(directory, name);
  let source: Buffer;
  let trimming = false;
  const { session, request } = harness((query) => {
    switch (query["@type"]) {
      case "getAuthorizationState": return { "@type": "authorizationStateReady" };
      case "getChat": return { "@type": "chat", id: 42, type: { "@type": "chatTypePrivate", user_id: 42 } };
      case "getOption": return { "@type": "optionValueString", value: "1.8.99" };
      case "sendMessage": {
        const content = query.input_message_content as TdObject;
        if (content["@type"] === "inputMessageAnimation") {
          const animation = content.animation as TdObject;
          const file = String((animation.animation as TdObject).path);
          const info = JSON.parse(execFileSync(`${videoTestBin}/ffprobe`, ["-v", "error", "-show_entries",
            "stream=codec_name,pix_fmt,color_primaries,color_space,color_transfer:format=duration", "-of", "json", file], { encoding: "utf8" }));
          expect(info.streams).toEqual([{ codec_name: "h264", pix_fmt: "yuv420p", color_space: "bt709",
            color_transfer: "bt709", color_primaries: "bt709" }]);
          expect(Number(info.format.duration)).toBeCloseTo(0.5, 1);
          const rgb = execFileSync(`${videoTestBin}/ffmpeg`, ["-v", "error", "-i", file,
            "-frames:v", "1", "-pix_fmt", "rgb24", "-f", "rawvideo", "pipe:1"]);
          const levels = [20, 60, 100, 140].map((x) => rgb[(48 * 160 + x) * 3]!);
          expect(levels[0]).toBeLessThan(50);
          expect(levels[1]).toBeGreaterThan(75);
          expect(levels[2]).toBeGreaterThan(levels[1]! + 25);
          expect(levels[3]).toBeGreaterThan(levels[2]! + 15);
          expect(content.caption).toMatchObject({ text: "Fixture HDR GIF" });
          return { "@type": "message", id: 8, chat_id: 42, is_outgoing: true, content: { "@type": "messageAnimation" } };
        }
        const video = content.video as TdObject;
        expect(video).toMatchObject({ width: 160, height: 96, duration: 1, supports_streaming: false });
        const file = String((video.video as TdObject).path);
        if (!trimming) expect(readFileSync(file)).toEqual(source);
        else {
          expect(file).toMatch(/\.edited\.mp4$/);
          const info = JSON.parse(execFileSync(`${videoTestBin}/ffprobe`, ["-v", "error", "-select_streams", "v:0",
            "-read_intervals", "%+#4", "-show_entries",
            "stream=codec_name,pix_fmt,color_primaries,color_space,color_transfer,color_range:format=duration:frame_side_data=side_data_type,max_luminance,max_content,max_average",
            "-of", "json", file], { encoding: "utf8" }));
          expect(info.streams[0]).toMatchObject({ codec_name: "hevc", pix_fmt: "yuv420p10le",
            color_primaries: "bt2020", color_space: "bt2020nc", color_transfer: transfer, color_range: "tv" });
          expect(Number(info.format.duration)).toBeCloseTo(0.5, 1);
          if (transfer === "smpte2084") {
            expect(info.frames[0].side_data_list).toEqual(expect.arrayContaining([
              expect.objectContaining({ side_data_type: "Mastering display metadata", max_luminance: "40000000/10000" }),
              expect.objectContaining({ side_data_type: "Content light level metadata", max_content: 4000, max_average: 400 }),
            ]));
          }
        }
        const cover = String((video.cover as TdObject).path);
        const rgb = execFileSync(`${videoTestBin}/ffmpeg`, ["-v", "error", "-i", cover,
          "-frames:v", "1", "-pix_fmt", "rgb24", "-f", "rawvideo", "pipe:1"]);
        const levels = [20, 60, 100, 140].map((x) => rgb[(48 * 160 + x) * 3]!);
        expect(levels[0]).toBeLessThan(35);
        expect(levels[1]).toBeGreaterThan(85);
        expect(levels[2]).toBeGreaterThan(levels[1]! + 30);
        expect(levels[3]).toBeGreaterThan(levels[2]! + 18);
        return { "@type": "message", id: 7, chat_id: 42, is_outgoing: true, content: { "@type": "messageVideo" } };
      }
      default: throw new Error("Unexpected fixture query");
    }
  }, undefined, directory);
  try {
    const hdr10 = transfer === "smpte2084"
      ? ":hdr10=1:master-display=G(8500,39850)B(6550,2300)R(35400,14600)WP(15635,16450)L(40000000,50):max-cll=4000,400" : "";
    const generate = (path: string, primaries: string) => execFileSync(`${videoTestBin}/ffmpeg`, ["-v", "error",
      "-f", "lavfi", "-i", "nullsrc=s=160x96:r=10:d=1,format=yuv420p10le,geq=lum='if(lt(X,40),195,if(lt(X,80),509,if(lt(X,120),723,855)))':cb=512:cr=512",
      "-c:v", "libx265", "-x265-params", `log-level=error:pools=1:colorprim=${primaries}:transfer=${transfer}:colormatrix=bt2020nc${hdr10}`,
      "-pix_fmt", "yuv420p10le", "-movflags", "+write_colr", path]);
    generate(clip, "bt2020");
    source = await readFile(clip);
    await vi.waitFor(() => expect(session.status().state).toBe("ready"));
    const send = (bytes: Buffer, quality: "original" | "720") => {
      const blob = new Blob([new Uint8Array(bytes)]);
      return session.sendDocumentStream("42", name, "", blob.size, blob.stream(), () => true, undefined, undefined, true,
        { videoEdit: quality === "original" ? { startMs: 0, endMs: 1000, quality, coverMs: 300 }
          : { startMs: 200, endMs: 700, quality, coverMs: 400 } });
    };
    const sendGif = (bytes: Buffer) => {
      const blob = new Blob([new Uint8Array(bytes)]);
      return session.sendDocumentStream("42", name, "Fixture HDR GIF", blob.size, blob.stream(), () => true, undefined, undefined,
        undefined, { mediaKind: "animation", animationTrim: { startMs: 200, endMs: 700 } });
    };
    if (unsupported) {
      const ambiguous = join(directory, "ambiguous.mp4");
      generate(ambiguous, "bt709");
      const ambiguousBytes = await readFile(ambiguous);
      await expect(send(ambiguousBytes, "original")).resolves.toEqual({ state: "failed", uploadRejection: "video_preparation_failed" });
      await expect(send(ambiguousBytes, "720")).resolves.toEqual({ state: "failed", uploadRejection: "video_preparation_failed" });
      await expect(sendGif(ambiguousBytes)).resolves.toEqual({ state: "failed", uploadRejection: "media_preparation_failed" });
    }
    expect(request.mock.calls.filter(([query]) => query["@type"] === "sendMessage")).toHaveLength(0);
    await expect(send(source, "original")).resolves.toMatchObject({ state: "sent" });
    trimming = true;
    await expect(send(source, "720")).resolves.toMatchObject({ state: "sent" });
    await expect(sendGif(source)).resolves.toMatchObject({ state: "sent" });
    expect(request.mock.calls.filter(([query]) => query["@type"] === "sendMessage")).toHaveLength(3);
  } finally {
    await session.close();
    await rm(directory, { recursive: true, force: true });
  }
});

const dolbyVisionEditSupported = hdrCoverTestSupported && videoTestBin && (() => {
  try {
    const help = execFileSync(`${videoTestBin}/ffmpeg`, ["-hide_banner", "-h", "encoder=libx265"], { encoding: "utf8" });
    return help.includes("-dolbyvision");
  } catch {
    return false;
  }
})();

test.skipIf(!dolbyVisionEditSupported).each([
  { profile: "8.1", compatibility: 1, transfer: "smpte2084" },
  { profile: "8.4", compatibility: 4, transfer: "arib-std-b67" },
])("retains Dolby Vision $profile during original sends, covers and trimmed sends", async ({ profile, compatibility, transfer }) => {
  const directory = await mkdtemp(join(tmpdir(), "makosh-dolby-vision-"));
  // These clips are generated gray frames with synthetic Dolby Vision metadata.
  const bytes = await readFile(new URL(`./fixtures/dolby-vision/profile-${profile}.mp4`, import.meta.url));
  let trimming = false;
  let probeFailure: unknown;
  const probe = (file: string, entries: string) => JSON.parse(execFileSync(`${videoTestBin}/ffprobe`,
    ["-v", "error", "-select_streams", "v:0", "-read_intervals", "%+1", "-show_entries", entries,
      "-of", "json", file], { encoding: "utf8" }));
  const { session, request } = harness((query) => {
    switch (query["@type"]) {
      case "getAuthorizationState": return { "@type": "authorizationStateReady" };
      case "getChat": return { "@type": "chat", id: 42, type: { "@type": "chatTypePrivate", user_id: 42 } };
      case "getOption": return { "@type": "optionValueString", value: "1.8.99" };
      case "sendMessage": {
        try {
          const content = query.input_message_content as TdObject;
          const video = content.video as TdObject;
          const file = String((video.video as TdObject).path);
          if (!trimming) expect(readFileSync(file)).toEqual(bytes);
          const info = probe(file, "stream=codec_name,pix_fmt,width,height,color_transfer:stream_side_data=side_data_type,dv_profile,dv_bl_signal_compatibility_id,rpu_present_flag,el_present_flag:frame_side_data=side_data_type:format=duration");
          expect(info.streams[0]).toMatchObject({ codec_name: "hevc", width: 64, height: 64, pix_fmt: "yuv420p10le", color_transfer: transfer });
          expect(info.streams[0].side_data_list).toContainEqual(expect.objectContaining({ dv_profile: 8,
            dv_bl_signal_compatibility_id: compatibility, rpu_present_flag: 1, el_present_flag: 0 }));
          expect(info.frames.length).toBeGreaterThan(0);
          for (const frame of info.frames) {
            expect(frame.side_data_list).toContainEqual(expect.objectContaining({ side_data_type: "Dolby Vision RPU Data" }));
          }
          expect(Number(info.format.duration)).toBeCloseTo(trimming ? 0.5 : 0.75, 1);
          const cover = String((video.cover as TdObject).path);
          expect(probe(cover, "stream=codec_name,pix_fmt").streams[0])
            .toMatchObject({ codec_name: "mjpeg", pix_fmt: "yuvj420p" });
        } catch (error) {
          probeFailure = error;
        }
        return { "@type": "message", id: 7, chat_id: 42, is_outgoing: true, content: { "@type": "messageVideo" } };
      }
      default: throw new Error("Unexpected fixture query");
    }
  }, undefined, directory);
  try {
    await vi.waitFor(() => expect(session.status().state).toBe("ready"));
    const blob = new Blob([new Uint8Array(bytes)]);
    const send = (quality: "original" | "720") => session.sendDocumentStream("42", "fixture.mp4", "", blob.size, blob.stream(),
      () => true, undefined, undefined, true, { videoEdit: quality === "original"
        ? { startMs: 0, endMs: 750, quality, coverMs: 250 }
        : { startMs: 250, endMs: 750, quality, coverMs: 500 } });
    await expect(send("original")).resolves.toMatchObject({ state: "sent" });
    if (probeFailure) throw probeFailure;
    trimming = true;
    await expect(send("720")).resolves.toMatchObject({ state: "sent" });
    if (probeFailure) throw probeFailure;
    expect(request.mock.calls.filter(([query]) => query["@type"] === "sendMessage")).toHaveLength(2);
  } finally {
    await session.close();
    await rm(directory, { recursive: true, force: true });
  }
});

const doviValidationTool = process.env.MAKOSH_TELEGRAM_TEST_DOVI_TOOL ?? findDolbyVisionTool();

test.skipIf(!dolbyVisionEditSupported || !doviValidationTool).each([
  { profile: "8.1", compatibility: 1, transfer: "smpte2084" },
  { profile: "8.4", compatibility: 4, transfer: "arib-std-b67" },
])("resizes full-frame and scene-specific active areas for Dolby Vision $profile", async ({ profile, compatibility, transfer }) => {
  const directory = await mkdtemp(join(tmpdir(), "makosh-dolby-resize-"));
  const ffmpeg = `${videoTestBin}/ffmpeg`;
  const tool = doviValidationTool!;
  const scale = (args: string[]) => execFileSync(ffmpeg, ["-nostdin", "-v", "error", ...args]);
  const encoder = ["-c:v", "libx265", "-preset", "ultrafast", "-pix_fmt", "yuv420p10le",
    "-tag:v", "hvc1", "-bf", "0", "-b:v", "1500k", "-maxrate", "1500k", "-bufsize", "3000k", "-x265-params",
    `log-level=error:pools=1:colorprim=bt2020:transfer=${transfer}:colormatrix=bt2020nc:range=limited`,
    "-dolbyvision", "1", "-strict", "unofficial"];
  const large = join(directory, "large.mp4");
  const letterbox = join(directory, "letterbox.mp4");
  const rawVideo = join(directory, "large.hevc");
  const rawRpu = join(directory, "source.rpu");
  const editedRpu = join(directory, "letterbox.rpu");
  const editedRaw = join(directory, "letterbox.hevc");
  const config = join(directory, "offsets.json");
  let sentInfo: unknown;
  let sentAudio: unknown;
  let sentArea: { presets: { id: number; left: number; right: number; top: number; bottom: number }[];
    edits: Record<string, number> } | undefined;
  const { session, request } = harness((query) => {
    switch (query["@type"]) {
      case "getAuthorizationState": return { "@type": "authorizationStateReady" };
      case "getChat": return { "@type": "chat", id: 42, type: { "@type": "chatTypePrivate", user_id: 42 } };
      case "getOption": return { "@type": "optionValueString", value: "1.8.99" };
      case "sendMessage": {
        const video = (query.input_message_content as TdObject).video as TdObject;
        const path = String((video.video as TdObject).path);
        sentInfo = JSON.parse(execFileSync(`${videoTestBin}/ffprobe`, ["-v", "error", "-select_streams", "v:0",
          "-show_entries", "stream=codec_name,width,height,pix_fmt,color_transfer:stream_side_data=dv_profile,dv_bl_signal_compatibility_id:frame_side_data=side_data_type",
          "-of", "json", path], { encoding: "utf8" }));
        sentAudio = JSON.parse(execFileSync(`${videoTestBin}/ffprobe`, ["-v", "error", "-select_streams", "a:0",
          "-show_entries", "stream=codec_name,start_time,duration", "-of", "json", path], { encoding: "utf8" }));
        const rendered = join(directory, "sent.hevc");
        const metadata = join(directory, "sent.rpu");
        const area = join(directory, "sent-area.json");
        scale(["-y", "-i", path, "-c:v", "copy", "-map", "0:v:0", "-bsf:v", "hevc_mp4toannexb", "-f", "hevc", rendered]);
        execFileSync(tool, ["extract-rpu", rendered, "-o", metadata]);
        execFileSync(tool, ["export", metadata, "-d", `level5=${area}`]);
        sentArea = JSON.parse(readFileSync(area, "utf8"));
        return { "@type": "message", id: 7, chat_id: 42, is_outgoing: true, content: { "@type": "messageVideo" } };
      }
      default: throw new Error("Unexpected fixture query");
    }
  }, undefined, { directory, dolbyVisionTool: tool });
  try {
    const fixture = new URL(`./fixtures/dolby-vision/profile-${profile}.mp4`, import.meta.url);
    const input = join(directory, "fixture.mp4");
    await writeFile(input, await readFile(fixture));
    scale(["-i", input, "-vf", "scale=800:800", ...encoder, large]);
    scale(["-i", large, "-c:v", "copy", "-bsf:v", "hevc_mp4toannexb", "-f", "hevc", rawVideo]);
    execFileSync(tool, ["extract-rpu", rawVideo, "-o", rawRpu]);
    await writeFile(config, JSON.stringify({ active_area: {
      presets: [{ id: 0, left: 10, right: 30, top: 20, bottom: 40 },
        { id: 1, left: 50, right: 0, top: 0, bottom: 60 }],
      edits: { "0-2": 0, "3-8": 1 },
    } }));
    execFileSync(tool, ["editor", rawRpu, "-j", config, "-o", editedRpu]);
    execFileSync(tool, ["inject-rpu", "-i", rawVideo, "--rpu-in", editedRpu, "-o", editedRaw]);
    // Re-encode the injected HEVC so the MP4 muxer writes the Dolby Vision configuration record.
    scale(["-r", "12", "-i", editedRaw, "-f", "lavfi", "-i", "sine=frequency=440:duration=0.75",
      "-map", "0:v:0", "-map", "1:a:0", ...encoder, "-c:a", "aac", letterbox]);
    const configs = JSON.parse(execFileSync(`${videoTestBin}/ffprobe`, ["-v", "error", "-select_streams", "v:0",
      "-show_entries", "stream_side_data=dv_profile,dv_bl_signal_compatibility_id", "-of", "json", letterbox],
    { encoding: "utf8" }));
    expect(configs.streams[0].side_data_list).toContainEqual(expect.objectContaining({
      dv_profile: 8, dv_bl_signal_compatibility_id: compatibility,
    }));
    await expect(inspectDolbyVisionArea(ffmpeg, tool, large, 0, { width: 800, height: 800 })).resolves.toMatchObject({ fullFrame: true });
    await expect(inspectDolbyVisionArea(ffmpeg, tool, letterbox, 0, { width: 800, height: 800 })).resolves.toMatchObject({ fullFrame: false });
    await vi.waitFor(() => expect(session.status().state).toBe("ready"));
    const send = async (source: string) => {
      const blob = new Blob([new Uint8Array(await readFile(source))]);
      return session.sendDocumentStream("42", "fixture.mp4", "", blob.size, blob.stream(),
        () => true, undefined, undefined, true, { videoEdit: { startMs: 0, endMs: 500, quality: "480" } });
    };
    await expect(send(large)).resolves.toMatchObject({ state: "sent" });
    expect(sentInfo).toMatchObject({ streams: [{ codec_name: "hevc", width: 480, height: 480, pix_fmt: "yuv420p10le",
      color_transfer: transfer, side_data_list: expect.arrayContaining([
        expect.objectContaining({ dv_profile: 8, dv_bl_signal_compatibility_id: compatibility }),
      ]) }] });
    const frames = (sentInfo as { frames: { side_data_list: unknown[] }[] }).frames;
    expect(frames.length).toBeGreaterThan(0);
    expect(frames.every((frame) => frame.side_data_list.some((entry) =>
      (entry as { side_data_type?: string }).side_data_type === "Dolby Vision RPU Data"))).toBe(true);
    await expect(send(letterbox)).resolves.toMatchObject({ state: "sent" });
    expect(sentInfo).toMatchObject({ streams: [{ width: 480, height: 480, pix_fmt: "yuv420p10le",
      color_transfer: transfer, side_data_list: expect.arrayContaining([
        expect.objectContaining({ dv_profile: 8, dv_bl_signal_compatibility_id: compatibility }),
      ]) }] });
    expect(sentAudio).toMatchObject({ streams: [{ codec_name: "aac", start_time: "0.000000" }] });
    const audioDuration = Number((sentAudio as { streams: { duration: string }[] }).streams[0]?.duration);
    expect(Math.abs(audioDuration - 0.5)).toBeLessThan(1024 / 44100);
    expect(sentArea).toMatchObject({ presets: [
      { id: 0, left: 6, right: 18, top: 12, bottom: 24 },
      { id: 1, left: 30, right: 0, top: 0, bottom: 36 },
    ], edits: { "0-2": 0, "3-5": 1 } });
    await expect(inspectDolbyVisionArea(ffmpeg, tool, letterbox, 0, { width: 800, height: 20 }))
      .rejects.toThrow("Dolby Vision active area is outside the frame.");
    const rotated = join(directory, "rotated.mp4");
    scale(["-display_rotation", "90", "-i", letterbox, "-map", "0", "-c", "copy", "-strict", "unofficial", rotated]);
    await expect(send(rotated)).resolves.toMatchObject({ state: "failed", uploadRejection: "video_preparation_failed" });
    expect(request.mock.calls.filter(([query]) => query["@type"] === "sendMessage")).toHaveLength(2);
  } finally {
    await session.close();
    await rm(directory, { recursive: true, force: true });
  }
}, 15_000);

const hdr10PlusFixtureTool = process.env.MAKOSH_TELEGRAM_TEST_HDR10_PLUS_TOOL ?? findHdr10PlusTool();

test.skipIf(!hdrCoverTestSupported || !hdr10PlusFixtureTool).each(["constant", "variable"])(
  "trims and resizes %s-rate HDR10+ with matching frame timing, metadata and audio", async (rate) => {
  const variable = rate === "variable";
  const directory = await mkdtemp(join(tmpdir(), "makosh-hdr10plus-"));
  const file = (name: string) => join(directory, name);
  const ffmpeg = (args: string[]) => execFileSync(`${videoTestBin}/ffmpeg`, ["-nostdin", "-v", "error", ...args]);
  const sceneInfo = Array.from({ length: 24 }, (_, index) => ({
    NumberOfWindows: 1, SceneId: index, SceneFrameIndex: 0, SequenceFrameIndex: index,
    TargetedSystemDisplayMaximumLuminance: 0,
    LuminanceParameters: { AverageRGB: 400 + index * 100, MaxScl: [1000 + index * 200, 2000, 3000],
      LuminanceDistributions: { DistributionIndex: [1, 5, 10, 25, 50, 75, 90, 95, 99],
        DistributionValues: [5, 10, 20, 30, 40, 50, 60, 70, 80] } },
  }));
  let sent: { streams: unknown[]; frames: {
    media_type?: string; best_effort_timestamp_time?: string; duration_time?: string;
    side_data_list?: { average_maxrgb?: string }[];
  }[] } | undefined;
  const { session, request } = harness((query) => {
    switch (query["@type"]) {
      case "getAuthorizationState": return { "@type": "authorizationStateReady" };
      case "getChat": return { "@type": "chat", id: 42, type: { "@type": "chatTypePrivate", user_id: 42 } };
      case "getOption": return { "@type": "optionValueString", value: "1.8.99" };
      case "sendMessage": {
        const clip = (query.input_message_content as TdObject).video as TdObject;
        sent = JSON.parse(execFileSync(`${videoTestBin}/ffprobe`, ["-v", "error", "-show_entries",
          "stream=codec_name,width,height,duration,start_time,color_transfer:frame=media_type,best_effort_timestamp_time,duration_time:frame_side_data=average_maxrgb", "-of", "json",
          String((clip.video as TdObject).path)], { encoding: "utf8" }));
        return { "@type": "message", id: 7, chat_id: 42, is_outgoing: true, content: { "@type": "messageVideo" } };
      }
      default: throw new Error("Unexpected HDR10+ fixture request.");
    }
  }, undefined, { directory, hdr10PlusTool: file("tool") });
  try {
    await writeFile(file("metadata.json"), JSON.stringify({
      JSONInfo: { HDR10plusProfile: "A", Version: "1.0" }, SceneInfo: sceneInfo,
      SceneInfoSummary: { SceneFirstFrameIndex: sceneInfo.map(({ SceneId }) => SceneId), SceneFrameNumbers: sceneInfo.map(() => 1) },
      ToolInfo: { Tool: "synthetic fixture", Version: "1.0" },
    }));
    ffmpeg(["-f", "lavfi", "-i", "testsrc2=s=800x450:r=12:d=2", "-c:v", "libx265", "-pix_fmt", "yuv420p10le",
      "-x265-params", "log-level=error:pools=1:bframes=0:colorprim=bt2020:transfer=smpte2084:colormatrix=bt2020nc",
      "-f", "hevc", file("plain.hevc")]);
    execFileSync(hdr10PlusFixtureTool!, ["inject", "-i", file("plain.hevc"), "-j", file("metadata.json"), "-o", file("source.hevc")]);
    const variableClock = ["-bsf:v", "setts=time_base=1/1000000:ts='floor(N/3)*250000+if(eq(mod(N,3),0),0,if(eq(mod(N,3),1),70000,155000))'"
      + ":duration='if(eq(mod(N,3),0),70000,if(eq(mod(N,3),1),85000,95000))'", "-video_track_timescale", "1000000"];
    ffmpeg(["-r", variable ? "1000000" : "12", "-i", file("source.hevc"), "-f", "lavfi", "-i", "sine=frequency=440:duration=2",
      "-map", "0:v", "-map", "1:a", "-c:v", "copy", "-tag:v", "hvc1", "-c:a", "aac",
      ...(variable ? variableClock : []), file("source.mp4")]);
    await symlink(hdr10PlusFixtureTool!, file("tool"));
    await vi.waitFor(() => expect(session.status().state).toBe("ready"));
    const blob = new Blob([new Uint8Array(await readFile(file("source.mp4")))]);
    const send = () => session.sendDocumentStream("42", "source.mp4", "", blob.size, blob.stream(),
      () => true, undefined, undefined, true, { videoEdit: { startMs: 240, endMs: variable ? 2000 : 1250, quality: "480" } });
    await expect(send()).resolves.toMatchObject({ state: "sent" });
    expect(sent?.streams).toEqual([
      expect.objectContaining({ codec_name: "hevc", width: 480, height: 270, start_time: "0.000000", color_transfer: "smpte2084", duration: variable ? "1.750000" : "1.000000" }),
      expect.objectContaining({ codec_name: "aac", start_time: "0.000000", duration: variable ? "1.750000" : "1.000000" }),
    ]);
    expect(sent?.frames.flatMap(({ side_data_list }) => side_data_list?.flatMap(({ average_maxrgb }) => average_maxrgb ?? []) ?? []))
      .toEqual(sceneInfo.slice(3, variable ? 24 : 15).map((frame) => `${frame.LuminanceParameters.AverageRGB}/100000`));
    if (variable) {
      const videoFrames = sent?.frames.filter(({ media_type }) => media_type === "video");
      expect(videoFrames?.map(({ best_effort_timestamp_time }) => Number(best_effort_timestamp_time)))
        .toEqual(Array.from({ length: 21 }, (_, i) => (Math.floor(i / 3) * 250 + [0, 70, 155][i % 3]!) / 1000));
      expect(videoFrames?.map(({ duration_time }) => Number(duration_time)))
        .toEqual(Array.from({ length: 21 }, (_, i) => [0.070, 0.085, 0.095][i % 3]));
    }
    await rm(file("tool"));
    await expect(send()).resolves.toMatchObject({ state: "failed", uploadRejection: "video_preparation_failed" });
    expect(request.mock.calls.filter(([query]) => query["@type"] === "sendMessage")).toHaveLength(1);
  } finally {
    await session.close();
    await rm(directory, { recursive: true, force: true });
  }
}, 30_000);

test.skipIf(!videoTestBin)("uses the default video track for both an edit and its cover", async () => {
  const directory = await mkdtemp(join(tmpdir(), "makosh-multiple-video-tracks-"));
  const name = "fixture.mp4";
  const clip = join(directory, name);
  let original = true;
  let source: Buffer;
  const { session, request } = harness((query) => {
    switch (query["@type"]) {
      case "getAuthorizationState": return { "@type": "authorizationStateReady" };
      case "getChat": return { "@type": "chat", id: 42, type: { "@type": "chatTypePrivate", user_id: 42 } };
      case "getOption": return { "@type": "optionValueString", value: "1.8.99" };
      case "sendMessage": {
        const media = (query.input_message_content as TdObject).video as TdObject;
        expect(media).toMatchObject({ width: 160, height: 96, duration: original ? 2 : 1 });
        const video = String((media.video as TdObject).path);
        if (original) expect(readFileSync(video)).toEqual(source);
        const cover = String((media.cover as TdObject).path);
        const pixels = execFileSync(`${videoTestBin}/ffmpeg`, ["-v", "error", "-i", cover, "-frames:v", "1",
          "-vf", "scale=1:1,format=rgb24", "-f", "rawvideo", "pipe:1"]);
        expect(pixels[2]).toBeGreaterThan(pixels[0]! + 180);
        return { "@type": "message", id: 7, chat_id: 42, is_outgoing: true, content: { "@type": "messageVideo" } };
      }
      default: throw new Error("Unexpected fixture query");
    }
  }, undefined, directory);
  try {
    execFileSync(`${videoTestBin}/ffmpeg`, ["-v", "error",
      "-f", "lavfi", "-i", "color=red:s=320x180:r=20:d=2", "-f", "lavfi", "-i", "color=blue:s=160x96:r=20:d=2",
      "-map", "0:v:0", "-map", "1:v:0", "-disposition:v:0", "0", "-disposition:v:1", "default",
      "-c:v", "libx264", "-pix_fmt", "yuv420p", clip]);
    source = await readFile(clip);
    await vi.waitFor(() => expect(session.status().state).toBe("ready"));
    const blob = new Blob([new Uint8Array(source)]);
    const send = (videoEdit: import("../src/core/contract.ts").VideoEdit) =>
      session.sendDocumentStream("42", name, "", blob.size, blob.stream(), () => true, undefined, undefined, true, { videoEdit });
    await expect(send({ quality: "original", startMs: 0, endMs: 2000, coverMs: 500 })).resolves.toMatchObject({ state: "sent" });
    original = false;
    await expect(send({ quality: "480", startMs: 250, endMs: 1250, coverMs: 500 })).resolves.toMatchObject({ state: "sent" });
    expect(request.mock.calls.filter(([query]) => query["@type"] === "sendMessage")).toHaveLength(2);
  } finally {
    await session.close();
    await rm(directory, { recursive: true, force: true });
  }
});

test("validates single-video upload edits", () => {
  const schema = schemas.prepareDocumentUpload.input;
  const input = { id: "42", name: "fixture.mp4", size: 123, caption: "", video: true,
    options: { videoEdit: { quality: "720", startMs: 0, endMs: 1000, coverMs: 500 } } };
  expect(schema.safeParse(input).success).toBe(true);
  expect(schema.safeParse({ ...input, video: undefined }).success).toBe(false);
  expect(schema.safeParse({ ...input, options: { ...input.options, originalVideo: true } }).success).toBe(false);
  expect(schema.safeParse({ ...input, options: { videoEdit: { ...input.options.videoEdit, coverMs: 1000 } } }).success).toBe(false);
});

test("keeps local video edits attached to their album item or formatted block", () => {
  const videoEdit = { startMs: 250, endMs: 1500, quality: "480", coverMs: 500 };
  const edited = { kind: "video", name: "edited.mp4", size: 123, videoEdit };
  const original = { kind: "video", name: "original.mp4", size: 456 };
  const album = { id: "42", caption: "", items: [original, edited], options: { originalVideo: true } };
  const prepareAlbum = schemas.prepareAlbumUpload.input;
  expect(prepareAlbum.parse(album).items).toEqual([original, edited]);
  expect(prepareAlbum.safeParse({ ...album, options: { paidStars: 1 } }).success).toBe(false);
  expect(prepareAlbum.safeParse({ ...album, items: [original, { ...edited,
    videoEdit: { ...videoEdit, endMs: 300 } }] }).success).toBe(false);

  const block = { ...edited, caption: "Fixture clip", spoiler: true };
  const prepareRich = schemas.prepareRichMessageUpload.input;
  expect(prepareRich.parse({ id: "42", draft: [block] }).draft).toEqual([block]);
  expect(prepareRich.safeParse({ id: "42", draft: [{ ...block, kind: "document" }] }).success).toBe(false);
});

test.skipIf(!videoTestBin).each([
  ["mp4", "libx265", false],
  ["mov", "libx264", true],
] as const)("preserves original %s video and audio streams", async (extension, encoder, streaming) => {
  const directory = await mkdtemp(join(tmpdir(), "makosh-original-video-"));
  const name = `fixture.${extension}`;
  const clip = join(directory, name);
  let stagedBytes: Buffer | undefined;
  let stagedStreams: string | undefined;
  const hash = (path: string) => execFileSync(`${videoTestBin}/ffmpeg`, [
    "-v", "error", "-i", path, "-map", "0:v:0", "-map", "0:a:0", "-c", "copy", "-f", "streamhash", "-hash", "sha256", "pipe:1",
  ], { encoding: "utf8" });
  const { session, request } = harness((query) => {
    switch (query["@type"]) {
      case "getAuthorizationState": return { "@type": "authorizationStateReady" };
      case "getChat": return { "@type": "chat", id: 42, type: { "@type": "chatTypePrivate", user_id: 42 } };
      case "getOption": return { "@type": "optionValueString", value: "1.8.99" };
      case "sendMessage": {
        const media = (query.input_message_content as TdObject).video as TdObject;
        expect(media.supports_streaming).toBe(streaming);
        const path = String((media.video as TdObject).path);
        expect(path).toMatch(extension === "mov" ? /telegram-video\.mp4$/ : /fixture\.mp4$/);
        stagedBytes = readFileSync(path);
        stagedStreams = hash(path);
        return { "@type": "message", id: 7, chat_id: 42, is_outgoing: true, content: { "@type": "messageVideo" } };
      }
      default: throw new Error("Unexpected fixture query");
    }
  }, undefined, directory);
  try {
    execFileSync(`${videoTestBin}/ffmpeg`, ["-v", "error",
      "-f", "lavfi", "-i", "color=blue:s=160x90:r=15", "-f", "lavfi", "-i", "sine=frequency=440:sample_rate=48000",
      "-t", "0.5", "-c:v", encoder, ...(encoder === "libx265" ? ["-x265-params", "log-level=error:pools=1"] : []), "-c:a", "aac", clip]);
    await vi.waitFor(() => expect(session.status().state).toBe("ready"));
    const send = (file: Buffer) => session.sendDocumentStream("42", name, "Fixture caption", file.length,
      new ReadableStream<Uint8Array>({ start(controller) { controller.enqueue(file); controller.close(); } }),
      () => true, undefined, undefined, true, { originalVideo: true });
    const bytes = await readFile(clip);
    await expect(send(bytes)).resolves.toMatchObject({ state: "sent" });
    expect(stagedStreams).toBe(hash(clip));
    if (extension === "mp4") expect(stagedBytes).toEqual(bytes);
    if (extension === "mov") {
      const incompatible = join(directory, "fixture-pcm.mov");
      execFileSync(`${videoTestBin}/ffmpeg`, ["-v", "error", "-i", clip, "-c:v", "copy", "-c:a", "pcm_s16le", incompatible]);
      await expect(send(await readFile(incompatible))).resolves.toEqual({ state: "failed", uploadRejection: "video_preparation_failed" });
    }
    expect(request.mock.calls.filter(([query]) => query["@type"] === "sendMessage")).toHaveLength(1);
  } finally {
    await session.close();
    await rm(directory, { recursive: true, force: true });
  }
});

