test("reads channel Stars income only when Telegram allows it", async () => {
  let allowed = false;
  const { session, request } = harness((query) => {
    switch (query["@type"]) {
      case "getAuthorizationState": return { "@type": "authorizationStateReady" };
      case "getChat": return { "@type": "chat", id: -42, title: "Fixture channel",
        type: { "@type": "chatTypeSupergroup", supergroup_id: 42, is_channel: true } };
      case "getSupergroupFullInfo": return { "@type": "supergroupFullInfo", can_get_star_revenue_statistics: allowed };
      case "getStarRevenueStatistics": {
        const amount = (star_count: number) => ({ "@type": "starAmount", star_count, nanostar_count: 0 });
        return { "@type": "starRevenueStatistics", revenue_by_day_graph: { "@type": "statisticalGraphAsync", token: "fixture-graph" },
          status: { "@type": "starRevenueStatus", total_amount: amount(40),
          current_amount: amount(14), available_amount: amount(7), withdrawal_enabled: true, next_withdrawal_in: 86400 } };
      }
      case "getStatisticalGraph": return { "@type": "statisticalGraphData", json_data: JSON.stringify({
        columns: [["x", 1800000000000, 1800086400000], ["y", 6, -2], ["invalid", 99]],
        types: { x: "x", y: "bar", invalid: "bar" }, names: { y: "Fixture revenue" },
      }) };
      case "getStarTransactions": return { "@type": "starTransactions", next_offset: "next",
        star_amount: { "@type": "starAmount", star_count: 14, nanostar_count: 5 }, transactions: [{
          "@type": "starTransaction", id: "income", date: 1800000000, is_refund: false,
          star_amount: { "@type": "starAmount", star_count: 7, nanostar_count: 0 },
          type: { "@type": "starTransactionTypeChannelPaidReactionReceive", message_id: 1048576 },
        }] };
      default: throw new Error("Unexpected fixture query");
    }
  });
  await vi.waitFor(() => expect(session.status().state).toBe("ready"));
  await expect(session.starTransactions("", "incoming", "", "-42")).resolves.toBeNull();
  await expect(session.channelStarRevenue("-42")).resolves.toBeNull();
  expect(request.mock.calls.some(([query]) => query["@type"] === "getStarTransactions")).toBe(false);
  expect(request.mock.calls.some(([query]) => query["@type"] === "getStarRevenueStatistics")).toBe(false);
  allowed = true;
  await expect(session.starTransactions("", "incoming", "", "-42")).resolves.toEqual({
    next: "next", balance: { stars: 14, nanostars: 5 }, transactions: [{
      id: "income", date: 1800000000, refund: false, label: "Paid reaction income", amount: { stars: 7, nanostars: 0 },
      source: { id: "-42", messageId: "1048576" },
    }],
  });
  expect(request).toHaveBeenLastCalledWith({ "@type": "getStarTransactions", owner_id: { "@type": "messageSenderChat", chat_id: -42 },
    direction: { "@type": "transactionDirectionIncoming" }, subscription_id: "", offset: "", limit: 30 });
  await expect(session.channelStarRevenue("-42")).resolves.toEqual({ total: { stars: 40, nanostars: 0 },
    current: { stars: 14, nanostars: 0 }, available: { stars: 7, nanostars: 0 }, withdrawalEnabled: true, nextWithdrawalIn: 86400,
    daily: [{ name: "Fixture revenue", points: [{ date: 1800000000000, stars: 6 }, { date: 1800086400000, stars: -2 }] }] });
  expect(request).toHaveBeenCalledWith({ "@type": "getStarRevenueStatistics", owner_id: { "@type": "messageSenderChat", chat_id: -42 }, is_dark: false });
  expect(request).toHaveBeenLastCalledWith({ "@type": "getStatisticalGraph", chat_id: -42, token: "fixture-graph", x: 0 });
});

test("publishes an eligible channel's paid album as one priced message", async () => {
  const directory = await mkdtemp(join(tmpdir(), "makosh-paid-album-"));
  const jpeg = Buffer.from([0xff, 0xd8, 0xff, 0xc0, 0, 8, 8, 0, 1, 0, 1, 1, 0xff, 0xd9]).toString("base64");
  let allowed = false;
  const { session, request } = harness((query) => {
    switch (query["@type"]) {
      case "getAuthorizationState": return { "@type": "authorizationStateReady" };
      case "getChat": return { "@type": "chat", id: -42, type: { "@type": "chatTypeSupergroup", supergroup_id: 42, is_channel: true } };
      case "getSupergroup": return { "@type": "supergroup", id: 42, is_channel: true, status: { "@type": "chatMemberStatusCreator", is_member: true } };
      case "getSupergroupFullInfo": return { "@type": "supergroupFullInfo", has_paid_media_allowed: allowed };
      case "getOption": return { "@type": "optionValueInteger", value: "100" };
      case "sendMessage": return { "@type": "message", id: 7, chat_id: -42 };
      default: throw new Error("Unexpected fixture query");
    }
  }, undefined, directory);
  try {
    await vi.waitFor(() => expect(session.status().state).toBe("ready"));
    const publish = (paidStars: number) => session.sendPhotoAlbum("-42", "Paid fixture", [jpeg, jpeg], undefined, undefined,
      undefined, { paidStars, captionAbove: true });
    await expect(publish(42)).resolves.toBe("failed");
    allowed = true;
    await expect(publish(101)).resolves.toBe("failed");
    expect(request.mock.calls.some(([query]) => query["@type"] === "sendMessage")).toBe(false);
    await expect(publish(42)).resolves.toBe("sent");
    expect(request.mock.calls.filter(([query]) => query["@type"] === "sendMessage")).toEqual([[expect.objectContaining({
      chat_id: -42, input_message_content: {
        "@type": "inputMessagePaidMedia", star_count: 42, caption: { "@type": "formattedText", text: "Paid fixture", entities: [] },
        show_caption_above_media: true, payload: "", paid_media: Array.from({ length: 2 }, () => expect.objectContaining({
          "@type": "inputPaidMedia", type: { "@type": "inputPaidMediaTypePhoto", video: null },
          media: { "@type": "inputFileLocal", path: expect.any(String) },
        })),
      },
    })]]);
    await expect(session.sendPhotoAlbum("-42", "", [jpeg])).resolves.toBe("failed");
    await expect(session.sendPhotoAlbum("-42", "", [jpeg], undefined, undefined, undefined, { paidStars: 42 })).resolves.toBe("sent");
    expect(request).toHaveBeenLastCalledWith(expect.objectContaining({ input_message_content: expect.objectContaining({
      "@type": "inputMessagePaidMedia", paid_media: [expect.objectContaining({ "@type": "inputPaidMedia" })],
    }) }));
    const singleVideo = { id: "-42", caption: "", items: [{ kind: "video", name: "fixture.mp4", size: 12 }] };
    expect(schemas.prepareAlbumUpload.input.safeParse(singleVideo).success).toBe(false);
    expect(schemas.prepareAlbumUpload.input.safeParse({ ...singleVideo, options: { paidStars: 42 } }).success).toBe(true);
    expect(schemas.prepareQuickReplyAlbumUpload.input.safeParse({ ...singleVideo, id: undefined, name: "fixture" }).success).toBe(false);
  } finally {
    await session.close();
    await rm(directory, { recursive: true, force: true });
  }
});

test("sends all photos in one album under spoilers with one caption", async () => {
  const directory = await mkdtemp(join(tmpdir(), "makosh-album-"));
  const jpeg = Buffer.from([0xff, 0xd8, 0xff, 0xc0, 0, 8, 8, 0, 1, 0, 1, 1, 0xff, 0xd9]).toString("base64");
  let secondAlbumId = "99";
  let secondMessageId = 8;
  let price = 4;
  const effect = "9007199254740997";
  let confirmedEffect: string | undefined = effect;
  const { session, request } = harness((query) => {
    switch (query["@type"]) {
      case "getAuthorizationState": return { "@type": "authorizationStateReady" };
      case "getChat": return { "@type": "chat", id: 42, type: { "@type": "chatTypePrivate", user_id: 42 } };
      case "getOption": return { "@type": "optionValueString", value: "1.8.99" };
      case "getMe": return { "@type": "user", id: 7, is_premium: false };
      case "getUser": return { "@type": "user", id: 42, type: { "@type": "userTypeRegular" },
        status: { "@type": "userStatusOffline", was_online: 1700000000 } };
      case "getCurrentState": return { "@type": "updates", updates: [{ "@type": "updateAvailableMessageEffects", reaction_effect_ids: [effect] }] };
      case "getMessageEffect": return { "@type": "messageEffect", id: query.effect_id, emoji: "🔥", is_premium: false,
        type: { "@type": "messageEffectTypeEmojiReaction" } };
      case "canSendMessageToUser":
        return { "@type": "canSendMessageToUserResultUserHasPaidMessages", outgoing_paid_message_star_count: price };
      case "sendMessageAlbum": return { "@type": "messages", messages: [7, secondMessageId].map((id, index) => ({
        "@type": "message", id, chat_id: 42, media_album_id: index ? secondAlbumId : "99",
        scheduling_state: (query.options as TdObject | undefined)?.scheduling_state,
        ...(index === 0 && (query.options as TdObject | undefined)?.effect_id !== undefined && { effect_id: confirmedEffect }),
      })) };
      default: throw new Error("Unexpected fixture query");
    }
  }, undefined, directory);
  try {
    await vi.waitFor(() => expect(session.status().state).toBe("ready"));
    await expect(session.sendPhotoAlbum("42", "Album fixture", [jpeg, jpeg],
      undefined, undefined, undefined, { spoiler: true, captionAbove: true })).resolves.toBe("sent");
    const calls = request.mock.calls.filter(([query]) => query["@type"] === "sendMessageAlbum");
    expect(calls).toHaveLength(1);
    const photos = calls[0]![0].input_message_contents as TdObject[];
    expect(photos).toHaveLength(2);
    expect(photos[0]).toMatchObject({
      "@type": "inputMessagePhoto", has_spoiler: true, show_caption_above_media: true, caption: { text: "Album fixture" },
    });
    expect(photos[1]).toMatchObject({
      "@type": "inputMessagePhoto", has_spoiler: true, show_caption_above_media: true, caption: { text: "" },
    });
    const paid = () => session.sendPhotoAlbum("42", "", [jpeg, jpeg], undefined, undefined, { paidStars: 4, silent: true });
    price = 5;
    await expect(paid()).resolves.toBe("failed");
    expect(request.mock.calls.filter(([query]) => query["@type"] === "sendMessageAlbum")).toHaveLength(1);
    price = 4;
    await expect(paid()).resolves.toBe("sent");
    expect(request).toHaveBeenLastCalledWith(expect.objectContaining({
      "@type": "sendMessageAlbum", chat_id: 42,
      options: { "@type": "messageSendOptions", disable_notification: true, paid_message_star_count: 8 },
    }));
    await expect(session.sendPhotoAlbum("42", "", [jpeg, jpeg], undefined, undefined, undefined,
      { itemCaptions: ["Incomplete"] })).resolves.toBe("failed");
    await expect(session.sendPhotoAlbum("42", "Shared", [jpeg, jpeg], undefined, undefined, undefined,
      { itemCaptions: ["First", "Second"] })).resolves.toBe("failed");
    await expect(session.sendPhotoAlbum("42", "", [jpeg, jpeg], undefined, undefined, undefined,
      { itemCaptions: ["First", { text: "Second", format: { links: [{ offset: 0, length: 6, url: "javascript:alert(1)" }] } }] }))
      .resolves.toBe("failed");
    expect(request.mock.calls.filter(([query]) => query["@type"] === "sendMessageAlbum")).toHaveLength(2);
    await expect(session.sendPhotoAlbum("42", "", [jpeg, jpeg], undefined, undefined, undefined,
      { itemCaptions: ["First file", { text: "Second file", format: { links: [
        { offset: 0, length: 6, url: "https://example.test/album" },
      ] } }], captionAbove: true })).resolves.toBe("sent");
    expect(request).toHaveBeenLastCalledWith(expect.objectContaining({
      "@type": "sendMessageAlbum",
      input_message_contents: [
        expect.objectContaining({ caption: { "@type": "formattedText", text: "First file", entities: [] }, show_caption_above_media: true }),
        expect.objectContaining({
          caption: { "@type": "formattedText", text: "Second file", entities: [{ "@type": "textEntity", offset: 0, length: 6,
            type: { "@type": "textEntityTypeTextUrl", url: "https://example.test/album" } }] },
          show_caption_above_media: true,
        }),
      ],
    }));
    secondAlbumId = "100";
    await expect(session.sendPhotoAlbum("42", "", [jpeg, jpeg])).resolves.toBe("unknown");
    secondAlbumId = "99";
    secondMessageId = 7;
    await expect(session.sendPhotoAlbum("42", "", [jpeg, jpeg])).resolves.toBe("unknown");
    secondMessageId = 8;
    const at = Math.floor(Date.now() / 1000) + 3600;
    const input = { id: "42", caption: "Album effect", photos: [jpeg, jpeg], delivery: { effect, silent: true, at } };
    const { delivery } = schemas.sendPhotoAlbum.input.parse(input);
    expect(schemas.sendPhotoAlbum.input.safeParse({ ...input, options: { paidStars: 5 } }).success).toBe(false);
    const sendWithEffect = () => session.sendPhotoAlbum(input.id, input.caption, input.photos, undefined, undefined, delivery);
    await expect(sendWithEffect()).resolves.toBe("sent");
    expect(request).toHaveBeenLastCalledWith(expect.objectContaining({
      "@type": "sendMessageAlbum", chat_id: 42,
      options: { "@type": "messageSendOptions", disable_notification: true, effect_id: effect,
        scheduling_state: { "@type": "messageSchedulingStateSendAtDate", send_date: at } },
    }));
    confirmedEffect = undefined;
    await expect(sendWithEffect()).resolves.toBe("unknown");
    const onlineAlbum = { ...input, delivery: { whenOnline: true } };
    expect(schemas.sendPhotoAlbum.input.safeParse({ ...onlineAlbum, topic: { id: 17, name: "Fixture topic" } }).success).toBe(false);
    const online = schemas.sendPhotoAlbum.input.parse(onlineAlbum);
    await expect(session.sendPhotoAlbum(online.id, online.caption, online.photos, undefined, undefined, online.delivery)).resolves.toBe("sent");
    expect(request).toHaveBeenLastCalledWith(expect.objectContaining({
      "@type": "sendMessageAlbum", options: { "@type": "messageSendOptions", disable_notification: false,
        scheduling_state: { "@type": "messageSchedulingStateSendWhenOnline" } },
    }));
  } finally {
    await session.close();
    await rm(directory, { recursive: true, force: true });
  }
});

test("verifies the source of an external album reply before dispatch and in the delivered album", async () => {
  const directory = await mkdtemp(join(tmpdir(), "makosh-album-reply-"));
  const jpeg = Buffer.from([0xff, 0xd8, 0xff, 0xc0, 0, 8, 8, 0, 1, 0, 1, 1, 0xff, 0xd9]).toString("base64");
  let checks = 0;
  let revokeAfterPreview = true;
  let deliveredSource = 42;
  const { session, request } = harness((query) => {
    switch (query["@type"]) {
      case "getAuthorizationState": return { "@type": "authorizationStateReady" };
      case "getChat": return { "@type": "chat", id: query.chat_id, type: { "@type": "chatTypePrivate", user_id: query.chat_id } };
      case "getOption": return { "@type": "optionValueString", value: "1.8.99" };
      case "getMessage": return query.chat_id === 42 && query.message_id === 24
        ? { "@type": "message", id: 24, chat_id: 42, content: {
          "@type": "messageText", text: { "@type": "formattedText", text: "Original fixture" },
        } } : { "@type": "ok" };
      case "getMessageProperties": return { "@type": "messageProperties", can_be_replied_in_another_chat: ++checks === 1 || !revokeAfterPreview };
      case "sendMessageAlbum": return { "@type": "messages", messages: [7, 8].map((id) => ({
        "@type": "message", id, chat_id: 43, media_album_id: "99",
        reply_to: { "@type": "messageReplyToMessage", chat_id: deliveredSource, message_id: 24 },
      })) };
      default: throw new Error("Unexpected fixture query");
    }
  }, undefined, directory);
  const publish = () => session.sendPhotoAlbum("43", "", [jpeg, jpeg], undefined,
    { messageId: "24", externalReplyChatId: "42", quote: { text: "Original", position: 0 } });
  const dispatches = () => request.mock.calls.filter(([query]) => query["@type"] === "sendMessageAlbum");
  try {
    await vi.waitFor(() => expect(session.status().state).toBe("ready"));
    await expect(publish()).resolves.toBe("failed");
    expect(checks).toBe(2);
    expect(dispatches()).toHaveLength(0);
    revokeAfterPreview = false;
    await expect(publish()).resolves.toBe("sent");
    expect(dispatches()).toHaveLength(1);
    expect(dispatches()[0]?.[0]).toMatchObject({
      chat_id: 43,
      reply_to: { "@type": "inputMessageReplyToExternalMessage", chat_id: 42, message_id: 24,
        quote: { "@type": "inputTextQuote", position: 0, text: { text: "Original" } } },
    });
    deliveredSource = 43;
    await expect(publish()).resolves.toBe("unknown");
  } finally {
    await session.close();
    await rm(directory, { recursive: true, force: true });
  }
});

test.each([false, true])("dispatches a document album once with original bytes (nested TDLib: %s)", async (nested) => {
  const directory = await mkdtemp(join(tmpdir(), "makosh-document-album-"));
  const stagedBytes: string[] = [];
  const { session, request } = harness((query) => {
    switch (query["@type"]) {
      case "getAuthorizationState": return { "@type": "authorizationStateReady" };
      case "getChat": return { "@type": "chat", id: 42, type: { "@type": "chatTypePrivate", user_id: 42 } };
      case "getOption": return { "@type": "optionValueString", value: nested ? "1.8.99" : "1.8.0" };
      case "sendMessageAlbum": {
        for (const entry of query.input_message_contents as TdObject[]) {
          const media = (nested ? entry.document : entry) as TdObject;
          expect(media.disable_content_type_detection).toBe(true);
          stagedBytes.push(readFileSync(String((media.document as TdObject).path), "utf8"));
        }
        return { "@type": "messages", messages: [7, 8].map((id) => ({
          "@type": "message", id, chat_id: 42, media_album_id: "99",
        })) };
      }
      default: throw new Error("Unexpected fixture query");
    }
  }, undefined, directory);
  try {
    await vi.waitFor(() => expect(session.status().state).toBe("ready"));
    const items = [{ kind: "document", name: "report.txt", size: 5 }, { kind: "document", name: "original.mp4", size: 4 }];
    const id = "9223372036854775807";
    const input = schemas.prepareAlbumUpload.input.parse({ id: "42", caption: "Fixture ✨", items, delivery: { silent: true },
      options: { captionFormat: { customEmoji: [{ id, offset: 8, length: 1 }] } } });
    expect(schemas.prepareAlbumUpload.input.safeParse({ ...input, items: [items[0], { kind: "video", name: "clip.mp4", size: 1 }] }).success).toBe(false);
    const onDispatch = vi.fn();
    await expect(session.sendAlbumStream(input, new Blob(["alpha", "beta"]).stream(), () => true,
      { onDispatch, onPendingUpload: vi.fn(), signal: new AbortController().signal })).resolves.toMatchObject({ state: "sent" });
    expect(stagedBytes).toEqual(["alpha", "beta"]);
    expect(onDispatch).toHaveBeenCalledOnce();
    expect(request.mock.calls.filter(([query]) => query["@type"] === "sendMessageAlbum")).toEqual([[expect.objectContaining({
      chat_id: 42, options: { "@type": "messageSendOptions", disable_notification: true },
      input_message_contents: [
        expect.objectContaining({ "@type": "inputMessageDocument", caption: { "@type": "formattedText", text: "Fixture ✨", entities: [
          { "@type": "textEntity", offset: 8, length: 1, type: { "@type": "textEntityTypeCustomEmoji", custom_emoji_id: id } },
        ] } }),
        expect.objectContaining({ "@type": "inputMessageDocument", caption: { "@type": "formattedText", text: "", entities: [] } }),
      ],
    })]]);
  } finally {
    await session.close();
    await rm(directory, { recursive: true, force: true });
  }
});

test("exports the largest regular photo and denies protected or disappearing media", async () => {
  const directory = await mkdtemp(join(tmpdir(), "makosh-photo-download-"));
  const path = join(directory, "photo.jpg");
  let chatProtected = false;
  let messageProtected = false;
  let disappearing = false;
  let largestPhotoId = 2400;
  const { session, request } = harness((query) => {
    switch (query["@type"]) {
      case "getAuthorizationState": return { "@type": "authorizationStateReady" };
      case "getChat": return { "@type": "chat", id: 42, has_protected_content: chatProtected };
      case "getMessage": return { "@type": "message", chat_id: 42, id: 12, can_be_saved: !messageProtected,
        ...(disappearing ? { self_destruct_type: { "@type": "messageSelfDestructTypeImmediately" } } : {}),
        content: { "@type": "messagePhoto", photo: { "@type": "photo", sizes: [320, 2400].map((width) => ({
          "@type": "photoSize", width, height: width, photo: { "@type": "file", id: width === 2400 ? largestPhotoId : width, size: width === 2400 ? 1024 * 1024 : 1024 },
        })) } },
      };
      case "downloadFile": return { "@type": "file", id: query.file_id,
        local: { "@type": "localFile", path, is_downloading_completed: true } };
      default: throw new Error("Unexpected fixture query");
    }
  }, undefined, directory);
  try {
    await writeFile(path, Buffer.from([0xff, 0xd8, 0xff, 0xd9]));
    await vi.waitFor(() => expect(session.status().state).toBe("ready"));
    const download = await session.document("42", "12");
    expect(download).toMatchObject({ name: "telegram-photo-12.jpg", size: 4 });
    expect(new Uint8Array(await new Response(download.body).arrayBuffer())).toEqual(Uint8Array.of(255, 216, 255, 217));
    expect(request.mock.calls.map(([query]) => query)).toContainEqual(expect.objectContaining({ "@type": "downloadFile", file_id: 2400 }));
    const drag = await session.photoDragReference("42", "12");
    expect(drag).toMatchObject({ id: 2400, name: "telegram-photo-12.jpg" });
    const signal = new AbortController().signal;
    largestPhotoId = 2401;
    await expect(session.photoDragDocument("42", "12", drag.id, signal)).rejects.toThrow("photo changed");
    largestPhotoId = 2400;
    chatProtected = true;
    await expect(session.document("42", "12")).rejects.toThrow("unavailable");
    await expect(session.photoDragDocument("42", "12", drag.id, signal)).rejects.toThrow("unavailable");
    await expect(session.recognizePhotoText("42", "12", "large", "0".repeat(64))).resolves.toBeNull();
    chatProtected = false;
    messageProtected = true;
    await expect(session.document("42", "12")).rejects.toThrow("unavailable");
    await expect(session.recognizePhotoText("42", "12", "large", "0".repeat(64))).resolves.toBeNull();
    messageProtected = false;
    disappearing = true;
    await expect(session.document("42", "12")).rejects.toThrow("unavailable");
    await expect(session.photoDragReference("42", "12")).rejects.toThrow("unavailable");
    await expect(session.recognizePhotoText("42", "12", "large", "0".repeat(64))).resolves.toBeNull();
    expect(request.mock.calls.filter(([query]) => query["@type"] === "downloadFile")).toHaveLength(1);
    disappearing = false;
    await writeFile(path, Buffer.concat([Buffer.from([0xff, 0xd8, 0xff]), Buffer.alloc(9)]));
    await expect(session.recognizePhotoText("42", "12", "large", "0".repeat(64))).resolves.toBeNull();
    expect(request.mock.calls.filter(([query]) => query["@type"] === "downloadFile")).toHaveLength(2);
  } finally {
    await session.close();
    await rm(directory, { recursive: true, force: true });
  }
});

test("cancels all members of a scheduled album only when the exact queue still matches", async () => {
  const row = (id: number, album: string) => ({
    "@type": "message", id, chat_id: -42, is_outgoing: true, media_album_id: album,
    topic_id: { "@type": "messageTopicForum", forum_topic_id: 17 },
    scheduling_state: { "@type": "messageSchedulingStateSendAtDate", send_date: 1980000000 },
  });
  let queued = [row(31, "99"), row(23, "77"), row(22, "77")];
  const { session, request } = harness((query) => {
    switch (query["@type"]) {
      case "getAuthorizationState": return { "@type": "authorizationStateReady" };
      case "getChatScheduledMessages": return { "@type": "messages", messages: queued };
      case "deleteMessages":
        queued = queued.filter(({ id }) => !(query.message_ids as number[]).includes(id));
        return { "@type": "ok" };
      default: throw new Error("Unexpected fixture query");
    }
  });
  try {
    await vi.waitFor(() => expect(session.status().state).toBe("ready"));
    const cancel = (members: string[], topicId = 17) =>
      session.cancelScheduledMessage("-42", "22", topicId, { id: "77", members });
    await expect(cancel(["22", "31"])).resolves.toBe(false);
    await expect(cancel(["22", "23", "24"])).resolves.toBe(false);
    await expect(cancel(["22", "23"], 18)).resolves.toBe(false);
    expect(request.mock.calls.some(([query]) => query["@type"] === "deleteMessages")).toBe(false);
    await expect(cancel(["22", "23"])).resolves.toBe(true);
    expect(request.mock.calls.filter(([query]) => query["@type"] === "deleteMessages")).toEqual([[
      { "@type": "deleteMessages", chat_id: -42, message_ids: [23, 22], revoke: true },
    ]]);
    expect(queued.map(({ id }) => id)).toEqual([31]);
  } finally { await session.close(); }
});

test("forwards an exact unprotected album in order and treats a partial delivery as unknown", async () => {
  const row = (id: number) => ({ "@type": "message", id, chat_id: -42, media_album_id: "77",
    can_be_forwarded: true, has_protected_content: id === 13 && protectedMember });
  let protectedMember = false;
  let partial = false;
  let copyAllowed = false;
  const scheduledAt = Math.floor(Date.now() / 1000) + 3600;
  const target = { id: "-43", name: "Album destination fixture", kind: "Channel" as const };
  const { session, request } = harness((query) => {
    switch (query["@type"]) {
      case "getAuthorizationState": return { "@type": "authorizationStateReady" };
      case "getChat": return query.chat_id === -42 ? { "@type": "chat", id: -42 }
        : query.chat_id === 43 ? { "@type": "chat", id: 43, title: "Private fixture", type: { "@type": "chatTypePrivate", user_id: 43 } }
        : { "@type": "chat", id: -43, title: target.name, type: { "@type": "chatTypeSupergroup", is_channel: true } };
      case "getMe": return { "@type": "user", id: 7 };
      case "getUser": return { "@type": "user", id: 43, type: { "@type": "userTypeRegular" },
        status: { "@type": "userStatusOffline", was_online: 1700000000 } };
      case "getChatHistory": return { "@type": "messages", messages: [row(14), row(13), row(12)] };
      case "getMessage": return row(Number(query.message_id));
      case "getMessageProperties": return { "@type": "messageProperties", can_be_forwarded: true, can_be_copied: copyAllowed };
      case "forwardMessages": return { "@type": "messages", messages: [21, 22, 23].map((id) => partial && id === 22
        ? null : { "@type": "message", id, chat_id: query.chat_id, media_album_id: "88", scheduling_state: (query.options as TdObject | undefined)?.scheduling_state }) };
      default: throw new Error("Unexpected fixture query");
    }
  });
  try {
    await vi.waitFor(() => expect(session.status().state).toBe("ready"));
    const forward = (members: string[]) => session.forwardMessage("-42", "12", target, { id: "77", members });
    await expect(forward(["12", "13"])).resolves.toBe("refused");
    protectedMember = true;
    await expect(forward(["12", "13", "14"])).resolves.toBe("refused");
    expect(request.mock.calls.some(([query]) => query["@type"] === "forwardMessages")).toBe(false);
    protectedMember = false;
    await expect(forward(["14", "12", "13"])).resolves.toBe("sent");
    const copy = () => session.forwardMessage("-42", "12", target, { id: "77", members: ["12", "13", "14"] },
      { hideSender: true, removeCaption: true }, { silent: true, at: scheduledAt });
    await expect(copy()).resolves.toBe("refused");
    copyAllowed = true;
    await expect(copy()).resolves.toBe("sent");
    expect(request.mock.calls.filter(([query]) => query["@type"] === "forwardMessages").at(-1)?.[0].options).toEqual({
      "@type": "messageSendOptions", disable_notification: true,
      scheduling_state: { "@type": "messageSchedulingStateSendAtDate", send_date: scheduledAt },
    });
    partial = true;
    await expect(forward(["12", "13", "14"])).resolves.toBe("unknown");
    expect(request.mock.calls.filter(([query]) => query["@type"] === "forwardMessages").map(([query]) => [query.message_ids, query.send_copy, query.remove_caption]))
      .toEqual([[[12, 13, 14], false, false], [[12, 13, 14], true, true], [[12, 13, 14], false, false]]);
    partial = false;
    const online = schemas.forwardMessage.input.parse({ id: "-42", messageId: "12",
      target: { id: "43", name: "Private fixture", kind: "Direct message" },
      album: { id: "77", members: ["12", "13", "14"] }, delivery: { whenOnline: true } });
    await expect(session.forwardMessage(online.id, online.messageId, online.target, online.album, undefined, online.delivery))
      .resolves.toBe("sent");
    expect(request).toHaveBeenLastCalledWith(expect.objectContaining({ "@type": "forwardMessages", message_ids: [12, 13, 14],
      options: { "@type": "messageSendOptions", disable_notification: false,
        scheduling_state: { "@type": "messageSchedulingStateSendWhenOnline" } } }));
  } finally { await session.close(); }
});

test("lists Telegram Saved Messages sources and filters history to the exact source and account", async () => {
  const topic = (id: number, order: string, type: TdObject) => ({
    "@type": "updateSavedMessagesTopic", topic: { "@type": "savedMessagesTopic", id, order, type },
  });
  const row = (id: number, sourceId: number, chatId = 42) => ({
    "@type": "message", id, chat_id: chatId, is_outgoing: true, date: 1700000000 + id,
    topic_id: { "@type": "messageTopicSavedMessages", saved_messages_topic_id: sourceId },
    content: { "@type": "messageText", text: { "@type": "formattedText", text: "Saved source fixture" } },
  });
  const { session, request, update } = harness((query) => {
    switch (query["@type"]) {
      case "getAuthorizationState": return { "@type": "authorizationStateReady" };
      case "loadSavedMessagesTopics": return { "@type": "ok" };
      case "toggleSavedMessagesTopicIsPinned": return { "@type": "ok" };
      case "setPinnedSavedMessagesTopics": return { "@type": "ok" };
      case "getSavedMessagesTags": return { "@type": "savedMessagesTags", tags: [
        { "@type": "savedMessagesTag", tag: { "@type": "reactionTypeEmoji", emoji: "⭐" }, label: "Later", count: 2 },
        { "@type": "savedMessagesTag", tag: { "@type": "reactionTypeCustomEmoji", custom_emoji_id: "9007199254740999" }, label: "", count: 1 },
        { "@type": "savedMessagesTag", tag: { "@type": "reactionTypePaid" }, label: "", count: 1 },
      ] };
      case "searchSavedMessages": return { "@type": "foundChatMessages", next_from_message_id: 6,
        messages: [row(7, -97), row(6, 42), row(5, -97, 43)] };
      case "getChat": return { "@type": "chat", id: query.chat_id, title: "Source fixture" };
      case "getMe": return { "@type": "user", id: 42 };
      case "getSavedMessagesTopicHistory": return { "@type": "messages", messages: [
        row(4, -97), row(6, -97), row(5, 42), row(3, -97, 43), row(4, -97),
      ] };
      case "getSavedMessagesTopicMessageByDate": {
        if (query.date === 1) throw new TdError(404);
        return row(6, query.date === 1700000006 ? -97 : 42);
      }
      case "searchChatMessages": return { "@type": "foundChatMessages", next_from_message_id: 6,
        messages: (query.filter as { "@type"?: string } | undefined)?.["@type"] === "searchMessagesFilterUrl"
          ? [row(13, -97), row(12, 42)]
          : query.filter
          ? [{ ...row(12, -97), is_pinned: true }, ...["messagePhoto", "messageVideo", "messageAudio", "messageVoiceNote", "messageVideoNote", "messageAnimation"]
            .map((type, index) => ({ ...row(11 - index, -97), content: { "@type": type } }))]
          : [row(7, -97), row(6, -97), row(5, 42), row(4, -97, 43), row(6, -97)] };
      default: throw new Error("Unexpected fixture query");
    }
  });
  try {
    await vi.waitFor(() => expect(session.status().state).toBe("ready"));
    update(topic(42, "9007199254740992", { "@type": "savedMessagesTopicTypeMyNotes" }));
    update(topic(-97, "9007199254740993", { "@type": "savedMessagesTopicTypeSavedFromChat", chat_id: -97 }));
    expect((await session.savedSources(0)).sources).toEqual([
      { id: "-97", title: "Source fixture", pinned: false, chatId: "-97" }, { id: "42", title: "My notes", pinned: false },
    ]);
    await expect(session.setSavedSourcePinned("-97", false, true)).resolves.toBe("changed");
    await expect(session.setSavedSourcePinned("-98", true, false)).resolves.toBe("refused");
    await expect(session.setSavedSourcePinned("-97", true, false)).resolves.toBe("updated");
    expect(request.mock.calls.filter(([query]) => query["@type"] === "toggleSavedMessagesTopicIsPinned")).toEqual([[
      { "@type": "toggleSavedMessagesTopicIsPinned", saved_messages_topic_id: -97, is_pinned: true },
    ]]);
    update({ "@type": "updateSavedMessagesTopic", topic: {
      "@type": "savedMessagesTopic", id: 42, order: "9007199254740994", is_pinned: true,
      type: { "@type": "savedMessagesTopicTypeMyNotes" },
    } });
    update({ "@type": "updateSavedMessagesTopic", topic: {
      "@type": "savedMessagesTopic", id: -97, order: "9007199254740995", is_pinned: true,
      type: { "@type": "savedMessagesTopicTypeSavedFromChat", chat_id: -97 },
    } });
    await expect(session.reorderSavedSources(["-97", "42"], ["42", "-97"])).resolves.toBe("changed");
    await expect(session.reorderSavedSources(["42", "42"], ["-97", "42"])).resolves.toBe("refused");
    await expect(session.reorderSavedSources(["42", "-97"], ["-97", "42"])).resolves.toBe("updated");
    expect(request.mock.calls.filter(([query]) => query["@type"] === "setPinnedSavedMessagesTopics")).toEqual([[
      { "@type": "setPinnedSavedMessagesTopics", saved_messages_topic_ids: [42, -97] },
    ]]);
    const page = await session.savedSourceHistory("-97", "6");
    expect(page.messages.map(({ id }) => id)).toEqual(["4"]);
    expect(page.before).toBe("4");
    const byDate = await session.savedSourceHistory("-97", undefined, undefined, 1700000006);
    expect(byDate.messages.map(({ id }) => id)).toEqual(["6", "4"]);
    expect(byDate.before).toBe("4");
    await expect(session.savedSourceHistory("-97", undefined, undefined, 1)).resolves.toEqual({ messages: [], before: null });
    await expect(session.savedSourceHistory("-97", undefined, undefined, 1700000007)).rejects.toThrow("date anchor");
    const matches = await session.savedSourceHistory("-97", "6", "fixture");
    expect(matches.messages.map(({ id }) => id)).toEqual(["6"]);
    expect(matches.before).toBeNull();
    expect((await session.savedSourceHistory("-97", undefined, "fixture")).before).toBe("6");
    expect(request.mock.calls.find(([query]) => query["@type"] === "searchChatMessages")?.[0]).toEqual({
      "@type": "searchChatMessages", chat_id: 42, query: "fixture", from_message_id: 6, offset: 0, limit: 40,
      topic_id: { "@type": "messageTopicSavedMessages", saved_messages_topic_id: -97 },
    });
    const photos = await session.savedSourceHistory("-97", undefined, undefined, undefined, "photo");
    expect(photos.messages.map(({ id }) => id)).toEqual(["11"]);
    expect(photos.before).toBe("6");
    expect(request.mock.calls.find(([query]) => query["@type"] === "searchChatMessages" && query.filter)?.[0]).toMatchObject({ query: "", filter: { "@type": "searchMessagesFilterPhoto" },
      topic_id: { "@type": "messageTopicSavedMessages", saved_messages_topic_id: -97 } });
    for (const [filter, type, ids] of [
      ["video", "Video", ["10"]], ["audio", "Audio", ["9"]], ["voiceVideoNotes", "VoiceAndVideoNote", ["8", "7"]],
      ["gif", "Animation", ["6"]], ["pinned", "Pinned", ["12"]],
      ["link", "Url", ["13"]],
    ] as const) {
      const page = await session.savedSourceHistory("-97", undefined, undefined, undefined, filter);
      expect(page.messages.map(({ id }) => id)).toEqual(ids);
      expect(request.mock.calls.some(([query]) => query["@type"] === "searchChatMessages"
        && (query.filter as { "@type"?: string } | undefined)?.["@type"] === `searchMessagesFilter${type}`)).toBe(true);
    }
    await expect(session.savedSourceHistory("-98")).rejects.toThrow("unavailable");
    const tags = await session.savedSourceTags("-97");
    expect(tags).toEqual([
      { type: { kind: "emoji", emoji: "⭐" }, label: "Later", count: 2 },
      { type: { kind: "custom", id: "9007199254740999" }, label: "", count: 1 },
    ]);
    const tagged = await session.savedSourceHistory("-97", undefined, "fixture", undefined, undefined, tags[1]!.type);
    expect(tagged.messages.map(({ id }) => id)).toEqual(["7"]);
    expect(tagged.before).toBe("6");
    expect(request.mock.calls.find(([query]) => query["@type"] === "searchSavedMessages")?.[0]).toMatchObject({
      saved_messages_topic_id: -97, query: "fixture", tag: { "@type": "reactionTypeCustomEmoji", custom_emoji_id: "9007199254740999" },
    });
  } finally { await session.close(); }
});

test("reports only the reviewed eligible chat and follows Telegram report options", async () => {
  let title = "Fixture channel";
  let eligible = false;
  const { session, request } = harness((query) => {
    switch (query["@type"]) {
      case "getAuthorizationState": return { "@type": "authorizationStateReady" };
      case "getChat": return { "@type": "chat", id: -42, title, can_be_reported: eligible };
      case "reportChat":
        if (query.option_id === "") return { "@type": "reportChatResultOptionRequired", title: "Reason",
          options: [{ "@type": "reportOption", id: "YQ==", text: "Fixture reason" }] };
        if (query.option_id === "YQ==") return { "@type": "reportChatResultTextRequired", option_id: "Yg==", is_optional: false };
        return { "@type": "reportChatResultOk" };
      default: throw new Error("Unexpected test query");
    }
  });
  try {
    await vi.waitFor(() => expect(session.status().state).toBe("ready"));
    await expect(session.canReportChat("-42")).resolves.toBe(false);
    await expect(session.reportChat("-42", title, { action: "start" })).resolves.toEqual({ state: "unavailable" });
    eligible = true;
    await expect(session.canReportChat("-42")).resolves.toBe(true);
    await expect(session.reportChat("-42", title, { action: "start" })).resolves.toEqual({
      state: "options", title: "Reason", options: [{ id: "YQ==", label: "Fixture reason" }],
    });
    await expect(session.reportChat("-42", title, { action: "choose", option: "YQ==" }))
      .resolves.toEqual({ state: "details", id: "Yg==", optional: false });
    title = "Renamed fixture";
    await expect(session.reportChat("-42", "Fixture channel", { action: "details", option: "Yg==", text: "Fixture details" }))
      .resolves.toEqual({ state: "unavailable" });
    await expect(session.reportChat("-42", title, { action: "details", option: "Yg==", text: "Fixture details" }))
      .resolves.toEqual({ state: "sent" });
    expect(request.mock.calls.filter(([query]) => query["@type"] === "reportChat").map(([query]) => query)).toEqual([
      { "@type": "reportChat", chat_id: -42, message_ids: [], option_id: "", text: "" },
      { "@type": "reportChat", chat_id: -42, message_ids: [], option_id: "YQ==", text: "" },
      { "@type": "reportChat", chat_id: -42, message_ids: [], option_id: "Yg==", text: "Fixture details" },
    ]);
  } finally { await session.close(); }
});

test("checks every selected message again before proceeding with a Telegram report", async () => {
  let blocked = 0;
  let ephemeral = 0;
  const start = { action: "start" as const };
  const { session, request } = harness((query) => {
    switch (query["@type"]) {
      case "getAuthorizationState": return { "@type": "authorizationStateReady" };
      case "getChat": return { "@type": "chat", id: -42, title: "Fixture group", can_be_reported: false };
      case "getMessage": return { "@type": "message", chat_id: -42, id: query.message_id,
        ...(query.message_id === ephemeral ? { self_destruct_type: { "@type": "messageSelfDestructTypeImmediately" } } : {}) };
      case "getMessageProperties": return { "@type": "messageProperties", can_report_chat: query.message_id !== blocked };
      case "reportChat": return query.option_id === ""
        ? { "@type": "reportChatResultOptionRequired", options: [{ "@type": "reportOption", id: "YQ==", text: "Fixture reason" }] }
        : { "@type": "reportChatResultOk" };
      default: throw new Error("Unexpected test query");
    }
  });
  try {
    await vi.waitFor(() => expect(session.status().state).toBe("ready"));
    const ids = ["7", "9"];
    const next = { action: "choose" as const, option: "YQ==" };
    await expect(session.canReportChat("-42")).resolves.toBe(false);
    await expect(session.reportChat("-42", "Fixture group", start, ids)).resolves.toMatchObject({ state: "options" });
    blocked = 9;
    await expect(session.reportChat("-42", "Fixture group", next, ids)).resolves.toEqual({ state: "unavailable" });
    blocked = 0;
    ephemeral = 9;
    await expect(session.reportChat("-42", "Fixture group", next, ids)).resolves.toEqual({ state: "unavailable" });
    await expect(session.reportChat("-42", "Fixture group", next, ["9"])).resolves.toEqual({ state: "sent" });
    expect(request.mock.calls.filter(([query]) => query["@type"] === "reportChat").map(([query]) => query)).toEqual([
      { "@type": "reportChat", chat_id: -42, message_ids: [7, 9], option_id: "", text: "" },
      { "@type": "reportChat", chat_id: -42, message_ids: [9], option_id: "YQ==", text: "" },
    ]);
  } finally { await session.close(); }
});

